function clampInt(v: number, lo: number, hi: number): number {

    if (v < lo) return lo

    if (v > hi) return hi

    return v | 0

}





function worldPixelWidth(): number {

    return WORLD_TILES_W * WORLD_TILE_SIZE;

}



function worldPixelHeight(): number {

    return WORLD_TILES_H * WORLD_TILE_SIZE;

}



function worldCenter(): { x: number; y: number } {

    return {

        x: worldPixelWidth() / 2,

        y: worldPixelHeight() / 2

    };

}



function makeBaseStats(baseTimeMs: number) {

    const stats: number[] = []

    for (let i = 0; i < STAT.LEN; i++) stats[i] = 0

    stats[STAT.DAMAGE_MULT] = 100

    stats[STAT.MOVE_DURATION] = baseTimeMs

    return stats

}



function applyAxisWeight(raw: number, weightX1000: number): number {

    const r = raw | 0

    const w = weightX1000 | 0

    if (r <= 0 || w <= 0) return 0

    return Math.idiv(r * w, 1000) | 0

}



function asymptoticBonusPct(points: number, maxBonusPct: number, halfPoints: number): number {

    const p = points | 0

    const maxPct = maxBonusPct | 0

    let half = halfPoints | 0

    if (p <= 0 || maxPct <= 0) return 0

    if (half <= 0) half = 1

    return Math.idiv(maxPct * p, p + half) | 0

}



function intellectPulsePeriodMs(perPulseDamage: number, tTime: number): number {

    let dmg = perPulseDamage | 0

    let time = tTime | 0

    if (dmg < 0) dmg = 0

    if (time < 0) time = 0



    let effective = (dmg - time) | 0

    if (effective < 0) effective = 0



    let linear = (effective * BALANCE.MOVES.INTELLECT.PULSE_PERIOD_PER_DMG_MS) | 0

    if (linear < 0) linear = 0



    const maxMs = BALANCE.MOVES.INTELLECT.PULSE_PERIOD_MAX_MS | 0

    const softStart = Math.idiv(maxMs, 2) | 0



    let period = linear

    if (period > softStart && softStart > 0) {

        const excess = (period - softStart) | 0

        const soft = Math.idiv(excess * softStart, excess + softStart) | 0

        period = (softStart + soft) | 0

    }



    const minMs = BALANCE.MOVES.INTELLECT.PULSE_PERIOD_MIN_MS | 0

    if (period < minMs) period = minMs

    if (period > maxMs) period = maxMs

    return period | 0

}



function getBaseMoveDurationMs(button: string, family: number) {

    const baseCfg = BALANCE.MOVES.BASE_DURATION_MS

    let base = baseCfg.DEFAULT

    if (family == FAMILY.STRENGTH) base = baseCfg.STRENGTH

    else if (family == FAMILY.AGILITY) base = baseCfg.AGILITY

    else if (family == FAMILY.INTELLECT) base = baseCfg.INTELLECT

    else if (family == FAMILY.HEAL) base = baseCfg.WISDOM

    if (button == "A+B") base += baseCfg.AB_BONUS

    return base

}



function getBasePower(family: number) {

    const base = BALANCE.MOVES.BASE_POWER

    if (family == FAMILY.STRENGTH) return base.STRENGTH

    if (family == FAMILY.AGILITY) return base.AGILITY

    if (family == FAMILY.INTELLECT) return base.INTELLECT

    if (family == FAMILY.HEAL) return base.WISDOM

    return base.DEFAULT

}



// Map numeric anim IDs to string keys (used by callHeroAnim)

function animIdToKey(id: number) {

    if (id == ANIM.ID.A) return ANIM.A

    if (id == ANIM.ID.B) return ANIM.B

    if (id == ANIM.ID.AB) return ANIM.AB

    return ANIM.IDLE

}



function distanceTo(a: Sprite, b: Sprite): number {

    if (!a || !b) return 99999

    const dx = b.x - a.x, dy = b.y - a.y

    return Math.sqrt(dx * dx + dy * dy)

}



function distSqPointToSprite(px: number, py: number, s: Sprite): number { const dx = px - s.x, dy = py - s.y; return dx * dx + dy * dy }



function worldPointAlongRay(ax: number, ay: number, nx: number, ny: number, s: number) { return [ax + nx * s, ay + ny * s] }



// Tint helper: remap one color index to another

function tintImageReplace(imgBase: Image, fromColor: number, toColor: number): Image {

    const w = imgBase.width, h = imgBase.height

    const out = image.create(w, h)

    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {

        const p = imgBase.getPixel(x, y)

        out.setPixel(x, y, p == fromColor ? toColor : p)

    }

    return out

}





const _INT_SPELL_IMG_CACHE: { [k: string]: Image } = Object.create(null)



function _getIntSpellImg(isDetonating: boolean, radius: number): Image {

    const g: any = globalThis as any



    // Self-initialize global cache + counters so this can never throw ReferenceError

    // (and so cache survives hot reload / multiple module instances).

    let cache: Map<string, Image> | null = null

    if (g.__intSpellImgCache instanceof Map) {

        cache = g.__intSpellImgCache as Map<string, Image>

    } else {

        // Fall back to the file-scope cache if present; otherwise create a new Map.

        cache = (typeof _INT_SPELL_IMG_CACHE !== "undefined" && _INT_SPELL_IMG_CACHE instanceof Map)

            ? (_INT_SPELL_IMG_CACHE as Map<string, Image>)

            : new Map<string, Image>()

        g.__intSpellImgCache = cache

    }



    if (typeof g.__intSpellImgCache_hit !== "number") g.__intSpellImgCache_hit = 0

    if (typeof g.__intSpellImgCache_miss !== "number") g.__intSpellImgCache_miss = 0



    // Sanitize radius (must be >= 1)

    const r = Math.max(1, (radius | 0)) | 0



    // Cache key: detonating state + radius

    const cacheKey = `${isDetonating ? 1 : 0}|${r}`

    const cached = cache.get(cacheKey)

    if (cached) {

        g.__intSpellImgCache_hit = ((g.__intSpellImgCache_hit | 0) + 1) | 0

        return cached

    }

    g.__intSpellImgCache_miss = ((g.__intSpellImgCache_miss | 0) + 1) | 0



    const w = ((r * 2) + 1) | 0

    const h = w

    const cx = r | 0

    const cy = r | 0

    const out = image.create(w, h)



    // Keep your existing palette intent:

    // - normal: green-ish body + brighter rim

    // - detonating: brighter rim/body swap

    const colBase = isDetonating ? 10 : 4

    const colRim = isDetonating ? 2 : 7



    const rr = (r * r) | 0

    const rInner = Math.max(0, (r - 1) | 0) | 0

    const rrInner = (rInner * rInner) | 0



    for (let y = 0; y < h; y++) {

        const dy = (y - cy) | 0

        const dy2 = (dy * dy) | 0

        for (let x = 0; x < w; x++) {

            const dx = (x - cx) | 0

            const d2 = (dx * dx + dy2) | 0



            // Fill disk

            if (d2 <= rr) {

                out.setPixel(x, y, colBase)

            }



            // Rim band (1px ring)

            if (d2 <= rr && d2 >= rrInner) {

                out.setPixel(x, y, colRim)

            }

        }

    }



    cache.set(cacheKey, out)

    return out

}







function getAimVectorForHero(heroIndex: number): number[] {

    // Use MakeCode-style per-player d-pad buttons (works even if hero movement is locked)

    let p: any = controller.player1

    if (heroIndex === 1) p = controller.player2

    else if (heroIndex === 2) p = controller.player3

    else if (heroIndex === 3) p = controller.player4



    // Defensive fallback (should never hit if controller is present)

    if (!p || !p.left || !p.right || !p.up || !p.down) {

        let dx0 = heroFacingX[heroIndex] || 0

        let dy0 = heroFacingY[heroIndex] || 0

        if (dx0 === 0 && dy0 === 0) { dx0 = 1; dy0 = 0 }

        return [dx0, dy0]

    }



    const left  = p.left.isPressed() ? 1 : 0

    const right = p.right.isPressed() ? 1 : 0

    const up    = p.up.isPressed() ? 1 : 0

    const down  = p.down.isPressed() ? 1 : 0



    let dx = (right - left) | 0

    let dy = (down - up) | 0



    // If no d-pad held, keep last facing so spell continues smoothly.

    if (dx === 0 && dy === 0) {

        dx = heroFacingX[heroIndex] || 0

        dy = heroFacingY[heroIndex] || 0

        if (dx === 0 && dy === 0) { dx = 1; dy = 0 }

    }



    return [dx, dy]

}



function r2(v: number) { return Math.round(v * 100) / 100 }

function r3(v: number) { return Math.round(v * 1000) / 1000 }





// --------------------------------------------------------------

// MOD BANK: unlimited additive effectors by bucket+label

// - Store unlimited entries (arrays) in JS memory (safe)

// - Cache sums per hero+bucket for O(1) reads in hot paths

// - Apply by modifying traits[] before calculateMoveStatsForFamily()

// --------------------------------------------------------------



type ModEntry = { label: string, value: number }



// Buckets (POC: family-only damage axis = TRAIT1)

const MOD_BUCKET_STR_DMG = "STR_DMG"

const MOD_BUCKET_AGI_DMG = "AGI_DMG"

const MOD_BUCKET_INT_DMG = "INT_DMG"

const MOD_BUCKET_SUP_DMG = "SUP_DMG"





// --- ADD: trait mod buckets beyond damage (Trait2/3/4) ---

const MOD_BUCKET_STR_REACH = "str.reach";

const MOD_BUCKET_STR_TIME = "str.time";

const MOD_BUCKET_STR_STATUS = "str.status";



const MOD_BUCKET_AGI_REACH = "agi.reach";

const MOD_BUCKET_AGI_TIME = "agi.time";

const MOD_BUCKET_AGI_STATUS = "agi.status";



const MOD_BUCKET_INT_REACH = "int.reach";

const MOD_BUCKET_INT_TIME = "int.time";

const MOD_BUCKET_INT_STATUS = "int.status";



const MOD_BUCKET_SUP_REACH = "sup.reach";

const MOD_BUCKET_SUP_TIME = "sup.time";

const MOD_BUCKET_SUP_STATUS = "sup.status";





// Lists live in memory (unbounded)

const _heroMods: { [heroIndex: number]: { [bucket: string]: ModEntry[] } } = {}

// Cached sums (fast reads)

const _heroModSums: { [heroIndex: number]: { [bucket: string]: number } } = {}



function _ensureHeroBucket(heroIndex: number, bucket: string): ModEntry[] {

    let h = _heroMods[heroIndex]

    if (!h) { h = {}; _heroMods[heroIndex] = h }

    let arr = h[bucket]

    if (!arr) { arr = []; h[bucket] = arr }

    return arr

}



function _recomputeHeroBucketSum(heroIndex: number, bucket: string): number {

    const arr = _ensureHeroBucket(heroIndex, bucket)

    let sum = 0

    for (let i = 0; i < arr.length; i++) sum += (arr[i].value | 0)



    let s = _heroModSums[heroIndex]

    if (!s) { s = {}; _heroModSums[heroIndex] = s }

    s[bucket] = sum

    return sum

}



function heroModGet(heroIndex: number, bucket: string, label: string): number {

    const arr = _ensureHeroBucket(heroIndex, bucket)

    for (let i = 0; i < arr.length; i++) if (arr[i].label === label) return arr[i].value | 0

    return 0

}



// Sets/overwrites the value for a label (best for "shop level", "relic id", etc.)

function heroModSet(heroIndex: number, bucket: string, label: string, value: number): number {

    const arr = _ensureHeroBucket(heroIndex, bucket)

    const v = value | 0



    for (let i = 0; i < arr.length; i++) {

        if (arr[i].label === label) {

            arr[i].value = v

            return _recomputeHeroBucketSum(heroIndex, bucket)

        }

    }



    arr.push({ label, value: v })

    return _recomputeHeroBucketSum(heroIndex, bucket)

}



function heroModRemove(heroIndex: number, bucket: string, label: string): number {

    const arr = _ensureHeroBucket(heroIndex, bucket)

    for (let i = 0; i < arr.length; i++) {

        if (arr[i].label === label) { arr.removeAt(i); break }

    }

    return _recomputeHeroBucketSum(heroIndex, bucket)

}



function heroModSum(heroIndex: number, bucket: string): number {

    const s = _heroModSums[heroIndex]

    if (s && (bucket in s)) return s[bucket] | 0

    return _recomputeHeroBucketSum(heroIndex, bucket)

}



function heroModDebug(heroIndex: number, bucket: string): string {

    const arr = _ensureHeroBucket(heroIndex, bucket)

    let out = ""

    for (let i = 0; i < arr.length; i++) {

        const e = arr[i]

        if (i) out += " "

        out += `${e.label}:${e.value | 0}`

    }

    return out

}



// --------------------------------------------------------------

// APPLY MODS: POC = add bucket sum to TRAIT1 (damage axis) per family

// --------------------------------------------------------------



function _damageBucketForFamily(family: number): string {

    switch (family | 0) {

        case FAMILY.STRENGTH:  return MOD_BUCKET_STR_DMG

        case FAMILY.AGILITY:   return MOD_BUCKET_AGI_DMG

        case FAMILY.INTELLECT: return MOD_BUCKET_INT_DMG

        case FAMILY.HEAL:      return MOD_BUCKET_SUP_DMG

    }

    return ""

}



// Returns either the original traits array (no change) OR a cloned array with TRAIT1 modified.

function _modBucketForFamilyAndTraitIndex(family: number, outTraitIndex: number): string | null {

    const f = family | 0;

    const t = outTraitIndex | 0;



    if (t === OUT.TRAIT1) return _damageBucketForFamily(f);



    if (f === FAMILY.STRENGTH) {

        if (t === OUT.TRAIT2) return MOD_BUCKET_STR_REACH;

        if (t === OUT.TRAIT3) return MOD_BUCKET_STR_TIME;

        if (t === OUT.TRAIT4) return MOD_BUCKET_STR_STATUS;

        return MOD_BUCKET_STR_DMG;

    }



    if (f === FAMILY.AGILITY) {

        if (t === OUT.TRAIT2) return MOD_BUCKET_AGI_REACH;

        if (t === OUT.TRAIT3) return MOD_BUCKET_AGI_TIME;

        if (t === OUT.TRAIT4) return MOD_BUCKET_AGI_STATUS;

        return MOD_BUCKET_AGI_DMG;

    }



    if (f === FAMILY.INTELLECT) {

        if (t === OUT.TRAIT2) return MOD_BUCKET_INT_REACH;

        if (t === OUT.TRAIT3) return MOD_BUCKET_INT_TIME;

        if (t === OUT.TRAIT4) return MOD_BUCKET_INT_STATUS;

        return MOD_BUCKET_INT_DMG;

    }



    // support/heal

    if (t === OUT.TRAIT2) return MOD_BUCKET_SUP_REACH;

    if (t === OUT.TRAIT3) return MOD_BUCKET_SUP_TIME;

    if (t === OUT.TRAIT4) return MOD_BUCKET_SUP_STATUS;

    return MOD_BUCKET_SUP_DMG;

}





function applyDamageModsToTraits(hi: number, family: number, traitsEff: MoveTraits): MoveTraits {

    if (!traitsEff) return traitsEff;



    const b1 = _modBucketForFamilyAndTraitIndex(family, OUT.TRAIT1);

    const b2 = _modBucketForFamilyAndTraitIndex(family, OUT.TRAIT2);

    const b3 = _modBucketForFamilyAndTraitIndex(family, OUT.TRAIT3);

    const b4 = _modBucketForFamilyAndTraitIndex(family, OUT.TRAIT4);



    const m1 = b1 ? (heroModSum(hi, b1) | 0) : 0;

    const m2 = b2 ? (heroModSum(hi, b2) | 0) : 0;

    const m3 = b3 ? (heroModSum(hi, b3) | 0) : 0;

    const m4 = b4 ? (heroModSum(hi, b4) | 0) : 0;



    if ((m1 | m2 | m3 | m4) === 0) return traitsEff;



    const out = traitsEff.slice() as MoveTraits;

    out[OUT.TRAIT1] = (out[OUT.TRAIT1] | 0) + m1;

    out[OUT.TRAIT2] = (out[OUT.TRAIT2] | 0) + m2;

    out[OUT.TRAIT3] = (out[OUT.TRAIT3] | 0) + m3;

    out[OUT.TRAIT4] = (out[OUT.TRAIT4] | 0) + m4;

    return out;

}







// ================================================================

// LEVEL-UP FLAT BONUSES (traits) + RELIC MODS (stats)

// ================================================================



// Store per-hero, per-family, per-trait flat bonuses on the hero sprite.

// Key format: "lvlb_<family>_<traitIndex>" (traitIndex uses OUT.TRAIT1..OUT.TRAIT4)

const HERO_LVL_BONUS_KEY_PREFIX = "lvlb_";



function _heroLvlBonusKey(family: number, traitIndex: number): string {

    return HERO_LVL_BONUS_KEY_PREFIX + (family | 0) + "_" + (traitIndex | 0);

}



function getHeroLevelUpTraitBonus(hi: number, family: number, traitIndex: number): number {

    const hero = heroes[hi];

    if (!hero) return 0;

    return (sprites.readDataNumber(hero, _heroLvlBonusKey(family, traitIndex)) | 0);

}



function setHeroLevelUpTraitBonus(hi: number, family: number, traitIndex: number, value: number): void {

    const hero = heroes[hi];

    if (!hero) return;

    sprites.setDataNumber(hero, _heroLvlBonusKey(family, traitIndex), (value | 0));

}



// Post-calc stat modifier hook for relics.

// For now: no-op. Later: this is where relics rewrite stats[] (and/or append metadata).

function applyRelicModsToStats(

    hi: number,

    family: number,

    button: string,

    traitsEff: MoveTraits,

    stats: number[]

): number[] {

    const hero = heroes[hi]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return stats



    // Work on a copy so relic logic can't accidentally mutate shared arrays.

    const statsCopy = Array.isArray(stats) ? stats.slice() : []



    const ctx: RelicModifyMoveStatsContext = {

        now: game.runtime() | 0,

        hi: hi | 0,

        hero,

        family: family | 0,

        button: String(button || ""),

        traitsEff,

        stats: statsCopy,

    }



    try {

        relic_modifyMoveStats(ctx)

    } catch { }



    // Allow handlers to replace ctx.stats entirely, but keep it safe.

    const out = (ctx && Array.isArray(ctx.stats)) ? ctx.stats : statsCopy

    return out

}





// ================================================================

// LEVEL-UP SPENDING (engine API; UI can call via globals)

// ================================================================



const LVLUP_AXIS_RANK_MAX = BALANCE.LEVEL.AXIS_RANK_MAX



// Flat bonuses derived from axis rank (rank 0..4).

// If you later want rank->bonus to be nonlinear, change ONLY this table.

const LVLUP_AXIS_BONUS_BY_RANK: number[] = BALANCE.LEVEL.AXIS_BONUS_BY_RANK



// HP/Mana picks (each costs 1 lvlPt)

const HERO_LVLUP_HP_PICKS_KEY = "lvlHpPicks"

const HERO_LVLUP_MANA_PICKS_KEY = "lvlManaPicks"



// Tunables

const LVLUP_HP_PER_PICK = BALANCE.LEVEL.HP_PER_PICK

const LVLUP_MANA_PER_PICK = BALANCE.LEVEL.MANA_PER_PICK



// UI-facing per-point bonuses (edit here to tune level-up display values per trait).

const LVLUP_UI_BONUS_BY_KEY: Record<string, number> = {

    dmg: 1,

    reach: 1,

    time: 1,

    status: 1,

    hp: LVLUP_HP_PER_PICK,

    mp: LVLUP_MANA_PER_PICK,

}



function _lvlupBonusFromRank(rankRaw: number): number {

    const r = clampInt(rankRaw | 0, 0, LVLUP_AXIS_RANK_MAX) | 0

    return (LVLUP_AXIS_BONUS_BY_RANK[r] | 0) || 0

}



function getHeroLevelUpAxisRank(hi: number, family: number, traitIndex: number): number {

    // Reuse existing storage (lvlb_<family>_<traitIndex>) but interpret as "rank"

    return clampInt(getHeroLevelUpTraitBonus(hi, family, traitIndex) | 0, 0, LVLUP_AXIS_RANK_MAX) | 0

}



function setHeroLevelUpAxisRank(hi: number, family: number, traitIndex: number, rank: number): void {

    const r = clampInt(rank | 0, 0, LVLUP_AXIS_RANK_MAX) | 0

    setHeroLevelUpTraitBonus(hi, family, traitIndex, r)

}



function getHeroUnspentLevelPts(hi: number): number {

    const hero = heroes[hi]

    if (!hero) return 0

    ensureHeroXpInitialized(hi)

    return sprites.readDataNumber(hero, HERO_XP_DATA.LVL_PTS) | 0

}



function _setHeroUnspentLevelPts(hi: number, pts: number): void {

    const hero = heroes[hi]

    if (!hero) return

    sprites.setDataNumber(hero, HERO_XP_DATA.LVL_PTS, Math.max(0, pts | 0))

}



function trySpendLevelUpPointOnAxis(hi: number, family: number, traitIndex: number): boolean {

    const hero = heroes[hi]

    if (!hero) return false

    ensureHeroXpInitialized(hi)



    let pts = sprites.readDataNumber(hero, HERO_XP_DATA.LVL_PTS) | 0

    if (pts <= 0) return false



    const curRank = getHeroLevelUpAxisRank(hi, family, traitIndex) | 0

    if (curRank >= LVLUP_AXIS_RANK_MAX) return false



    const nextRank = (curRank + 1) | 0

    setHeroLevelUpAxisRank(hi, family, traitIndex, nextRank)



    pts = (pts - 1) | 0

    _setHeroUnspentLevelPts(hi, pts)



    console.log("[LVLUP] axis", {

        hi,

        family,

        traitIndex,

        rankFrom: curRank,

        rankTo: nextRank,

        bonusNow: _lvlupBonusFromRank(nextRank),

        ptsLeft: pts

    })



    return true

}



function trySpendLevelUpPointOnAxisGlobal(hi: number, traitIndex: number): boolean {

    const hero = heroes[hi]

    if (!hero) return false

    ensureHeroXpInitialized(hi)



    // Validate traitIndex (Damage/Reach/Time/Status)

    if (traitIndex < OUT.TRAIT1 || traitIndex > OUT.TRAIT4) return false



    let pts = sprites.readDataNumber(hero, HERO_XP_DATA.LVL_PTS) | 0

    if (pts <= 0) return false



    // Families to apply to (Support may be aliased depending on build)

    const fams: number[] = [

        (FAMILY.STRENGTH | 0),

        (FAMILY.AGILITY | 0),

        (FAMILY.INTELLECT | 0),

        (FAMILY.HEAL | 0),

    ]

    if (typeof (FAMILY as any).SUPPORT === "number") {

        const sup = ((FAMILY as any).SUPPORT | 0)

        if (fams.indexOf(sup) < 0) fams.push(sup)

    }



    // Can we increment at least one family?

    let canAny = false

    let minRank = 999

    let maxRank = -999



    for (let i = 0; i < fams.length; i++) {

        const f = fams[i] | 0

        const r = getHeroLevelUpAxisRank(hi, f, traitIndex) | 0

        if (r < LVLUP_AXIS_RANK_MAX) canAny = true

        if (r < minRank) minRank = r

        if (r > maxRank) maxRank = r

    }



    if (!canAny) return false



    // Increment every family that isn't maxed (still costs only 1 point total)

    let changed = 0

    for (let i = 0; i < fams.length; i++) {

        const f = fams[i] | 0

        const r = getHeroLevelUpAxisRank(hi, f, traitIndex) | 0

        if (r < LVLUP_AXIS_RANK_MAX) {

            setHeroLevelUpAxisRank(hi, f, traitIndex, (r + 1) | 0)

            changed++

        }

    }



    pts = (pts - 1) | 0

    _setHeroUnspentLevelPts(hi, pts)



    console.log("[LVLUP] axisGlobal", {

        hi,

        traitIndex,

        minRankFrom: minRank,

        maxRankFrom: maxRank,

        familiesTouched: changed,

        ptsLeft: pts,

    })



    return true

}



function trySpendLevelUpPointOnCore(hi: number, key: string): boolean {

    const k = (key || "").trim().toLowerCase()



    // Axis keys (global)

    if (k === "damage" || k === "dmg") return trySpendLevelUpPointOnAxisGlobal(hi, OUT.TRAIT1)

    if (k === "reach") return trySpendLevelUpPointOnAxisGlobal(hi, OUT.TRAIT2)

    if (k === "time") return trySpendLevelUpPointOnAxisGlobal(hi, OUT.TRAIT3)

    if (k === "status") return trySpendLevelUpPointOnAxisGlobal(hi, OUT.TRAIT4)



    // HP / MP keys

    if (k === "hp") return trySpendLevelUpPointOnMaxHp(hi)

    if (k === "mp" || k === "mana") return trySpendLevelUpPointOnMaxMana(hi)



    // Future-proof: unknown key

    console.log("[LVLUP] core denied (unknown key)", { hi, key })

    return false

}



function trySpendLevelUpPointOnMaxHp(hi: number): boolean {

    const hero = heroes[hi]

    if (!hero) return false

    ensureHeroXpInitialized(hi)



    let pts = sprites.readDataNumber(hero, HERO_XP_DATA.LVL_PTS) | 0

    if (pts <= 0) return false



    let picks = sprites.readDataNumber(hero, HERO_LVLUP_HP_PICKS_KEY) | 0

    picks = (picks + 1) | 0

    sprites.setDataNumber(hero, HERO_LVLUP_HP_PICKS_KEY, picks)



    const add = LVLUP_HP_PER_PICK | 0



    let maxHp = sprites.readDataNumber(hero, HERO_DATA.MAX_HP) | 0

    if (maxHp <= 0) maxHp = 1

    maxHp = (maxHp + add) | 0

    sprites.setDataNumber(hero, HERO_DATA.MAX_HP, maxHp)



    let hp = sprites.readDataNumber(hero, HERO_DATA.HP) | 0

    hp = (hp + add) | 0

    sprites.setDataNumber(hero, HERO_DATA.HP, hp)



    updateHeroHPBar(hi)



    pts = (pts - 1) | 0

    _setHeroUnspentLevelPts(hi, pts)



    console.log("[LVLUP] maxHp", { hi, add, picks, maxHp, hp, ptsLeft: pts })

    return true

}



function trySpendLevelUpPointOnMaxMana(hi: number): boolean {

    const hero = heroes[hi]

    if (!hero) return false

    ensureHeroXpInitialized(hi)



    let pts = sprites.readDataNumber(hero, HERO_XP_DATA.LVL_PTS) | 0

    if (pts <= 0) return false



    let picks = sprites.readDataNumber(hero, HERO_LVLUP_MANA_PICKS_KEY) | 0

    picks = (picks + 1) | 0

    sprites.setDataNumber(hero, HERO_LVLUP_MANA_PICKS_KEY, picks)



    const add = LVLUP_MANA_PER_PICK | 0



    let maxMana = sprites.readDataNumber(hero, HERO_DATA.MAX_MANA) | 0

    if (maxMana <= 0) maxMana = 1

    maxMana = (maxMana + add) | 0

    sprites.setDataNumber(hero, HERO_DATA.MAX_MANA, maxMana)



    let mana = sprites.readDataNumber(hero, HERO_DATA.MANA) | 0

    mana = (mana + add) | 0

    sprites.setDataNumber(hero, HERO_DATA.MANA, mana)



    updateHeroManaBar(hi)



    pts = (pts - 1) | 0

    _setHeroUnspentLevelPts(hi, pts)



    console.log("[LVLUP] maxMana", { hi, add, picks, maxMana, mana, ptsLeft: pts })

    return true

}







// Apply flat bonuses to traits AFTER applyDamageModsToTraits() and BEFORE calculateMoveStatsForFamily().

// This affects outputs (damage/reach/time/status) but does NOT affect mana costs.

function applyLevelUpBonusesToTraitsOLDCODETODELETE(hi: number, family: number, traitsEff: MoveTraits): MoveTraits {

    if (!traitsEff) return traitsEff;



    const b1 = getHeroLevelUpTraitBonus(hi, family, OUT.TRAIT1) | 0;

    const b2 = getHeroLevelUpTraitBonus(hi, family, OUT.TRAIT2) | 0;

    const b3 = getHeroLevelUpTraitBonus(hi, family, OUT.TRAIT3) | 0;

    const b4 = getHeroLevelUpTraitBonus(hi, family, OUT.TRAIT4) | 0;



    if ((b1 | b2 | b3 | b4) === 0) return traitsEff;



    const out = traitsEff.slice() as MoveTraits;

    out[OUT.TRAIT1] = (out[OUT.TRAIT1] | 0) + b1;

    out[OUT.TRAIT2] = (out[OUT.TRAIT2] | 0) + b2;

    out[OUT.TRAIT3] = (out[OUT.TRAIT3] | 0) + b3;

    out[OUT.TRAIT4] = (out[OUT.TRAIT4] | 0) + b4;

    return out;

}





// IMPORTANT: map stored rank->bonus at application time (so table can change later).

// Replace your existing function with this full replacement.

function applyLevelUpBonusesToTraits(hi: number, family: number, traitsEff: MoveTraits): MoveTraits {

    if (!traitsEff) return traitsEff



    const r1 = getHeroLevelUpAxisRank(hi, family, OUT.TRAIT1) | 0

    const r2 = getHeroLevelUpAxisRank(hi, family, OUT.TRAIT2) | 0

    const r3 = getHeroLevelUpAxisRank(hi, family, OUT.TRAIT3) | 0

    const r4 = getHeroLevelUpAxisRank(hi, family, OUT.TRAIT4) | 0



    const b1 = _lvlupBonusFromRank(r1) | 0

    const b2 = _lvlupBonusFromRank(r2) | 0

    const b3 = _lvlupBonusFromRank(r3) | 0

    const b4 = _lvlupBonusFromRank(r4) | 0



    if ((b1 | b2 | b3 | b4) === 0) return traitsEff



    const out = traitsEff.slice() as MoveTraits

    out[OUT.TRAIT1] = (out[OUT.TRAIT1] | 0) + b1

    out[OUT.TRAIT2] = (out[OUT.TRAIT2] | 0) + b2

    out[OUT.TRAIT3] = (out[OUT.TRAIT3] | 0) + b3

    out[OUT.TRAIT4] = (out[OUT.TRAIT4] | 0) + b4

    return out

}







