function _shopStatueRow_getLayoutState(): any {

    const kind = _shopLayout_kind | 0

    const baseR = _shopLayout_baseR | 0

    const baseC = _shopLayout_baseC | 0

    const haveLayout = (kind === 2 || kind === 1) && baseR >= 0 && baseC >= 0

    // Statue columns in 5-col layout: two left, gap, two right

    const statueCols = [0, 1, 3, 4]

    return { haveLayout, baseR, baseC, statueCols }

}



function _shopStatueRow_pidForIndex(si: number): number {

    return (SHOP_STATUE_PLAYER_IDS && SHOP_STATUE_PLAYER_IDS[si] != null)

        ? (SHOP_STATUE_PLAYER_IDS[si] | 0)

        : ((SHOPKEEPER_PLAYER_ID - 1 - si) | 0)

}



function _shopStatueRow_buildCtx(si: number): any {

    const familyNum = SHOP_STATUE_ORDER_FAMILY[si] | 0

    const familyStr = heroFamilyNumberToString(familyNum)

    const gameplayKind = SHOP_STATUE_ORDER_GAMEPLAY[si]



    const equipSlot = (SHOP_STATUE_EQUIP_SLOT && SHOP_STATUE_EQUIP_SLOT[si]) ? (SHOP_STATUE_EQUIP_SLOT[si] || "") : ""

    const renderSlot = (SHOP_STATUE_RENDER_SLOT && SHOP_STATUE_RENDER_SLOT[si]) ? (SHOP_STATUE_RENDER_SLOT[si] || "") : ""

    const eqSlot = (equipSlot || "thrust").toLowerCase()

    const rdSlot = (renderSlot || eqSlot).toLowerCase()



    const pid = _shopStatueRow_pidForIndex(si)

    return { familyNum, familyStr, gameplayKind, eqSlot, rdSlot, pid }

}



function _shopStatueRow_findHeroIndexForSprite(st: Sprite): number {

    for (let i = 0; i < heroes.length; i++) {

        if (heroes[i] === st) return i

    }

    return -1

}



function _shopStatueRow_findHeroByOwner(pid: number): any {

    for (let i = 0; i < heroes.length; i++) {

        const h = heroes[i]

        if (!h) continue

        if (h.flags & sprites.Flag.Destroyed) continue

        const owner = sprites.readDataNumber(h, HERO_DATA.OWNER) | 0

        if (owner === (pid | 0)) return { st: h, stHi: i }

    }

    return { st: null, stHi: -1 }

}



function _shopStatueRow_createStatue(si: number, pid: number, familyNum: number): any {

    const sx = shopkeeperNpc.x | 0

    const sy = (shopkeeperNpc.y - 42) | 0



    createHeroForPlayer(

        pid,

        sx,

        sy,

        SHOP_STATUE_PROFILE_NAME,

        familyNum,

        true,   // isNpc

        false   // forcePlayerToHeroIndexMapping

    )



    const stHi = heroes.length - 1

    const st = heroes[stHi]



    console.log(

        `[SHOP][STEP2][STATUE_CREATE] i=${si} pid=${pid} hi=${stHi} ` +

        `heroName=${sprites.readDataString(st, "heroName")} heroFamily=${sprites.readDataString(st, "heroFamily")}`

    )



    return { st, stHi }

}



function _shopStatueRow_getOrCreateStatue(si: number, ctx: any): any {

    let st: Sprite = shopStatues[si]

    let stHi = -1



    if (!st) {

        const found = _shopStatueRow_findHeroByOwner(ctx.pid | 0)

        st = found.st

        stHi = found.stHi



        if (!st) {

            const created = _shopStatueRow_createStatue(si, ctx.pid | 0, ctx.familyNum | 0)

            st = created.st

            stHi = created.stHi

        }



        if (st) {

            _shopRegisterNpc(st)

            st.setFlag(SpriteFlag.Ghost, true)

            st.vx = 0

            st.vy = 0

            shopStatues[si] = st

        }

    } else {

        stHi = _shopStatueRow_findHeroIndexForSprite(st)

    }



    return { st, stHi }

}



function _shopStatueRow_stampIdentityAndOverlay(st: Sprite, familyStr: string): void {

    // Canonical identity fields

    sprites.setDataString(st, HERO_DATA.NAME, SHOP_STATUE_PROFILE_NAME)

    sprites.setDataString(st, "heroName", SHOP_STATUE_PROFILE_NAME)

    sprites.setDataString(st, "heroFamily", familyStr)



    // Weapon overlay settings

    sprites.setDataNumber(st, HERO_DATA.HERO_WPN_OFF_X, 10)

    sprites.setDataNumber(st, HERO_DATA.HERO_WPN_OFF_Y, 6)

    sprites.setDataNumber(st, HERO_DATA.WEAPON_ALWAYS_SHOW, 1)

}



function _shopStatueRow_ensureWeaponIdInContract(si: number, rdSlot: string, ids: string[], slots: string[]): string {

    // ? INDEX-LOCKED weapon assignment (NO PICKING)

    let weaponId = (ids[si] || "").trim()



    // If missing, fill deterministically (and write back so it stays stable)

    if (!weaponId) {

        if (rdSlot === "slash") weaponId = DEFAULT_WEAPON_SLASH_ID

        else if (rdSlot === "cast") weaponId = DEFAULT_WEAPON_CAST_ID

        else weaponId = DEFAULT_WEAPON_THRUST_ID



        ids[si] = weaponId

        slots[si] = rdSlot

        sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_IDS_KEY, ids.join("|"))

        sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_SLOTS_KEY, slots.join("|"))

        console.log(`[SHOP][STATUE_CONTRACT][FILL] idx=${si} slot=${rdSlot} weapon=${weaponId}`)

    }



    // Force ring slot at this index to match the statue’s render slot (keeps contract coherent)

    const curSlot = (slots[si] || "").toLowerCase()

    if (curSlot !== rdSlot) {

        slots[si] = rdSlot

        sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_SLOTS_KEY, slots.join("|"))

        console.log(`[SHOP][STATUE_CONTRACT][FIX_SLOT] idx=${si} ${curSlot} -> ${rdSlot} weapon=${weaponId}`)

    }



    return weaponId

}



function _shopStatueRow_stampOfferMetadata(st: Sprite, si: number, ctx: any, weaponId: string): void {

    sprites.setDataString(st, SHOP_DATA.LABEL, "Statue " + ctx.gameplayKind)

    sprites.setDataString(st, SH_ITEM_GAMEPLAY_KIND, ctx.gameplayKind)

    sprites.setDataNumber(st, SH_ITEM_RING_INDEX, si)

    sprites.setDataString(st, SH_ITEM_EQUIP_SLOT, ctx.eqSlot)

    sprites.setDataString(st, SH_ITEM_RENDER_SLOT, ctx.rdSlot)

    sprites.setDataString(st, SH_ITEM_WEAPON_ID, weaponId)

}



function _shopStatueRow_forceFrozenPose(st: Sprite, stHi: number, nowMs: number, rdSlot: string): void {

    if (typeof _shopStatueForceFrozenPose === "function") {

        _shopStatueForceFrozenPose(st, stHi, nowMs | 0, rdSlot)

    } else {

        sprites.setDataString(st, "dir", "down")

        sprites.setDataString(st, HERO_DATA.DIR, "down")

        sprites.setDataString(st, "phase", rdSlot)

        sprites.setDataString(st, HERO_DATA.PHASE, rdSlot)

        sprites.setDataString(st, HERO_DATA.PhaseName, rdSlot)

        sprites.setDataNumber(st, HERO_DATA.FRAME_COL_OVERRIDE, 0)

    }

}



function _shopStatueRow_equipIfChanged(st: Sprite, rdSlot: string, weaponId: string): void {

    const prevWeapon = (sprites.readDataString(st, "_shPrevWeaponId") || "")

    const prevSlot = (sprites.readDataString(st, "_shPrevRenderSlot") || "")

    if (weaponId !== prevWeapon || rdSlot !== prevSlot) {

        sprites.setDataString(st, "_shPrevWeaponId", weaponId)

        sprites.setDataString(st, "_shPrevRenderSlot", rdSlot)

        _shopEquipWeaponToHeroSlot(st, rdSlot, weaponId)

    }

}



function _shopStatueRow_debugStamp(st: Sprite, nowMs: number, si: number, ctx: any, weaponId: string, stHi: number): void {

    const _kStamp = "shStatueStampLogMs"

    const lastStamp = (sprites.readDataNumber(st, _kStamp) | 0)

    if (((nowMs | 0) - lastStamp) >= 750) {

        sprites.setDataNumber(st, _kStamp, nowMs | 0)

        const DEBUG_STATUE_STAMP = false

        if (DEBUG_STATUE_STAMP) {

        console.log(

            `[SHOP][STEP3][STATUE_STAMP] i=${si} pid=${ctx.pid} kind=${ctx.gameplayKind} ` +

            `equip=${ctx.eqSlot} render=${ctx.rdSlot} weapon=${weaponId} family=${ctx.familyStr} hi=${stHi}`

        )

    }

    }

}



function _shopPedestalEnsureLen4(): void {

    if (!shopPedestalSolids) shopPedestalSolids = []

    while (shopPedestalSolids.length < 4) shopPedestalSolids.push(null)

    while (shopPedestalSolids.length > 4) shopPedestalSolids.pop()

}



function _shopUpsertPedestalSolid(si: number, tileR: number, tileC: number): void {

    const r = tileR | 0

    const c = tileC | 0

    if (r < 0 || c < 0) return



    const tileSize = WORLD_TILE_SIZE | 0

    if (tileSize <= 0) return



    _shopPedestalEnsureLen4()



    let s = shopPedestalSolids[si]

    const dead = (!s || (s.flags & sprites.Flag.Destroyed))



    if (dead) {

        const img = _createDecorColliderImage(tileSize, tileSize)

        s = sprites.create(img, (SpriteKind as any).DecorSolid)

        s.setFlag(SpriteFlag.Invisible, true)



        sprites.setDataNumber(s, DECOR_DATA.IS_COLLIDER, 1)

        sprites.setDataNumber(s, DECOR_DATA.ID, PROP_PEDESTAL)

        sprites.setDataNumber(s, DECOR_DATA.ROLE, DECOR_ROLE.SOLID)

        sprites.setDataString(s, DECOR_DATA.NAME, "pedestal")



        shopPedestalSolids[si] = s

        _engineDecorSolids.push(s)

    } else {

        let found = false

        for (let i = 0; i < _engineDecorSolids.length; i++) {

            if (_engineDecorSolids[i] === s) { found = true; break }

        }

        if (!found) _engineDecorSolids.push(s)



        sprites.setDataNumber(s, DECOR_DATA.IS_COLLIDER, 1)

        sprites.setDataNumber(s, DECOR_DATA.ID, PROP_PEDESTAL)

        sprites.setDataNumber(s, DECOR_DATA.ROLE, DECOR_ROLE.SOLID)

        sprites.setDataString(s, DECOR_DATA.NAME, "pedestal")

    }



    const prevR = sprites.readDataNumber(s, "decorTileR") | 0

    const prevC = sprites.readDataNumber(s, "decorTileC") | 0

    if (dead || prevR !== r || prevC !== c) {

        sprites.setDataNumber(s, "decorTileR", r)

        sprites.setDataNumber(s, "decorTileC", c)



        s.left = (c * tileSize) | 0

        s.top = (r * tileSize) | 0



        _engineDecorRev = (_engineDecorRev + 1) | 0

    }

}



function _shopStatueRow_placeStatue(si: number, st: Sprite, layout: any): void {

    let pedR = -1

    let pedC = -1



    if (layout.haveLayout) {

        const rowSlot = 0

        const colSlot = layout.statueCols[si] | 0



        const slotBaseR = (layout.baseR + (rowSlot * 2)) | 0

        const slotBaseC = (layout.baseC + (colSlot * 2)) | 0

        pedR = (slotBaseR + 1) | 0

        pedC = (slotBaseC + 1) | 0

    } else {

        const baseX = shopkeeperNpc.x | 0

        const baseY = (shopkeeperNpc.y - 42) | 0

        const spacing = 36

        const dx = (Math.round((si - 1.5) * spacing) | 0)

        const guessX = (baseX + dx) | 0

        const guessY = baseY | 0



        pedR = _shopPixToTile(guessY)

        pedC = _shopPixToTile(guessX)

    }



    st.z = ((shopkeeperNpc.z | 0) + SHOP_STATUE_DEPTH_BIAS) | 0



    if (pedR >= 0 && pedC >= 0) {

        // Statues should sit ON the pedestal tile center (not the 2x2 slot center).

        const pedX = _dunColToX(pedC)

        const pedY = _dunRowToY(pedR)

        const stR = Math.max(0, (pedR - 1) | 0)

        const stY = _dunRowToY(stR)

        st.setPosition(pedX, stY)

        _shopUpsertPedestalSolid(si, pedR, pedC)



        const nowMs = game.runtime() | 0

        const _k = "shPedLogMs"

        const last = sprites.readDataNumber(st, _k) | 0

        if ((nowMs - last) >= 750) {

            sprites.setDataNumber(st, _k, nowMs)

            const dx = ((st.x | 0) - (pedX | 0)) | 0

            const dy = ((st.y | 0) - (pedY | 0)) | 0

            const stHi = _shopStatueRow_findHeroIndexForSprite(st)

            let heroXY = "?,?"

            let heroTile = "?,?"

            let heroOwner = -1

            let nativeXY = "?,?"

            const renderOffsY = sprites.readDataNumber(st, HERO_DATA.RENDER_OFFS_Y) | 0

            if (stHi >= 0 && heroes[stHi]) {

                const h = heroes[stHi]

                heroXY = `${h.x | 0},${h.y | 0}`

                heroOwner = sprites.readDataNumber(h, HERO_DATA.OWNER) | 0

                const tr = sprites.readDataNumber(h, HERO_DATA.TILE_R) | 0

                const tc = sprites.readDataNumber(h, HERO_DATA.TILE_C) | 0

                heroTile = `${tr},${tc}`

            }

            const nat: any = (st as any).native

            if (nat && typeof nat.x === "number" && typeof nat.y === "number") {

                nativeXY = `${nat.x | 0},${nat.y | 0}`

            }

            const DEBUG_STATUE_PEDESTAL = false

            if (DEBUG_STATUE_PEDESTAL) {

            console.log(

                `[SHOP][PED] i=${si} stXY=${st.x|0},${st.y|0} pedRC=${pedR},${pedC} pedXY=${pedX|0},${pedY|0} d=${dx},${dy} ` +

                `heroHi=${stHi} heroXY=${heroXY} heroTile=${heroTile} heroOwner=${heroOwner} nativeXY=${nativeXY} renderOffsY=${renderOffsY}`

            )

        }

        }

    }

}





function _shopEnsureStatueRow(nowMs: number): void {

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    // Keep exactly 4 slots, stable index = stable statue meaning

    _shopStatueRow_ensureLen4()



    // Null out dead refs (do NOT removeAt / shift indices)

    _shopStatueRow_nullDeadRefs()



    // Keep shopkeeper + trigger anchored to the layout (prevents drift)

    _shopStatueRow_anchorShopkeeperAndTriggerIfPresent()



    // Read ring contract (SOURCE OF TRUTH)

    const rr = _shopStatueRow_readRingContractEnsureLen4(shopkeeperNpc)

    const ids: string[] = rr.ids

    const slots: string[] = rr.slots



    // Layout-aware slot positioning

    const layout = _shopStatueRow_getLayoutState()



    for (let si = 0; si < 4; si++) {

        const ctx = _shopStatueRow_buildCtx(si)



        const got = _shopStatueRow_getOrCreateStatue(si, ctx)

        const st: Sprite = got.st

        const stHi: number = got.stHi



        if (!st) continue



        _shopStatueRow_stampIdentityAndOverlay(st, ctx.familyStr)



        const weaponId = _shopStatueRow_ensureWeaponIdInContract(si, ctx.rdSlot, ids, slots)



        _shopStatueRow_stampOfferMetadata(st, si, ctx, weaponId)



        _shopStatueRow_forceFrozenPose(st, stHi, nowMs | 0, ctx.rdSlot)



        _shopStatueRow_equipIfChanged(st, ctx.rdSlot, weaponId)



        _shopStatueRow_debugStamp(st, nowMs | 0, si, ctx, weaponId, stHi)



        _shopStatueRow_placeStatue(si, st, layout)

    }

}





function _shopFamilyFromGameplayKind(kind: string): number {

    const k = (kind || "").toLowerCase();

    if (k === "strength") return FAMILY.STRENGTH;

    if (k === "agility") return FAMILY.AGILITY;

    if (k === "intellect" || k === "intelligence") return FAMILY.INTELLECT;

    if (k === "wisdom" || k === "support" || k === "heal" || k === "healing") return FAMILY.HEAL;

    return FAMILY.STRENGTH;

}



function _shopFamilyFromEquipSlot(slot: string): number {

    const s = (slot || "").toLowerCase()

    if (s === SHOP_EQUIP_SLOT_STRENGTH) return FAMILY.STRENGTH

    if (s === SHOP_EQUIP_SLOT_AGILITY) return FAMILY.AGILITY

    if (s === SHOP_EQUIP_SLOT_INTELLIGENCE) return FAMILY.INTELLECT

    if (s === SHOP_EQUIP_SLOT_SUPPORT || s === "wisdom") return FAMILY.HEAL

    return FAMILY.STRENGTH

}



function _shopEquipSlotFromFamily(fam: number): string {

    const f = fam | 0

    if (f === FAMILY.STRENGTH) return SHOP_EQUIP_SLOT_STRENGTH

    if (f === FAMILY.AGILITY) return SHOP_EQUIP_SLOT_AGILITY

    if (f === FAMILY.INTELLECT) return SHOP_EQUIP_SLOT_INTELLIGENCE

    if (f === FAMILY.HEAL) return SHOP_EQUIP_SLOT_SUPPORT

    return ""

}



function _shopDefaultWeaponIdForSlot(slot: string): string {

    const s = (slot || "").toLowerCase()

    if (s === SHOP_EQUIP_SLOT_STRENGTH) return DEFAULT_WEAPON_STRENGTH_ID

    if (s === SHOP_EQUIP_SLOT_AGILITY) return DEFAULT_WEAPON_AGILITY_ID

    if (s === SHOP_EQUIP_SLOT_INTELLIGENCE) return DEFAULT_WEAPON_INTELLIGENCE_ID

    if (s === SHOP_EQUIP_SLOT_SUPPORT) return DEFAULT_WEAPON_SUPPORT_ID

    if (s === "slash") return DEFAULT_WEAPON_SLASH_ID

    if (s === "cast") return DEFAULT_WEAPON_CAST_ID

    return DEFAULT_WEAPON_THRUST_ID

}



function _shopPrettyFamilyName(fam: number): string {

    const f = fam | 0;

    if (f === FAMILY.STRENGTH) return "Strength";

    if (f === FAMILY.AGILITY) return "Agility";

    if (f === FAMILY.INTELLECT) return "Intelligence";

    return "Wisdom";

}



function _shopFormatBonusDesc(fam: number, t1: number, t2: number, t3: number, t4: number): string {

    const familyName = _shopPrettyFamilyName(fam);



    const a1 = t1 | 0, a2 = t2 | 0, a3 = t3 | 0, a4 = t4 | 0;



    // Exact patterns you asked for

    if (a1 !== 0 && a2 === 0 && a3 === 0 && a4 === 0) {

        return `+${a1} to Trait 1 for ${familyName}`;

    }

    if (a1 !== 0 && a1 === a2 && a2 === a3 && a3 === a4) {

        return `+${a1} to Traits 1, 2, 3, and 4 for ${familyName}`;

    }



    // Generic fallback

    let s = `Bonus for ${familyName}: `;

    let first = true;



    function addPart(traitNum: number, v: number) {

        if ((v | 0) === 0) return;

        if (!first) s += ", ";

        first = false;

        s += `T${traitNum}+${v | 0}`;

    }



    addPart(1, a1);

    addPart(2, a2);

    addPart(3, a3);

    addPart(4, a4);



    if (first) return `Bonus for ${familyName}: (none)`;

    return s;

}



function _shopRollBonusForOffer(it: Sprite): void {

    const gameplayKind = sprites.readDataString(it, SH_ITEM_GAMEPLAY_KIND) || "";

    const fam = _shopFamilyFromGameplayKind(gameplayKind);



    // 3 simple “knobs” patterns (big single, spread, duo)

    const p = randint(0, 2);



    let t1 = 0, t2 = 0, t3 = 0, t4 = 0;



    if (p === 0) {

        t1 = randint(80, 120); // ~"+100 Trait 1"

    } else if (p === 1) {

        const v = randint(15, 30); // ~"+20 all traits"

        t1 = v; t2 = v; t3 = v; t4 = v;

    } else {

        t1 = randint(25, 60);

        t2 = randint(25, 60);

        // leave t3/t4 at 0 (easy to see the change)

    }



    const desc = _shopFormatBonusDesc(fam, t1, t2, t3, t4);



    sprites.setDataNumber(it, SH_ITEM_BONUS_FAMILY, fam);

    sprites.setDataNumber(it, SH_ITEM_BONUS_T1, t1);

    sprites.setDataNumber(it, SH_ITEM_BONUS_T2, t2);

    sprites.setDataNumber(it, SH_ITEM_BONUS_T3, t3);

    sprites.setDataNumber(it, SH_ITEM_BONUS_T4, t4);

    sprites.setDataString(it, SH_ITEM_BONUS_DESC, desc);

}



function _shopEnsureOfferHasBonus(it: Sprite): void {

    const d = sprites.readDataString(it, SH_ITEM_BONUS_DESC) || "";

    if (d) return;

    _shopRollBonusForOffer(it);

}



function _shopApplyOfferBonusToHero(hi: number, offer: Sprite, ringIndex: number, nowMs: number): void {

    _shopEnsureOfferHasBonus(offer);



    const equipSlot = (sprites.readDataString(offer, SH_ITEM_EQUIP_SLOT) || "").toLowerCase()

    const famRaw = sprites.readDataNumber(offer, SH_ITEM_BONUS_FAMILY) | 0;

    const fam = equipSlot ? _shopFamilyFromEquipSlot(equipSlot) : (famRaw | 0);

    const weaponId = sprites.readDataString(offer, SH_ITEM_WEAPON_ID) || "";

    let t1 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T1) | 0;

    let t2 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T2) | 0;

    let t3 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T3) | 0;

    let t4 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T4) | 0;



    const defaultId = _shopDefaultWeaponIdForSlot(equipSlot);

    const isBaseWeapon = !!defaultId && (weaponId === defaultId);

    if (isBaseWeapon || !weaponId) {

        t1 = 0; t2 = 0; t3 = 0; t4 = 0;

    }



    const slotKey = equipSlot || `fam${fam | 0}`;

    const base = `shop.weapon.${slotKey}`;



    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT1)!, base + ".t1", t1);

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT2)!, base + ".t2", t2);

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT3)!, base + ".t3", t3);

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT4)!, base + ".t4", t4);

}



function _shopGetEquippedWeaponIdForHeroSlot(hero: Sprite, equipSlot: string): string {

    if (!hero) return ""

    const slot = (equipSlot || "").toLowerCase()



    // New trait slots

    if (slot === SHOP_EQUIP_SLOT_STRENGTH) return sprites.readDataString(hero, HERO_DATA_WEAPON_STRENGTH_ID) || ""

    if (slot === SHOP_EQUIP_SLOT_AGILITY) return sprites.readDataString(hero, HERO_DATA_WEAPON_AGILITY_ID) || ""

    if (slot === SHOP_EQUIP_SLOT_INTELLIGENCE) return sprites.readDataString(hero, HERO_DATA_WEAPON_INTELLIGENCE_ID) || ""

    if (slot === SHOP_EQUIP_SLOT_SUPPORT) return sprites.readDataString(hero, HERO_DATA_WEAPON_SUPPORT_ID) || ""



    // Legacy render/equip slots (keep for old callers)

    if (slot === "slash") return sprites.readDataString(hero, HERO_DATA.WEAPON_SLASH_ID) || ""

    if (slot === "cast") return sprites.readDataString(hero, HERO_DATA.WEAPON_CAST_ID) || ""

    return sprites.readDataString(hero, HERO_DATA.WEAPON_THRUST_ID) || ""

}





function _shopSetRingWeaponAndSlotAtIndex(sk: Sprite, idx: number, weaponId: string, slot: string): void {

    if (!sk) return



    // Pull current lists

    const idsRaw = sprites.readDataString(sk, SHOP_WPN_RING_IDS_KEY) || ""

    const slotsRaw = sprites.readDataString(sk, SHOP_WPN_RING_SLOTS_KEY) || SHOP_DEFAULT_RING_SLOTS || ""



    let ids = _shopSplitPipeList(idsRaw)

    let slots = _shopSplitPipeKeepEmpty(slotsRaw)



    const want = 4

    while (ids.length < want) ids.push("")

    while (ids.length > want) ids.pop()

    while (slots.length < want) slots.push("")

    while (slots.length > want) slots.pop()



    const i = (idx | 0)

    if (i < 0 || i >= want) return



    // Enforce canonical slots (prevents drift; statues depend on this)

    const wantSlot = _shopNormWeaponId((SHOP_STATUE_RENDER_SLOT && SHOP_STATUE_RENDER_SLOT[i]) ? (SHOP_STATUE_RENDER_SLOT[i] || "") : "")

    const slotUse = wantSlot || _shopNormWeaponId(slot) || "thrust"



    // Enforce allowed model ids per statue index

    const before = _shopNormWeaponId(weaponId)

    const list = _shopAllowedWeaponListForStatueIndex(i)

    const fallback = (list && list.length > 0) ? _shopNormWeaponId(list[0]) : _shopNormWeaponId("")

    const use = _shopSanitizeWeaponIdForStatueIndex(i, before, fallback)



    if (use !== before) {

        console.log(`[SHOP][RING][SET_SAN] idx=${i} bad=${before} -> use=${use} kind=${SHOP_STATUE_ORDER_GAMEPLAY[i]}`)

    }



    ids[i] = use

    slots[i] = slotUse



    sprites.setDataString(sk, SHOP_WPN_RING_IDS_KEY, ids.join("|"))

    sprites.setDataString(sk, SHOP_WPN_RING_SLOTS_KEY, slots.join("|"))

}





function _shopSetRingWeaponIdAtIndex(sk: Sprite, idx: number, weaponId: string): void {

    const idsStr = sprites.readDataString(sk, SHOP_WPN_RING_IDS_KEY) || "";

    const ids = _shopSplitPipeList(idsStr);

    if (idx < 0 || idx >= ids.length) return;

    ids[idx] = weaponId || "";

    sprites.setDataString(sk, SHOP_WPN_RING_IDS_KEY, ids.join("|"));

}



function _shopUnlockExitPadIfInShopFloor(nowMs: number): void {

    const now = nowMs | 0



    // V6 uses DUNGEON_MODE_ACTIVE (no _dunActive exists)

    if (!DUNGEON_MODE_ACTIVE) return

    if (_dunFloorKind !== DUNGEON_KIND_SHOP) return



    if (_dunObjectiveDone && _dunIsPadPowered()) return



    _dunObjectiveDone = true

    _dunSetPadPowered(true)



    // Make rune appear immediately (don’t wait for dungeonTick)

    if (_dunTeleportRuneTrig && !(_dunTeleportRuneTrig.flags & sprites.Flag.Destroyed)) {

        const desired = "teleport_rune"

        if (_dunTeleportRuneName !== desired) {

            sprites.setDataString(_dunTeleportRuneTrig, DECOR_DATA.NAME, desired)

            _engineDecorRev = (_engineDecorRev + 1) | 0

            _dunTeleportRuneName = desired

        }

    }



    // Optional: quick DOM hint

    const g: any = globalThis as any

    const dlg = g.__heDialog

    dlg?.show?.({

        speaker: "Shopkeeper",

        text: "Teleport rune activated.",

        hint: "Step on the pad to leave the shop."

    })

}







function enterShopMode(): void {

    if (_shopEntered) return

    _shopEntered = false

    if(SHOP_MODE_ACTIVE_MASTER) {

    SHOP_MODE_ACTIVE = true

    }

    // Create shopkeeper + publish contract + spawn offers

    shopInitPOC()



    // Optional: immediate debug

    console.log("[SHOP] ENTER shop mode t=" + (game.runtime() | 0))

}







function _shopEnsurePerHeroStateArrays(): void {

    const N = 4



    // (These vars MUST already be declared at top-level in this namespace.)

    if (shopFocusRingIndexByHero === null) shopFocusRingIndexByHero = []

    if (shopFocusUntilMsByHero === null) shopFocusUntilMsByHero = []

    if (shopTouchUntilMsByHero === null) shopTouchUntilMsByHero = []

    if (shopBoughtByHero === null) shopBoughtByHero = []

    if (shopFocusOfferByHero === null) shopFocusOfferByHero = []



    while (shopFocusRingIndexByHero.length < N) shopFocusRingIndexByHero.push(-1)

    while (shopFocusUntilMsByHero.length < N) shopFocusUntilMsByHero.push(0)

    while (shopTouchUntilMsByHero.length < N) shopTouchUntilMsByHero.push(0)

    while (shopBoughtByHero.length < N) shopBoughtByHero.push(false)

    while (shopFocusOfferByHero.length < N) shopFocusOfferByHero.push(null)

}







function shopTick(nowMs: number): void {

    const now = (nowMs | 0)

    if (!HeroEngine._isStarted()) return



    // ------------------------------------------------------------

    // CRITICAL GUARD:

    // Prevent shopInitPOC() from running on non-shop floors.

    // This was causing the trigger/shopkeeper to respawn forever.

    // ------------------------------------------------------------

    if (!DUNGEON_MODE_ACTIVE || _dunFloorKind !== DUNGEON_KIND_SHOP) {

        SHOP_MODE_ACTIVE_MASTER = false

        SHOP_MODE_ACTIVE = false

        return

    }



    // Only init when missing/destroyed (DO NOT re-init every frame)

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) {

        shopInitPOC()

    }



    // If still not present, bail cleanly.

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) {

        console.log("Ending shop mode")

        SHOP_MODE_ACTIVE = false

        return

    }



    shopkeeperNpc.setFlag(SpriteFlag.Ghost, false)



    // Force-move escape hatch + auto-rescue if stuck in walls

    _shopApplyForceMoveIfRequested()

    _shopRescueShopkeeperFromWalls()



    // 1) Compute which offer each hero is focused/touching (grace-window)

    shopUpdateFocus(now)



    // 2) Publish highlight contract on shopkeeper sprite

    shopPublishTouchedMapOnShopkeeper(now)



    // 3) Route shop controls (A buy, B return, arrows reserved for future UI)

    shopHandleControls(now)



    // 4) Decide whether shop mode is active

    let anyActive = false

    for (let hi = 0; hi < 4; hi++) {

        if (now <= (shopFocusUntilMsByHero[hi] | 0)) { anyActive = true; break }

    }



    // 5) Debug dump (throttled inside)

    shopDebugDump(now)

}





function shopPollControls(hi: number): {

    A_edge: boolean;

    B_edge: boolean;

    Up_edge: boolean;

    Down_edge: boolean;

    Left_edge: boolean;

    Right_edge: boolean;

} {

    const i = hi | 0

    if (i < 0 || i > 3) {

        return { A_edge: false, B_edge: false, Up_edge: false, Down_edge: false, Left_edge: false, Right_edge: false }

    }



    let aNow = false, bNow = false, upNow = false, downNow = false, leftNow = false, rightNow = false



    if (i === 0) {

        aNow = controller.player1.A.isPressed()

        bNow = controller.player1.B.isPressed()

        upNow = controller.player1.up.isPressed()

        downNow = controller.player1.down.isPressed()

        leftNow = controller.player1.left.isPressed()

        rightNow = controller.player1.right.isPressed()

    } else if (i === 1) {

        aNow = controller.player2.A.isPressed()

        bNow = controller.player2.B.isPressed()

        upNow = controller.player2.up.isPressed()

        downNow = controller.player2.down.isPressed()

        leftNow = controller.player2.left.isPressed()

        rightNow = controller.player2.right.isPressed()

    } else if (i === 2) {

        aNow = controller.player3.A.isPressed()

        bNow = controller.player3.B.isPressed()

        upNow = controller.player3.up.isPressed()

        downNow = controller.player3.down.isPressed()

        leftNow = controller.player3.left.isPressed()

        rightNow = controller.player3.right.isPressed()

    } else {

        aNow = controller.player4.A.isPressed()

        bNow = controller.player4.B.isPressed()

        upNow = controller.player4.up.isPressed()

        downNow = controller.player4.down.isPressed()

        leftNow = controller.player4.left.isPressed()

        rightNow = controller.player4.right.isPressed()

    }



    const aPrev = shopPrevAByPlayer[i]

    const bPrev = shopPrevBByPlayer[i]

    const upPrev = shopPrevUpByPlayer[i]

    const downPrev = shopPrevDownByPlayer[i]

    const leftPrev = shopPrevLeftByPlayer[i]

    const rightPrev = shopPrevRightByPlayer[i]



    shopPrevAByPlayer[i] = aNow

    shopPrevBByPlayer[i] = bNow

    shopPrevUpByPlayer[i] = upNow

    shopPrevDownByPlayer[i] = downNow

    shopPrevLeftByPlayer[i] = leftNow

    shopPrevRightByPlayer[i] = rightNow



    return {

        A_edge: !!(aNow && !aPrev),

        B_edge: !!(bNow && !bPrev),

        Up_edge: !!(upNow && !upPrev),

        Down_edge: !!(downNow && !downPrev),

        Left_edge: !!(leftNow && !leftPrev),

        Right_edge: !!(rightNow && !rightPrev),

    }

}







function shopUpdateFocus(nowMs: number): void {

    const now = nowMs | 0



    // Keep statues “locked in” (pose + weapon + placement) every tick

    _shopEnsureStatueRow(now)



    // If we don’t have all statues yet, do not change focus (prevents flicker)

    if (!shopStatues || shopStatues.length < 4) return



    // Clear dead focus refs

    for (let hi = 0; hi < 4; hi++) {

        const cur = shopFocusOfferByHero[hi]

        if (cur && (cur.flags & sprites.Flag.Destroyed)) {

            shopFocusOfferByHero[hi] = null

            shopFocusRingIndexByHero[hi] = -1

            shopFocusUntilMsByHero[hi] = 0

        }

    }



    // Statue offers only (indices 0..3)

    const offers: Sprite[] = []

    for (let i = 0; i < 4; i++) {

        const st = shopStatues[i]

        if (!st) continue

        if (st.flags & sprites.Flag.Destroyed) continue

        offers.push(st)

    }



    // For each player-hero, pick the first overlapping statue (sorted by ring index)

    // (We keep the "lowest ring index wins" behavior deterministically.)

    for (let hi = 0; hi < 4; hi++) {

        const hero = heroes[hi]

        if (!hero) continue

        if (hero.flags & sprites.Flag.Destroyed) continue

        const pid = (hi + 1) | 0

        const owner = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

        if ((owner | 0) !== (pid | 0)) {

            shopFocusOfferByHero[hi] = null

            shopFocusRingIndexByHero[hi] = -1

            shopFocusUntilMsByHero[hi] = 0

            continue

        }



        let found: Sprite = null

        let foundRing = -1



        // Scan in index order 0..3 (stable)

        for (let i = 0; i < offers.length; i++) {

            const it = offers[i]

            if (!it) continue

            if (_shopIsHeroTouchingStatueOffer(hero, it)) {

                found = it

                foundRing = (sprites.readDataNumber(it, SH_ITEM_RING_INDEX) | 0)

                break

            }

        }



        if (found) {

            shopFocusOfferByHero[hi] = found

            shopFocusRingIndexByHero[hi] = foundRing

            shopFocusUntilMsByHero[hi] = (now + SHOP_FOCUS_KEEPALIVE_MS) | 0

        } else {

            // Grace: allow brief dropout without losing focus immediately

            if (now > (shopFocusUntilMsByHero[hi] | 0)) {

                shopFocusOfferByHero[hi] = null

                shopFocusRingIndexByHero[hi] = -1

                shopFocusUntilMsByHero[hi] = 0

            }

        }

    }



    // Existing debug proof should still work downstream:

    // shopPublishTouchedMapOnShopkeeper() reads shopFocusRingIndexByHero[]

}







function shopPublishTouchedMapOnShopkeeper(nowMs: number): void {

    const now = nowMs | 0

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    // Build: p1=2|p2=-1|p3=-1|p4=0

    let ringByPid = ""

    let idByPid = ""

    let slotByPid = ""



    for (let hi = 0; hi < 4; hi++) {

        const pid = (hi + 1) | 0

        let ring = -1

        let wid = ""

        let slot = ""



        if (now <= (shopFocusUntilMsByHero[hi] | 0)) {

            ring = shopFocusRingIndexByHero[hi] | 0

            const offer = shopFocusOfferByHero[hi]

            if (offer && !(offer.flags & sprites.Flag.Destroyed)) {

                wid = sprites.readDataString(offer, SH_ITEM_WEAPON_ID) || ""

                slot = sprites.readDataString(offer, SH_ITEM_RENDER_SLOT) || ""

            }

        }



        if (hi > 0) { ringByPid += "|"; idByPid += "|"; slotByPid += "|" }

        ringByPid += "p" + pid + "=" + ring

        idByPid += "p" + pid + "=" + wid

        slotByPid += "p" + pid + "=" + slot

    }



    sprites.setDataString(shopkeeperNpc, SHOP_WPN_TOUCHED_RING_BY_PID_KEY, ringByPid)

    sprites.setDataString(shopkeeperNpc, SHOP_WPN_TOUCHED_ID_BY_PID_KEY, idByPid)

    sprites.setDataString(shopkeeperNpc, SHOP_WPN_TOUCHED_SLOT_BY_PID_KEY, slotByPid)

}







function shopHandleControls(nowMs: number): void {

    const now = nowMs | 0

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    for (let hi = 0; hi < 4; hi++) {

        const hero = heroes[hi]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue



        const pid = (hi + 1) | 0

        const owner = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

        if ((owner | 0) !== (pid | 0)) continue

        const uiMode = _uiReadNum(hero, HERO_UI_DATA.MODE, HERO_UI_MODE.NONE) | 0

        if (uiMode === HERO_UI_MODE.SHOP) continue

        const ctrl = shopPollControls(hi)



        // Focused offer (statue)

        const summary = _shopGetFocusedOfferSummaryForHero(hi, now)



        // ------------------------------------------------------------

        // A: Buy/Swap (statue offer)

        // ------------------------------------------------------------

        if (summary && summary.active && ctrl.A_edge) {

            const offer: Sprite = summary.offer

            if (!offer || (offer.flags & sprites.Flag.Destroyed)) continue

            const si = summary.ringIndex | 0



            const price = summary.price | 0

            const takeRaw = summary.weaponId || ""

            const takeId = _shopNormWeaponId(takeRaw)

            if (!takeId) continue



            const equipSlot = (summary.equipSlot || "thrust").toLowerCase()

            const renderSlot = (summary.renderSlot || equipSlot).toLowerCase()



            const giveRaw = _shopGetEquippedWeaponIdForHeroSlot(hero, equipSlot) || ""

            const giveId = _shopNormWeaponId(giveRaw)



            const takeT1 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T1) | 0

            const takeT2 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T2) | 0

            const takeT3 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T3) | 0

            const takeT4 = sprites.readDataNumber(offer, SH_ITEM_BONUS_T4) | 0



            const slotKey = equipSlot || ("fam" + (_shopFamilyFromEquipSlot(equipSlot) | 0))

            const base = `shop.weapon.${slotKey}`

            const giveT1 = heroModGet(hi, _modBucketForFamilyAndTraitIndex(_shopFamilyFromEquipSlot(equipSlot), OUT.TRAIT1)!, base + ".t1") | 0

            const giveT2 = heroModGet(hi, _modBucketForFamilyAndTraitIndex(_shopFamilyFromEquipSlot(equipSlot), OUT.TRAIT2)!, base + ".t2") | 0

            const giveT3 = heroModGet(hi, _modBucketForFamilyAndTraitIndex(_shopFamilyFromEquipSlot(equipSlot), OUT.TRAIT3)!, base + ".t3") | 0

            const giveT4 = heroModGet(hi, _modBucketForFamilyAndTraitIndex(_shopFamilyFromEquipSlot(equipSlot), OUT.TRAIT4)!, base + ".t4") | 0



            const sameWeapon = ((giveId || "") === (takeId || ""))

            const sameBonus = (giveT1 === takeT1 && giveT2 === takeT2 && giveT3 === takeT3 && giveT4 === takeT4)



            if (sameWeapon && sameBonus) {

                console.log(`[SHOP][SWAP_SKIP] hi=${hi} pid=${pid} ring=${si} reason=same_weapon weapon=${takeId}`)

                continue

            }



            // LEGALITY: both sides must match statue allowed set

            if (!_shopIsWeaponAllowedForStatueIndex(si, takeId)) {

                console.log(`[SHOP][SWAP_DENY] hi=${hi} pid=${pid} ring=${si} reason=offer_illegal take=${takeId} give=${giveId}`)



                // Repair offer to something legal (do NOT spend coins)

                const rr = _shopRingReadIdsSlotsFromShopkeeper(shopkeeperNpc)

                const ids: string[] = rr.ids

                const slots: string[] = rr.slots



                const want = 4

                while (ids.length < want) ids.push("")

                while (ids.length > want) ids.pop()

                while (slots.length < want) slots.push("")

                while (slots.length > want) slots.pop()



                const list = _shopAllowedWeaponListForStatueIndex(si)



                let pick = ""

                if (list && list.length > 0) pick = list[((Math.random() * list.length) | 0)] || ""

                pick = _shopNormWeaponId(pick)



                if (!pick || !_shopIsWeaponAllowedForStatueIndex(si, pick)) {

                    pick = ""

                    for (let j = 0; j < list.length; j++) {

                        const c = _shopNormWeaponId(list[j] || "")

                        if (_shopIsWeaponAllowedForStatueIndex(si, c)) { pick = c; break }

                    }

                }



                if (!pick) {

                    if (renderSlot === "slash") pick = DEFAULT_WEAPON_SLASH_ID

                    else if (renderSlot === "cast") pick = DEFAULT_WEAPON_CAST_ID

                    else pick = DEFAULT_WEAPON_THRUST_ID

                    pick = _shopNormWeaponId(pick)

                }



                ids[si] = pick

                slots[si] = renderSlot



                sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_IDS_KEY, ids.join("|"))

                sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_SLOTS_KEY, slots.join("|"))



                // HARD-clear legacy ring keys so nothing external spawns ring offers

                sprites.setDataString(shopkeeperNpc, SHOP_WPN_RING_IDS_KEY, "")

                sprites.setDataString(shopkeeperNpc, SHOP_WPN_RING_SLOTS_KEY, "")



                console.log(`[SHOP][SWAP_REPAIR_OFFER] ring=${si} newOffer=${pick} slot=${renderSlot}`)

                _shopEnsureStatueRow(now)

                continue

            }



            if (!_shopIsWeaponAllowedForStatueIndex(si, giveId)) {

                console.log(`[SHOP][SWAP_DENY] hi=${hi} pid=${pid} ring=${si} reason=hero_illegal take=${takeId} give=${giveId}`)

                continue

            }



            // Spend this hero's coins

            if (!trySpendHeroCoins(hi, price)) {

                console.log(`[SHOP][BUY_DENY] hi=${hi} pid=${pid} ring=${si} price=${price} coins=${getHeroCoins(hi) | 0}`)

                continue

            }



            // Apply bonus to hero (mods)

            _shopApplyOfferBonusToHero(hi, offer, si, now)



            // Hero takes the offer (EQUIP SLOT drives gameplay)

            _shopEquipWeaponToHeroSlot(hero, equipSlot, takeId)



            // Offer becomes hero's previous weapon (ALWAYS SWAPPED) — write to NEW contract

            const rr2 = _shopRingReadIdsSlotsFromShopkeeper(shopkeeperNpc)

            const ids2: string[] = rr2.ids

            const slots2: string[] = rr2.slots



            const want = 4

            while (ids2.length < want) ids2.push("")

            while (ids2.length > want) ids2.pop()

            while (slots2.length < want) slots2.push("")

            while (slots2.length > want) slots2.pop()



            ids2[si] = giveId

            slots2[si] = renderSlot



            sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_IDS_KEY, ids2.join("|"))

            sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_SLOTS_KEY, slots2.join("|"))



            // HARD-clear legacy ring keys so nothing external spawns ring offers

            sprites.setDataString(shopkeeperNpc, SHOP_WPN_RING_IDS_KEY, "")

            sprites.setDataString(shopkeeperNpc, SHOP_WPN_RING_SLOTS_KEY, "")



            // Immediate visual update on the touched statue

            sprites.setDataString(offer, SH_ITEM_WEAPON_ID, giveId)

            sprites.setDataString(offer, SH_ITEM_RENDER_SLOT, renderSlot)

            sprites.setDataString(offer, SH_ITEM_EQUIP_SLOT, equipSlot)

            _shopEquipWeaponToHeroSlot(offer, renderSlot, giveId)



            console.log(

                `[SHOP][SWAP] hi=${hi} pid=${pid} ring=${si} ` +

                `equip=${equipSlot} render=${renderSlot} take=${takeId} give=${giveId} ` +

                `price=${price} coinsAfter=${getHeroCoins(hi) | 0}`

            )



            _animEvent_emit(hi, hero, EVENT_MASK_SHOP_SWAP, 0, 0, 0, 0, "SHOP_SWAP", "shopHandleControls")

            const offerHi = sprites.readDataNumber(offer, HERO_DATA.HERO_INDEX) | 0

            if (offerHi >= 0) {

                _animEvent_emit(offerHi, offer, EVENT_MASK_SHOP_SWAP, 0, 0, 0, 0, "SHOP_SWAP", "shopHandleControls")

            }



            _shopEnsureStatueRow(now)

            continue

        }



        // ------------------------------------------------------------

        // A: No focused offer -> interacting with shopkeeper unlocks exit

        // ------------------------------------------------------------

        if (ctrl.A_edge) {

            if (_isHeroInInteractRange(hero, shopkeeperNpc, NPC_INTERACT_EXTRA_X_PX, NPC_INTERACT_EXTRA_Y_PX)) {

                _uiTryOpenShopUi(hi, pid, "shopkeeper:A")
                _shopUnlockExitPadIfInShopFloor(now)

            }

        }

    }

}







function shopDebugDump(nowMs: number): void {

    const now = nowMs | 0

    if (now - (_shopLastDebugDumpMs | 0) < SHOP_DEBUG_DUMP_EVERY_MS) return

    _shopLastDebugDumpMs = now



    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    const skId = (shopkeeperNpc.id | 0)

    const owner = (sprites.readDataNumber(shopkeeperNpc, HERO_DATA.OWNER) | 0)

    const heroName = sprites.readDataString(shopkeeperNpc, "heroName") || sprites.readDataString(shopkeeperNpc, HERO_DATA.NAME) || ""

    const ringIds = sprites.readDataString(shopkeeperNpc, SHOP_WPN_RING_IDS_KEY) || ""

    const rPx = sprites.readDataNumber(shopkeeperNpc, SHOP_WPN_RING_RADIUS_PX_KEY) | 0

    const aDeg = sprites.readDataNumber(shopkeeperNpc, SHOP_WPN_RING_ANGLE_DEG_KEY) | 0

    const defDir = sprites.readDataString(shopkeeperNpc, SHOP_WPN_DEFAULT_DIR_KEY) || ""

    const dirMap = sprites.readDataString(shopkeeperNpc, SHOP_WPN_DIR_MAP_KEY) || ""



    const touchedRingByPid = sprites.readDataString(shopkeeperNpc, SHOP_WPN_TOUCHED_RING_BY_PID_KEY) || ""

    const touchedIdByPid = sprites.readDataString(shopkeeperNpc, SHOP_WPN_TOUCHED_ID_BY_PID_KEY) || ""

    const touchedSlotByPid = sprites.readDataString(shopkeeperNpc, SHOP_WPN_TOUCHED_SLOT_BY_PID_KEY) || ""



    // Offer list snapshot (ringIndex:weaponId:slot:price:boughtByPid)

    let offers: Sprite[] = null as any

    try { offers = (SHOP_ITEMS as any) } catch (e) { offers = null }

    if (!offers) offers = sprites.allOfKind(SpriteKind.ShopItem)



    let offerDump = ""

    for (let i = 0; i < offers.length; i++) {

        const it = offers[i]

        if (!it) continue

        if (it.flags & sprites.Flag.Destroyed) continue



        const ri = sprites.readDataNumber(it, SH_ITEM_RING_INDEX) | 0

        const wid = sprites.readDataString(it, SH_ITEM_WEAPON_ID) || ""

        const slot = sprites.readDataString(it, SH_ITEM_RENDER_SLOT) || ""

        const price = sprites.readDataNumber(it, SH_ITEM_PRICE) | 0

        const byPid = sprites.readDataNumber(it, SH_ITEM_BOUGHT_BY_PID) | 0



        if (offerDump !== "") offerDump += " ; "

        offerDump += ri + ":" + wid + ":" + slot + ":" + price + ":p" + byPid

    }



    console.log(

        "[SHOP][DUMP] t=" + now +

        " sk{id=" + skId + " owner=" + owner + " heroName=" + heroName + "}" +

        " ring{ids='" + ringIds + "' rPx=" + rPx + " aDeg=" + aDeg + " defDir=" + defDir + " dirMap='" + dirMap + "'}" +

        " touched{ring='" + touchedRingByPid + "' id='" + touchedIdByPid + "' slot='" + touchedSlotByPid + "'}" +

        " offers{n=" + offers.length + " " + offerDump + "}"

    )

}





function _shopSafeStr(s: string): string {

    return (s === null || s === undefined) ? "" : ("" + s)

}



function _shopSpriteId(s: Sprite): number {

    // Arcade sprite ids are usually stored on the object; if not, return -1

    return (s && (s as any).id !== undefined) ? ((s as any).id | 0) : -1

}



function _shopOfferSummary(it: Sprite): string {

    if (!it) return "null"

    if (it.flags & sprites.Flag.Destroyed) return "destroyed"



    const id = _shopSpriteId(it)

    const ringIndex = sprites.readDataNumber(it, SH_ITEM_RING_INDEX) | 0

    const weaponId = _shopSafeStr(sprites.readDataString(it, SH_ITEM_WEAPON_ID))

    const slot = _shopSafeStr(sprites.readDataString(it, SH_ITEM_RENDER_SLOT))

    const price = sprites.readDataNumber(it, SH_ITEM_PRICE) | 0

    const ownedBy = sprites.readDataNumber(it, SH_ITEM_BOUGHT_BY_PID) | 0



    return "#" + id +

        " i=" + ringIndex +

        " wid=" + weaponId +

        " slot=" + slot +

        " $" + price +

        " ownedBy=" + ownedBy +

        " pos=(" + (it.x | 0) + "," + (it.y | 0) + ")"

}



function _shopBuildDebugSignature(nowMs: number): string {

    // Signature used to detect meaningful changes for spam-safe logs

    let sig = ""



    // Shopkeeper core + contract

    if (shopkeeperNpc && !(shopkeeperNpc.flags & sprites.Flag.Destroyed)) {

        sig += "sk@" + (shopkeeperNpc.x | 0) + "," + (shopkeeperNpc.y | 0)

        sig += "|ids=" + _shopSafeStr(sprites.readDataString(shopkeeperNpc, SHOP_WPN_RING_IDS_KEY))

        sig += "|r=" + (sprites.readDataNumber(shopkeeperNpc, SHOP_WPN_RING_RADIUS_PX_KEY) | 0)

        sig += "|a=" + (sprites.readDataNumber(shopkeeperNpc, SHOP_WPN_RING_ANGLE_DEG_KEY) | 0)

        sig += "|dd=" + _shopSafeStr(sprites.readDataString(shopkeeperNpc, SHOP_WPN_DEFAULT_DIR_KEY))

        sig += "|dm=" + _shopSafeStr(sprites.readDataString(shopkeeperNpc, SHOP_WPN_DIR_MAP_KEY))



        // Highlight contract

        sig += "|tm=" + (sprites.readDataNumber(shopkeeperNpc, SHOP_WPN_TOUCH_MASK_KEY) | 0)

        sig += "|tbh=" + _shopSafeStr(sprites.readDataString(shopkeeperNpc, SHOP_WPN_TOUCH_BY_HERO_KEY))

    } else {

        sig += "sk=none"

    }



    // Offers summary (weapon/slot/price/ownedBy)

    sig += "|offers="

    for (let i = 0; i < _shopRingOfferItems.length; i++) {

        const it = _shopRingOfferItems[i]

        if (!it || (it.flags & sprites.Flag.Destroyed)) { sig += "x"; continue }

        const weaponId = _shopSafeStr(sprites.readDataString(it, SH_ITEM_WEAPON_ID))

        const slot = _shopSafeStr(sprites.readDataString(it, SH_ITEM_RENDER_SLOT))

        const price = sprites.readDataNumber(it, SH_ITEM_PRICE) | 0

        const ownedBy = sprites.readDataNumber(it, SH_ITEM_BOUGHT_BY_PID) | 0

        sig += "[" + weaponId + ":" + slot + ":" + price + ":" + ownedBy + "]"

    }



    // Per-hero focus

    sig += "|focus="

    for (let hi = 0; hi < 4; hi++) {

        sig += "(" + (shopFocusRingIndexByHero[hi] | 0) + "," + (shopFocusUntilMsByHero[hi] | 0) + ")"

    }



    // Per-hero coins

    sig += "|coins="

    for (let hi = 0; hi < 4; hi++) {

        sig += "p" + ((hi + 1) | 0) + "=" + (getHeroCoins(hi) | 0) + ";"

    }



    return sig

}











function _shopPrettySlot(slot: string): string {

    const s = (slot || "").toLowerCase()

    if (s === "slash") return "SLASH"

    if (s === "cast") return "CAST"

    return "THRUST"

}



function _shopOwnerLabel(ownedByPid: number, pid: number): string {

    const ob = ownedByPid | 0

    const p = pid | 0

    if (ob === 0) return "AVAILABLE"

    if (ob === p) return "YOURS"

    return "OWNED(P" + ob + ")"

}



function _shopGetFocusedOfferSummaryForHero(hi: number, nowMs: number): any {

    const now = nowMs | 0

    const offer = shopFocusOfferByHero[hi]

    if (!offer) return { active: false }

    if (!_shopIsOfferTouchValidForHero(hi, now)) return { active: false }



    _shopEnsureOfferHasBonus(offer)



    const ringIndex = sprites.readDataNumber(offer, SH_ITEM_RING_INDEX) | 0



    const equipSlot = (sprites.readDataString(offer, SH_ITEM_EQUIP_SLOT) || "").toLowerCase()

    const renderSlot = (sprites.readDataString(offer, SH_ITEM_RENDER_SLOT) || "").toLowerCase()

    const weaponId = sprites.readDataString(offer, SH_ITEM_WEAPON_ID) || ""



    const weaponLabel = sprites.readDataString(offer, SH_ITEM_LABEL) || weaponId

    const price = sprites.readDataNumber(offer, SH_ITEM_PRICE) | 0

    const bonusDesc = sprites.readDataString(offer, SH_ITEM_BONUS_DESC) || ""



    return {

        active: true,

        offer,

        ringIndex,

        weaponId,

        weaponLabel,

        price,

        equipSlot: (equipSlot || renderSlot || "thrust"),

        renderSlot: (renderSlot || equipSlot || "thrust"),

        bonusDesc

    }

}



function _shopBuildDialogLine(hi: number, pid: number, s: {

    ringIndex: number,

    weaponId: string,

    slot: string,

    price: number,

    ownedBy: number,

    active: boolean

}): string {

    if (!s.active) return ""



    const slotPretty = _shopPrettySlot(s.slot)

    const ownerStr = _shopOwnerLabel(s.ownedBy, pid)



    // Example: "DAGGER  [THRUST]  $6  AVAILABLE"

    return (s.weaponId || "???").toUpperCase() + "  [" + slotPretty + "]  $" + (s.price | 0) + "  " + ownerStr

}





function _shopBuildControlsLine(pid: number, summary: any): string {

    if (!summary || !summary.active) return "";

    const price = summary.price | 0;

    return `A: buy/swap (${price}??)`;

}



function _shopBuildStatsLine(hi: number, summary: any): string {

    if (!summary || !summary.active) return "";

    return summary.bonusDesc || "";

}





function _shopIsOfferTouchValidForHero(hi: number, nowMs: number): boolean {

    const h = hi | 0

    const now = nowMs | 0

    if (h < 0 || h >= 4) return false



    const hero = heroes[h]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return false



    const offer = shopFocusOfferByHero[h]

    if (!offer || (offer.flags & sprites.Flag.Destroyed)) return false



    const until = shopFocusUntilMsByHero[h] | 0

    if ((until | 0) == 0) return false

    if (now > until) return false



    // Sanity: ring index should match the focused ring index (when both are present)

    const offerRing = sprites.readDataNumber(offer, SH_ITEM_RING_INDEX) | 0

    const focusRing = shopFocusRingIndexByHero[h] | 0

    if ((offerRing | 0) >= 0 && (focusRing | 0) >= 0 && (offerRing | 0) !== (focusRing | 0)) return false



    // Ownership gate (future-proof; currently you stamp 0 = available)

    const ownedBy = sprites.readDataNumber(offer, SH_ITEM_BOUGHT_BY_PID) | 0

    const pid = (h + 1) | 0

    if ((ownedBy | 0) !== 0 && (ownedBy | 0) !== (pid | 0)) return false



    return true

}







function _shopGetFocusedOfferForHero(hi: number, nowMs: number): Sprite {

    if (hi < 0 || hi > 3) return null



    // Focus must be currently alive (freshness)

    const until = shopFocusUntilMsByHero[hi] | 0

    if (!(until > 0 && (nowMs | 0) < until)) return null



    const idx = shopFocusRingIndexByHero[hi] | 0

    if (idx < 0) return null



    // Prefer ring list

    if (idx < _shopRingOfferItems.length) {

        const it = _shopRingOfferItems[idx]

        if (it && !(it.flags & sprites.Flag.Destroyed)) return it

    }



    // Fallback: scan SHOP_ITEMS by ringIndex

    _shopCullDestroyed(SHOP_ITEMS)

    for (let i = 0; i < SHOP_ITEMS.length; i++) {

        const it = SHOP_ITEMS[i]

        if (!it) continue

        if (it.flags & sprites.Flag.Destroyed) continue

        const ri = sprites.readDataNumber(it, SH_ITEM_RING_INDEX) | 0

        if (ri === idx) return it

    }



    return null

}



function _shopEquipWeaponToHeroSlot(hero: Sprite, equipSlot: string, weaponId: string): void {

    if (!hero) return

    const slot = (equipSlot || "").toLowerCase()

    const wid = weaponId || ""



    // New trait slots

    if (slot === SHOP_EQUIP_SLOT_STRENGTH) { sprites.setDataString(hero, HERO_DATA_WEAPON_STRENGTH_ID, wid); return }

    if (slot === SHOP_EQUIP_SLOT_AGILITY) { sprites.setDataString(hero, HERO_DATA_WEAPON_AGILITY_ID, wid); return }

    if (slot === SHOP_EQUIP_SLOT_INTELLIGENCE) { sprites.setDataString(hero, HERO_DATA_WEAPON_INTELLIGENCE_ID, wid); return }

    if (slot === SHOP_EQUIP_SLOT_SUPPORT) { sprites.setDataString(hero, HERO_DATA_WEAPON_SUPPORT_ID, wid); return }



    // Legacy render/equip slots (keep for old callers)

    if (slot === "slash") { sprites.setDataString(hero, HERO_DATA.WEAPON_SLASH_ID, wid); return }

    if (slot === "cast") { sprites.setDataString(hero, HERO_DATA.WEAPON_CAST_ID, wid); return }

    sprites.setDataString(hero, HERO_DATA.WEAPON_THRUST_ID, wid)

}



function _shopClearWeaponFromHeroSlotIfMatches(hero: Sprite, equipSlot: string, weaponId: string): boolean {

    if (!hero) return false

    const slot = (equipSlot || "").toLowerCase()

    const wid = weaponId || ""



    // New trait slots

    if (slot === SHOP_EQUIP_SLOT_STRENGTH) {

        const cur = sprites.readDataString(hero, HERO_DATA_WEAPON_STRENGTH_ID) || ""

        if (cur === wid) {

            sprites.setDataString(hero, HERO_DATA_WEAPON_STRENGTH_ID, "")

            return true

        }

        return false

    }

    if (slot === SHOP_EQUIP_SLOT_AGILITY) {

        const cur = sprites.readDataString(hero, HERO_DATA_WEAPON_AGILITY_ID) || ""

        if (cur === wid) {

            sprites.setDataString(hero, HERO_DATA_WEAPON_AGILITY_ID, "")

            return true

        }

        return false

    }

    if (slot === SHOP_EQUIP_SLOT_INTELLIGENCE) {

        const cur = sprites.readDataString(hero, HERO_DATA_WEAPON_INTELLIGENCE_ID) || ""

        if (cur === wid) {

            sprites.setDataString(hero, HERO_DATA_WEAPON_INTELLIGENCE_ID, "")

            return true

        }

        return false

    }

    if (slot === SHOP_EQUIP_SLOT_SUPPORT) {

        const cur = sprites.readDataString(hero, HERO_DATA_WEAPON_SUPPORT_ID) || ""

        if (cur === wid) {

            sprites.setDataString(hero, HERO_DATA_WEAPON_SUPPORT_ID, "")

            return true

        }

        return false

    }



    // Legacy render/equip slots

    if (slot === "slash") {

        const cur = sprites.readDataString(hero, HERO_DATA.WEAPON_SLASH_ID) || ""

        if (cur === wid) {

            sprites.setDataString(hero, HERO_DATA.WEAPON_SLASH_ID, "")

            return true

        }

        return false

    }

    if (slot === "cast") {

        const cur = sprites.readDataString(hero, HERO_DATA.WEAPON_CAST_ID) || ""

        if (cur === wid) {

            sprites.setDataString(hero, HERO_DATA.WEAPON_CAST_ID, "")

            return true

        }

        return false

    }

    const cur = sprites.readDataString(hero, HERO_DATA.WEAPON_THRUST_ID) || ""

    if (cur === wid) {

        sprites.setDataString(hero, HERO_DATA.WEAPON_THRUST_ID, "")

        return true

    }

    return false

}



function _shopClearWeaponModsForSlot(hi: number, equipSlot: string): void {

    const slot = (equipSlot || "").toLowerCase()

    const fam = _shopFamilyFromEquipSlot(slot)

    const base = `shop.weapon.${slot || ("fam" + (fam | 0))}`

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT1)!, base + ".t1", 0)

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT2)!, base + ".t2", 0)

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT3)!, base + ".t3", 0)

    heroModSet(hi, _modBucketForFamilyAndTraitIndex(fam, OUT.TRAIT4)!, base + ".t4", 0)

}



function _shopSetUiBoughtFlagFromOffer(hi: number, pid: number, offer: Sprite): void {

    if (hi < 0 || hi > 3) return

    if (!offer) { shopBoughtByHero[hi] = false; return }

    const boughtBy = sprites.readDataNumber(offer, SH_ITEM_BOUGHT_BY_PID) | 0

    shopBoughtByHero[hi] = (boughtBy === (pid | 0))

}







function _shopApplyFocusGateToShopUi(nowMs: number): void {

    const now = nowMs | 0

    for (let hi = 0; hi < 4; hi++) {

        const until = shopFocusUntilMsByHero[hi] | 0

        const active = (until > 0) && (now < until)



        if (active) {

            // Keep the existing shop UI/input gate alive while an offer is focused

            shopTouchUntilMsByHero[hi] = now + SHOP_TOUCH_GRACE_MS

        } else {

            // Let it decay naturally (do not force to 0; preserves your grace semantics)

            // (No-op here)

        }

    }

}







function _shopIsAliveSprite(s: Sprite): boolean {

    return !!s && ((s.flags & sprites.Flag.Destroyed) === 0)

}



function _shopComputeFocusedRingIndexForHero(hero: Sprite): number {

    if (!hero) return -1



    // Prefer the dedicated ring offer list (Step 1–4)

    for (let i = 0; i < _shopRingOfferItems.length; i++) {

        const it = _shopRingOfferItems[i]

        if (!_shopIsAliveSprite(it)) continue

        if (_shopIsOverlapping(hero, it)) {

            const idx = sprites.readDataNumber(it, SH_ITEM_RING_INDEX) | 0

            return (idx >= 0) ? idx : i

        }

    }



    // Fallback: scan SHOP_ITEMS if ring list isn't populated

    // (This keeps the seam usable even if someone later spawns items outside the ring builder.)

    _shopCullDestroyed(SHOP_ITEMS)

    for (let i = 0; i < SHOP_ITEMS.length; i++) {

        const it = SHOP_ITEMS[i]

        if (!_shopIsAliveSprite(it)) continue

        if (_shopIsOverlapping(hero, it)) {

            const idx = sprites.readDataNumber(it, SH_ITEM_RING_INDEX) | 0

            return (idx >= 0) ? idx : -1

        }

    }



    return -1

}



function _shopPublishTouchStateOnShopkeeper(nowMs: number): void {

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    // Determine "active touch" (within keepalive)

    let mask = 0

    const parts: string[] = []



    for (let hi = 0; hi < 4; hi++) {

        const until = shopFocusUntilMsByHero[hi] | 0

        const active = (until > 0) && ((nowMs | 0) < until)



        const idx = active ? (shopFocusRingIndexByHero[hi] | 0) : -1

        parts.push("" + idx)



        if (active && idx >= 0 && idx < 31) {

            mask |= (1 << idx)

        }

    }



    const touchByHeroStr = parts.join("|")



    // Publish to shopkeeper for Phaser ghost-ring renderer

    sprites.setDataNumber(shopkeeperNpc, SHOP_WPN_TOUCH_MASK_KEY, mask | 0)

    sprites.setDataString(shopkeeperNpc, SHOP_WPN_TOUCH_BY_HERO_KEY, touchByHeroStr)



    // Debug only on change

    if (mask !== _shopPrevTouchMask || touchByHeroStr !== _shopPrevTouchByHero) {

        _shopPrevTouchMask = mask

        _shopPrevTouchByHero = touchByHeroStr

        console.log("[SHOP][FOCUS] mask=" + mask + " byHero=" + touchByHeroStr)

    }

}





function shopControlTick(nowMs: number): void {

    const now = nowMs | 0



    // If shopkeeper not alive, clear state

    if (!_shopIsAliveSprite(shopkeeperNpc)) {

        for (let hi = 0; hi < 4; hi++) {

            shopFocusRingIndexByHero[hi] = -1

            shopFocusUntilMsByHero[hi] = 0

            shopFocusOfferByHero[hi] = null

        }

        return

    }



    // Statues are the offers now; focus is computed against statues only.

    shopUpdateFocus(now)



    // Publish highlight/touch state onto shopkeeper (DOM/overlay uses these)

    _shopPublishTouchStateOnShopkeeper(now)



    // Step 9: comprehensive dump (spam-safe; prints on change or throttled)

    shopDebugDump(now)

}





// Main “shop controls layer” tick (Step 5)

// - Today: focus comes from overlap

// - Future: focus can come from a menu selection (arrows) without touching publish/purchase code

function shopControlTickOLDCODETODELETE(nowMs: number): void {

    const now = nowMs | 0



    if (!_shopIsAliveSprite(shopkeeperNpc)) {

        for (let hi = 0; hi < 4; hi++) {

            shopFocusRingIndexByHero[hi] = -1

            shopFocusUntilMsByHero[hi] = 0

            shopFocusOfferByHero[hi] = null



            shopTouchRingMaskByHero[hi] = 0

            shopTouchUntilMsByHero[hi] = 0

        }

        return

    }



    // Statues are the ONLY offers now

    shopUpdateFocus(now)



    // Touch plumbing stays in sync with focus

    for (let hi = 0; hi < 4; hi++) {

        const ringIndex = shopFocusRingIndexByHero[hi] | 0

        const aliveFocus = (ringIndex >= 0) && (shopFocusUntilMsByHero[hi] > now)

        if (aliveFocus) {

            shopTouchRingMaskByHero[hi] = (1 << ringIndex)

            shopTouchUntilMsByHero[hi] = shopFocusUntilMsByHero[hi]

        } else {

            shopTouchRingMaskByHero[hi] = 0

            shopTouchUntilMsByHero[hi] = 0

        }

    }



    _shopPublishTouchStateOnShopkeeper(now)

    shopPublishTouchedMapOnShopkeeper(now)



    shopDebugDump(now)

}







// ------------------------------------------------------------

// Helpers

