function _shopSetItemVisibleForHero(heroIndex: number, hero: Sprite, show: boolean): void {

    const it = _shopEnsureItemForHero(heroIndex)

    it.setFlag(SpriteFlag.Invisible, !show)

    if (!show) return



    // POC “inventory position”: floats near hero

    it.x = hero.x + 18

    it.y = hero.y - 18

}



