// ================================================================

// SECTION 2.5 - TILEMAP AND WORLD GENERATION (improved)

// ================================================================

// Uses cellular automata to make nice blobby walls, then carves

// a central arena for the heroes.

// ================================================================



function _createTileMap2D(): number[][] {

    // Just use the basic cave generator in ALL runtimes.

    // MakeCode and Phaser both see the same 0/1 logic grid.

    return _createBasicCaveMap();

}



function _createBasicCaveMap(): number[][] {

    // 1) Decide world dimensions in tiles

    let cols = Math.max(WORLD_TILES_W, MIN_WORLD_TILES_W)

    let rows = Math.max(WORLD_TILES_H, MIN_WORLD_TILES_H)



    // Extra safety floor if you still want it

    if (cols < 10) cols = 10

    if (rows < 8) rows = 8



    // 2) Seed random map (0 = empty, 1 = wall)

    const wallChance = 45

    let map = _seedRandomMap(rows, cols, wallChance)



    // 3) Run a few smoothing steps (cellular automata)

    const smoothSteps = 5

    for (let i = 0; i < smoothSteps; i++) {

        map = _smoothMapStep(map)

    }



    // 4) Make outer border solid walls (flying-island feel & clean edges)

    for (let r = 0; r < rows; r++) {

        map[r][0] = TILE_WALL

        map[r][cols - 1] = TILE_WALL

    }

    for (let c = 0; c < cols; c++) {

        map[0][c] = TILE_WALL

        map[rows - 1][c] = TILE_WALL

    }



    // 5) Carve a central arena for the heroes (guaranteed open space)

    const centerR = Math.idiv(rows, 2)

    const centerC = Math.idiv(cols, 2)



    // Size of arena scales with map size

    const arenaHalfH = Math.max(2, Math.idiv(rows, 8))   // vertical half-size

    const arenaHalfW = Math.max(2, Math.idiv(cols, 8))   // horizontal half-size



    const topR = Math.max(1, centerR - arenaHalfH)

    const bottomR = Math.min(rows - 2, centerR + arenaHalfH)

    const leftC = Math.max(1, centerC - arenaHalfW)

    const rightC = Math.min(cols - 2, centerC + arenaHalfW)



    for (let r = topR; r <= bottomR; r++) {

        for (let c = leftC; c <= rightC; c++) {

            map[r][c] = TILE_EMPTY

        }

    }



    // 6) Carve L-shaped corridors from each corner into the arena (NOW 2 tiles wide).

    const CORRIDOR_WIDTH = 2



    // We target a 2-column “spine” at the arena center.

    const spineC0 = Math.max(1, Math.min(cols - 2, centerC - 1))

    const spineC1 = Math.max(1, Math.min(cols - 2, centerC))



    function carveRect(r0: number, c0: number, r1: number, c1: number) {

        const rStart = Math.max(1, Math.min(r0, r1))

        const rEnd   = Math.min(rows - 2, Math.max(r0, r1))

        const cStart = Math.max(1, Math.min(c0, c1))

        const cEnd   = Math.min(cols - 2, Math.max(c0, c1))



        for (let r = rStart; r <= rEnd; r++) {

            for (let c = cStart; c <= cEnd; c++) {

                map[r][c] = TILE_EMPTY

            }

        }

    }



    function carveCornerToArena(cornerR: number, cornerC: number) {

        // Horizontal segment (2 tiles tall):

        const hr0 = (cornerR <= centerR) ? cornerR : (cornerR - (CORRIDOR_WIDTH - 1))

        const hr1 = hr0 + (CORRIDOR_WIDTH - 1)



        carveRect(

            hr0,

            Math.min(cornerC, spineC0),

            hr1,

            Math.max(cornerC, spineC1)

        )



        // Vertical segment (2 tiles wide at the spine columns):

        carveRect(

            Math.min(cornerR, centerR),

            spineC0,

            Math.max(cornerR, centerR),

            spineC1

        )

    }



    // Inner spawn corners (leave outermost border walls intact at 0 / rows-1 / cols-1)

    const topRow = 1

    const bottomRow = rows - 2

    const leftCol = 1

    const rightCol = cols - 2



    carveCornerToArena(topRow, leftCol)

    carveCornerToArena(topRow, rightCol)

    carveCornerToArena(bottomRow, leftCol)

    carveCornerToArena(bottomRow, rightCol)



    // 7) Carve spawn pads that INCLUDE the actual outer corners.

    const SPAWN_PAD_RADIUS = 2 // 2 ? up to 5x5 pad; tune as needed



    function carveSpawnPad(centerR: number, centerC: number) {

        const rStart = Math.max(0, centerR - SPAWN_PAD_RADIUS)

        const rEnd   = Math.min(rows - 1, centerR + SPAWN_PAD_RADIUS)

        const cStart = Math.max(0, centerC - SPAWN_PAD_RADIUS)

        const cEnd   = Math.min(cols - 1, centerC + SPAWN_PAD_RADIUS)



        for (let r = rStart; r <= rEnd; r++) {

            for (let c = cStart; c <= cEnd; c++) {

                map[r][c] = TILE_EMPTY

            }

        }

    }



    carveSpawnPad(0, 0)

    carveSpawnPad(0, cols - 1)

    carveSpawnPad(rows - 1, 0)

    carveSpawnPad(rows - 1, cols - 1)



    // 8) Post-process for tile-art constraints:

    //    A) Walkways/corridors must not be 1-tile wide (widen to >=2).

    //    B) Wall blobs must be >=4 tiles OR true singletons (size==1).

    //    C) Non-singleton wall tiles must have >=2 cardinal wall neighbors (prune spurs).

    ;(function postProcessForArt() {

        const MIN_COMPONENT_SIZE = 4

        const MIN_CARDINAL_WALL_NEI = 2



        function copyGrid(src: number[][]): number[][] {

            const out: number[][] = []

            for (let r = 0; r < rows; r++) out.push((src[r] as number[]).slice())

            return out

        }



        function countCardinalSame(src: number[][], r: number, c: number, val: number): number {

            let n = 0

            if (r > 0 && src[r - 1][c] === val) n++

            if (r < rows - 1 && src[r + 1][c] === val) n++

            if (c > 0 && src[r][c - 1] === val) n++

            if (c < cols - 1 && src[r][c + 1] === val) n++

            return n

        }



        function computeComponents4(src: number[][], targetVal: number): { compId: number[][], sizes: number[], touchesBorder: boolean[] } {

            const compId: number[][] = []

            for (let r = 0; r < rows; r++) {

                const row: number[] = []

                for (let c = 0; c < cols; c++) row.push(-1)

                compId.push(row)

            }



            const sizes: number[] = []

            const touchesBorder: boolean[] = []



            let nextId = 0



            for (let r0 = 0; r0 < rows; r0++) {

                for (let c0 = 0; c0 < cols; c0++) {

                    if (src[r0][c0] !== targetVal) continue

                    if (compId[r0][c0] >= 0) continue



                    const qR: number[] = [r0]

                    const qC: number[] = [c0]

                    compId[r0][c0] = nextId



                    let head = 0

                    let size = 0

                    let touch = false



                    while (head < qR.length) {

                        const r = qR[head]

                        const c = qC[head]

                        head++



                        size++

                        if (r === 0 || c === 0 || r === rows - 1 || c === cols - 1) touch = true



                        // 4-neighborhood flood

                        if (r > 0 && src[r - 1][c] === targetVal && compId[r - 1][c] < 0) {

                            compId[r - 1][c] = nextId

                            qR.push(r - 1); qC.push(c)

                        }

                        if (r < rows - 1 && src[r + 1][c] === targetVal && compId[r + 1][c] < 0) {

                            compId[r + 1][c] = nextId

                            qR.push(r + 1); qC.push(c)

                        }

                        if (c > 0 && src[r][c - 1] === targetVal && compId[r][c - 1] < 0) {

                            compId[r][c - 1] = nextId

                            qR.push(r); qC.push(c - 1)

                        }

                        if (c < cols - 1 && src[r][c + 1] === targetVal && compId[r][c + 1] < 0) {

                            compId[r][c + 1] = nextId

                            qR.push(r); qC.push(c + 1)

                        }

                    }



                    sizes[nextId] = size

                    touchesBorder[nextId] = touch

                    nextId++

                }

            }



            return { compId, sizes, touchesBorder }

        }



        function widenThinCorridorsOnce(): boolean {

            const src = copyGrid(map)

            let changed = false



            for (let r = 1; r <= rows - 2; r++) {

                for (let c = 1; c <= cols - 2; c++) {

                    if (src[r][c] !== TILE_EMPTY) continue



                    // Vertical corridor that is 1-tile wide (walls on both sides)

                    if (src[r][c - 1] === TILE_WALL && src[r][c + 1] === TILE_WALL) {

                        const preferLeft = (((r + c) & 1) === 0)

                        const carveC = preferLeft ? (c - 1) : (c + 1)

                        if (carveC > 0 && carveC < cols - 1) {

                            map[r][carveC] = TILE_EMPTY

                            changed = true

                        }

                    }



                    // Horizontal corridor that is 1-tile wide (walls above/below)

                    if (src[r - 1][c] === TILE_WALL && src[r + 1][c] === TILE_WALL) {

                        const preferUp = (((r + c) & 1) === 0)

                        const carveR = preferUp ? (r - 1) : (r + 1)

                        if (carveR > 0 && carveR < rows - 1) {

                            map[carveR][c] = TILE_EMPTY

                            changed = true

                        }

                    }

                }

            }



            return changed

        }



        function fillSmallFloorPockets(): void {

            const src = copyGrid(map)

            const comp = computeComponents4(src, TILE_EMPTY)



            for (let r = 0; r < rows; r++) {

                for (let c = 0; c < cols; c++) {

                    if (src[r][c] !== TILE_EMPTY) continue

                    const id = comp.compId[r][c]

                    if (id < 0) continue

                    if (comp.sizes[id] < MIN_COMPONENT_SIZE && !comp.touchesBorder[id]) {

                        map[r][c] = TILE_WALL

                    }

                }

            }

        }



        function removeSmallWallClusters(): void {

            const src = copyGrid(map)

            const comp = computeComponents4(src, TILE_WALL)



            for (let r = 0; r < rows; r++) {

                for (let c = 0; c < cols; c++) {

                    if (src[r][c] !== TILE_WALL) continue

                    const id = comp.compId[r][c]

                    if (id < 0) continue

                    const size = comp.sizes[id] | 0



                    // Keep true singletons (these render via "decor" slots on the Phaser side).

                    if (size === 1) continue



                    // Enforce >=4 for any non-singleton cluster (don’t touch border clusters).

                    if (size < MIN_COMPONENT_SIZE && !comp.touchesBorder[id]) {

                        map[r][c] = TILE_EMPTY

                    }

                }

            }

        }



        function pruneWallSpursOnce(): boolean {

            const src = copyGrid(map)

            const comp = computeComponents4(src, TILE_WALL)



            let changed = false



            for (let r = 1; r <= rows - 2; r++) {

                for (let c = 1; c <= cols - 2; c++) {

                    if (src[r][c] !== TILE_WALL) continue



                    const id = comp.compId[r][c]

                    if (id < 0) continue

                    const size = comp.sizes[id] | 0



                    // Keep singleton walls (0-neighbor “rocks”).

                    if (size <= 1) continue



                    const n = countCardinalSame(src, r, c, TILE_WALL)

                    if (n < MIN_CARDINAL_WALL_NEI) {

                        map[r][c] = TILE_EMPTY

                        changed = true

                    }

                }

            }



            return changed

        }



        // (A) Widen walkways to avoid 1-tile corridors

        for (let i = 0; i < 3; i++) {

            if (!widenThinCorridorsOnce()) break

        }



        // (B) Remove tiny pockets / blobs (but keep true singleton walls)

        fillSmallFloorPockets()

        removeSmallWallClusters()



        // (C) Prune wall spurs (non-singletons must have >=2 cardinal neighbors)

        for (let i = 0; i < 2; i++) {

            const changed = pruneWallSpursOnce()

            removeSmallWallClusters()

            if (!changed) break

        }



        // Final widen pass (spur pruning can reintroduce narrow spots)

        for (let i = 0; i < 2; i++) {

            if (!widenThinCorridorsOnce()) break

        }

    })()



    console.log(

        ">>> [HeroEngine.worldgen] map size",

        rows,

        "x",

        cols,

        "arena=",

        { topR, bottomR, leftC, rightC }

    )



    return map

}



// ------------------------------------------------------------

// Seed map with random walls / empty

// ------------------------------------------------------------

function _seedRandomMap(rows: number, cols: number, wallChancePercent: number): number[][] {

    const map: number[][] = []

    for (let r = 0; r < rows; r++) {

        const row: number[] = []

        for (let c = 0; c < cols; c++) {

            // Random wall vs empty

            if (randint(0, 99) < wallChancePercent) {

                row.push(TILE_WALL)

            } else {

                row.push(TILE_EMPTY)

            }

        }

        map.push(row)

    }

    return map

}



// ------------------------------------------------------------

// One cellular automata smoothing step

// ------------------------------------------------------------

function _smoothMapStep(oldMap: number[][]): number[][] {

    const rows = oldMap.length

    const cols = oldMap[0].length

    const newMap: number[][] = []



    for (let r = 0; r < rows; r++) {

        const newRow: number[] = []

        for (let c = 0; c < cols; c++) {

            const wallCount = _countWallNeighbors(oldMap, r, c)



            const current = oldMap[r][c]

            let next = current



            // Classic cave-style rules:

            // - If many walls around, this cell tends to become wall

            // - If few walls around, it tends to become empty

            if (current === TILE_WALL) {

                if (wallCount < 4) next = TILE_EMPTY

                else next = TILE_WALL

            } else { // TILE_EMPTY

                if (wallCount > 4) next = TILE_WALL

                else next = TILE_EMPTY

            }



            newRow.push(next)

        }

        newMap.push(newRow)

    }

    return newMap

}



// ------------------------------------------------------------

// Count walls in the 8 neighbors around (r,c).

// Out-of-bounds counts as wall to keep edges closed.

// ------------------------------------------------------------

function _countWallNeighbors(map: number[][], r: number, c: number): number {

    const rows = map.length

    const cols = map[0].length

    let count = 0



    for (let dr = -1; dr <= 1; dr++) {

        for (let dc = -1; dc <= 1; dc++) {

            if (dr === 0 && dc === 0) continue

            const nr = r + dr

            const nc = c + dc



            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {

                // Treat out-of-bounds as wall

                count++

            } else if (map[nr][nc] === TILE_WALL) {

                count++

            }

        }

    }



    return count

}





function _createWallTileImage(): Image {

    const s = WORLD_TILE_SIZE

    const img = image.create(s, s)



    // Black base

    img.fill(15)



    // Gray speckles

    for (let y = 0; y < s; y++) {

        for (let x = 0; x < s; x++) {

            if (randint(0, 7) === 0) img.setPixel(x, y, 13)

        }

    }



    // Stripes

    for (let x = 0; x < s; x += 4) {

        for (let y = 0; y < s; y++) img.setPixel(x, y, 1)

    }



    return img

}







function _buildTilesIntoSprites(map: number[][]): void {

    // Phaser runtime: NEVER represent wall tiles as Arcade sprites.

    // Rendering is handled by tileMapGlue/WorldTileRenderer using Phaser tilemap layers,

    // and collisions are handled by the engine's grid-based solver.

    if (isPhaserRuntime()) return



    const tile = WORLD_TILE_SIZE

    const wallImg = _createWallTileImage()



    for (let r = 0; r < map.length; r++) {

        const row = map[r]

        for (let c = 0; c < row.length; c++) {

            if (row[c] !== TILE_WALL) continue



            const s = sprites.create(wallImg, SpriteKind.Wall)

            s.left = c * tile

            s.top = r * tile

        }

    }

}



function _destroyAllInPlace(list: Sprite[]): void {

    for (let i = 0; i < list.length; i++) {

        const s = list[i]

        if (s && !(s.flags & sprites.Flag.Destroyed)) {

            s.destroy()

        }

    }

    list.length = 0

}



function _createDecorColliderImage(w: number, h: number): Image {

    // Invisible colliders still need a real image for width/height in overlap math.

    const img = image.create(w, h)

    img.fill(0)

    return img

}



// This is called after the base world grid exists.

// It must be safe to call multiple times (destroy + rebuild).

function initWorldDecorPostPass(): void {

    // Clear old decor (in case world is re-init’d)

    _destroyAllInPlace(_engineDecorTriggers)

    _destroyAllInPlace(_engineDecorSolids)



    // Allocate decals grid to match world

    const rows = _engineWorldTileMap ? (_engineWorldTileMap.length | 0) : 0

    const cols = (rows > 0 && _engineWorldTileMap[0]) ? (_engineWorldTileMap[0].length | 0) : 0



    _engineDecalGrid = []

    for (let r = 0; r < rows; r++) {

        const row: number[] = []

        for (let c = 0; c < cols; c++) row.push(DECAL_NONE)

        _engineDecalGrid.push(row)

    }



    if (rows <= 0 || cols <= 0) {

        _engineDecorRev = (_engineDecorRev + 1) | 0

        return

    }



    // ----------------------------------------------------------

    // Pick a WALKABLE center-ish tile for sand (robust)

    // ----------------------------------------------------------

    let sandR = (Math.idiv(rows, 2) | 0) + 3

    let sandC = (Math.idiv(cols, 2) | 0) - 4



    function isWalkable(r: number, c: number): boolean {

        if (r < 0 || c < 0 || r >= rows || c >= cols) return false

        return ((_engineWorldTileMap[r][c] | 0) !== TILE_WALL)

    }



    if (!isWalkable(sandR, sandC)) {

        // search outward for first walkable tile

        let found = false

        for (let rad = 1; rad <= 6 && !found; rad++) {

            for (let dr = -rad; dr <= rad && !found; dr++) {

                const r0 = (sandR + dr) | 0

                const cLeft = (sandC - rad) | 0

                const cRight = (sandC + rad) | 0

                if (isWalkable(r0, cLeft)) { sandR = r0; sandC = cLeft; found = true; break }

                if (isWalkable(r0, cRight)) { sandR = r0; sandC = cRight; found = true; break }

            }

            for (let dc = -rad; dc <= rad && !found; dc++) {

                const c0 = (sandC + dc) | 0

                const rUp = (sandR - rad) | 0

                const rDown = (sandR + rad) | 0

                if (isWalkable(rUp, c0)) { sandR = rUp; sandC = c0; found = true; break }

                if (isWalkable(rDown, c0)) { sandR = rDown; sandC = c0; found = true; break }

            }

        }

        // If still not found, keep original center (worst-case)

    }



    // Sand decal at chosen tile

    _engineDecalGrid[sandR][sandC] = DECAL_SAND_PATCH



    // ----------------------------------------------------------

    // Place rock SOLID adjacent to sand (prefer right, then left/down/up)

    // ----------------------------------------------------------

    let rockR = sandR

    let rockC = sandC



    const candidates = [

        { dr: 0, dc: 1 },

        { dr: 0, dc: -1 },

        { dr: 1, dc: 0 },

        { dr: -1, dc: 0 },

    ]



    for (let i = 0; i < candidates.length; i++) {

        const rr = (sandR + candidates[i].dr) | 0

        const cc = (sandC + candidates[i].dc) | 0

        if (isWalkable(rr, cc)) {

            rockR = rr

            rockC = cc

            break

        }

    }



    // ----------------------------------------------------------

    // Trigger collider sprite for sand (overlap proof)

    // ----------------------------------------------------------

    const sandImg = _createDecorColliderImage(WORLD_TILE_SIZE, WORLD_TILE_SIZE)

    const sandTrigger = sprites.create(sandImg, (SpriteKind as any).DecorTrigger)



    sandTrigger.left = (sandC * WORLD_TILE_SIZE) | 0

    sandTrigger.top = (sandR * WORLD_TILE_SIZE) | 0

    sandTrigger.setFlag(SpriteFlag.Invisible, true)



    sprites.setDataNumber(sandTrigger, DECOR_DATA.IS_COLLIDER, 1)

    sprites.setDataNumber(sandTrigger, DECOR_DATA.ID, DECAL_SAND_PATCH)

    sprites.setDataNumber(sandTrigger, DECOR_DATA.ROLE, DECOR_ROLE.TRIGGER)

    sprites.setDataString(sandTrigger, DECOR_DATA.NAME, "sand_patch")



    _engineDecorTriggers.push(sandTrigger)



    // ----------------------------------------------------------

    // Solid collider sprite for rock (overlap proof now; blocking later)

    // ----------------------------------------------------------

    const rockImg = _createDecorColliderImage(WORLD_TILE_SIZE, WORLD_TILE_SIZE)

    const rockSolid = sprites.create(rockImg, (SpriteKind as any).DecorSolid)



    rockSolid.left = (rockC * WORLD_TILE_SIZE) | 0

    rockSolid.top = (rockR * WORLD_TILE_SIZE) | 0

    rockSolid.setFlag(SpriteFlag.Invisible, true)



    sprites.setDataNumber(rockSolid, DECOR_DATA.IS_COLLIDER, 1)

    sprites.setDataNumber(rockSolid, DECOR_DATA.ID, PROP_ROCK_MOUNTAIN)

    sprites.setDataNumber(rockSolid, DECOR_DATA.ROLE, DECOR_ROLE.SOLID)

    sprites.setDataString(rockSolid, DECOR_DATA.NAME, "rock_mountain")



    _engineDecorSolids.push(rockSolid)



    // Revision bumps any time decor layout is (re)built

    _engineDecorRev = (_engineDecorRev + 1) | 0

}





// This is called ONLY by HeroEngine.start()

// This is called ONLY by HeroEngine.start()

function initWorldTileMap(): void {

    // Always build the numeric world grid (used by Phaser renderer + collision).

    _engineWorldTileMap = _createTileMap2D()



    // Decor post-pass (decals + trigger/solid colliders), art-agnostic.

    initWorldDecorPostPass()



    // NEW: bump world revision any time the world grid is rebuilt

    _engineWorldRev = (_engineWorldRev + 1) | 0



    // WORLD SNAPSHOT (high-level, low spam)

    if (DEBUG_WORLD_SNAPSHOT) {

        const map = _engineWorldTileMap

        const rows = (map && map.length) ? (map.length | 0) : 0

        const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0



        let walls = 0

        let floors = 0

        let sig = 0



        for (let r = 0; r < rows; r++) {

            const row = map[r]

            if (!row) continue

            for (let c = 0; c < cols; c++) {

                const v = (row[c] | 0)

                if (v === (TILE_WALL | 0)) walls++

                else floors++



                // cheap deterministic signature

                sig = (((sig << 5) - sig) + v + ((r + 1) * 131) + ((c + 1) * 17)) | 0

            }

        }



        console.log("[WORLD][MAP]", {

            worldRev: _engineWorldRev | 0,

            floorIndex: _dunFloorIndex | 0,

            floorKind: _dunFloorKind || "",

            baseFamily: _dunBaseFamily || "",

            wallFamily: _dunWallFamily || "",

            rows,

            cols,

            walls,

            floors,

            sig,

            decorRev: _engineDecorRev | 0,

        })

    }



    // Only the MakeCode Arcade runtime needs "walls as sprites".

    // Phaser renders walls as a Phaser tilemap layer, not sprite objects.

    if (isMakeCodeArcadeRuntime()) {

        _buildTilesIntoSprites(_engineWorldTileMap)

    }

}







function _readTile(r: number, c: number): number {

    if (r < 0 || r >= _engineWorldTileMap.length) return TILE_WALL

    if (c < 0 || c >= _engineWorldTileMap[0].length) return TILE_WALL

    return _engineWorldTileMap[r][c]

}



// ==========================================================

// TILEMAP COLLISION – HEROES + ENEMIES, WITH LOGGING

// Soft slide along walls instead of teleporting

// ==========================================================



let _tileCollFrame = 0



// HERO collision-only Y offset (pixels). Positive = collision sits lower than sprite center.

// Keep visuals/projectiles aligned by only applying this to collision math.

const HERO_COLLISION_Y_OFFSET_PX = 22



function _heroCollisionOffsetY(s: Sprite): number {

    try { return (getHeroIndex(s) >= 0) ? HERO_COLLISION_Y_OFFSET_PX : 0 } catch { return 0 }

}



function _boundsWithOffset(s: Sprite, offY: number) {

    const halfW = s.width >> 1

    const halfH = s.height >> 1

    const cx = s.x | 0

    const cy = ((s.y | 0) + (offY | 0)) | 0

    return {

        left: cx - halfW,

        right: cx + halfW - 1,

        top: cy - halfH,

        bottom: cy + halfH - 1,

        centerX: cx,

        centerY: cy

    }

}



// Check if an axis-aligned box overlaps any TILE_WALL

function _boxOverlapsWall(

    centerX: number,

    centerY: number,

    halfW: number,

    halfH: number

): boolean {

    const left = centerX - halfW

    const right = centerX + halfW - 1

    const top = centerY - halfH

    const bottom = centerY + halfH - 1

    return _boxOverlapsWallBounds(left, right, top, bottom)

}



function _dunUpdateInteractableFocus(nowMs: number): void {

    if (!DUNGEON_MODE_ACTIVE) return

    if (!_dunInteractables || _dunInteractables.length === 0) return



    // Clear focus outline on interactables each tick

    for (let i = 0; i < _dunInteractables.length; i++) {

        const it = _dunInteractables[i]

        if (!it || (it.flags & sprites.Flag.Destroyed)) continue

        _setFocusOutline(it, false)

    }



    let chestFocusThisTick = false

    let chestFocusR = -1

    let chestFocusC = -1



    for (let hi = 0; hi < 4; hi++) {

        const hero = heroes[hi]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue

        const owner = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

        if ((owner | 0) !== ((hi + 1) | 0)) continue



        let found: Sprite = null

        for (let i = 0; i < _dunInteractables.length; i++) {

            const it = _dunInteractables[i]

            if (!it || (it.flags & sprites.Flag.Destroyed)) continue



            const kind = sprites.readDataString(it, INTERACT_DATA.KIND)

            if (kind === "chest") {

                const opened = sprites.readDataNumber(it, INTERACT_DATA.OPENED) | 0

                try {

                    const g: any = globalThis as any

                    const last = (it as any).__dbgChestScanMs ?? -999999

                    if (DEBUG_CHEST_SCAN_LOGS && nowMs - last > 1000) {

                        (it as any).__dbgChestScanMs = nowMs

                        const inRange = _isHeroInInteractRange(hero, it, DUNGEON_INTERACT_EXTRA_X_PX, DUNGEON_INTERACT_EXTRA_Y_PX)

                        console.log("[FOCUS][CHEST][SCAN]", {

                            opened: opened ? 1 : 0,

                            inRange: inRange ? 1 : 0,

                            hero: { x: hero.x | 0, y: hero.y | 0 },

                            chest: { x: it.x | 0, y: it.y | 0 },

                            decor: {

                                r: (sprites.readDataNumber(it, "decorTileR") | 0),

                                c: (sprites.readDataNumber(it, "decorTileC") | 0),

                            }

                        })

                    }

                } catch { }

                if (opened) continue

            }



            if (_isHeroInInteractRange(hero, it, DUNGEON_INTERACT_EXTRA_X_PX, DUNGEON_INTERACT_EXTRA_Y_PX)) {

                found = it

                break

            }

        }



        if (found) {

            sprites.setDataNumber(hero, HERO_FOCUS_ACTIVE_KEY, 1)

            _setFocusOutline(found, true)

            try {

                if (sprites.readDataString(found, INTERACT_DATA.KIND) === "chest") {

                    chestFocusThisTick = true

                    chestFocusR = sprites.readDataNumber(found, "decorTileR") | 0

                    chestFocusC = sprites.readDataNumber(found, "decorTileC") | 0

                    const k = "__focusChestOnce_" + (found.id | 0);

                    const g: any = globalThis as any;

                    if (!g[k]) {

                        g[k] = 1;

                        console.log("[FOCUS][CHEST] highlight set", { id: found.id | 0, x: found.x | 0, y: found.y | 0 });

                    }

                }

            } catch { }

        }

    }



    // Directly drive the chest aura using the same path as the pillar.

    try {

        const want = chestFocusThisTick ? 1 : 0

        if (_dunChestFocusActive !== want) {

            _dunChestFocusActive = want

        }

        if (_dunChestFocusActive || (_dunChestTileR >= 0 && _dunChestTileC >= 0)) {

            const r = (chestFocusR >= 0) ? chestFocusR : (_dunChestTileR | 0)

            const c = (chestFocusC >= 0) ? chestFocusC : (_dunChestTileC | 0)

            if (r >= 0 && c >= 0) {

                const g: any = globalThis as any

                const sc: any = g ? g.__phaserScene : null

                const renderer: any = sc?.registry?.get?.("__worldTileRenderer")

                const ok = !!(renderer && typeof renderer.setPropFocusAuraAt === "function")

                let targetR = r

                let targetC = c

                if (DEBUG_CHEST_ROUTE_TO_PILLAR && _dunStairsStatueSolid) {

                    const sr = sprites.readDataNumber(_dunStairsStatueSolid, "decorTileR") | 0

                    const sc2 = sprites.readDataNumber(_dunStairsStatueSolid, "decorTileC") | 0

                    if (sr >= 0 && sc2 >= 0) {

                        targetR = sr

                        targetC = sc2

                    }

                }

                if (DEBUG_CHEST_ROUTE_TO_PILLAR && renderer) {

                    try {

                        (renderer as any).__dbgAuraOverrideTarget = { r: (r | 0), c: (c | 0) }

                    } catch { /* ignore */ }

                } else if (renderer) {

                    try { (renderer as any).__dbgAuraOverrideTarget = null } catch { /* ignore */ }

                }

                if (ok) renderer.setPropFocusAuraAt(targetR, targetC, !!_dunChestFocusActive, 2, 1)

                if (DEBUG_FOCUS_DIRECT_LOGS) {

                    if (!(_dunChestSolid as any)?.__loggedChestDirect || !_dunChestFocusActive) {

                        if (_dunChestSolid) (_dunChestSolid as any).__loggedChestDirect = 1

                        console.log("[FOCUS][CHEST][DIRECT]", {

                            r,

                            c,

                            active: _dunChestFocusActive ? 1 : 0,

                            renderer: ok,

                            target: DEBUG_CHEST_ROUTE_TO_PILLAR ? "pillar" : "chest",

                            targetR,

                            targetC,

                            overridePos: DEBUG_CHEST_ROUTE_TO_PILLAR ? { r: r | 0, c: c | 0 } : null

                        })

                    }

                }

            }

        }

    } catch { /* ignore */ }

}



const SHOPKEEPER_FORCE_MOVE_NOW_KEY = "shopkeeperForceMove"

const SHOPKEEPER_FORCE_MOVE_X_KEY = "shopkeeperForceX"

const SHOPKEEPER_FORCE_MOVE_Y_KEY = "shopkeeperForceY"



function _shopTryMoveShopkeeperTo(x: number, y: number): boolean {

    if (!shopkeeperNpc) return false

    const halfW = shopkeeperNpc.width >> 1

    const halfH = shopkeeperNpc.height >> 1

    const collOffY = _heroCollisionOffsetY(shopkeeperNpc)

    const cy = (y + collOffY) | 0

    const left = (x - halfW) | 0

    const right = (x + halfW - 1) | 0

    const top = (cy - halfH) | 0

    const bottom = (cy + halfH - 1) | 0

    if (_boxOverlapsWallBounds(left, right, top, bottom)) return false

    shopkeeperNpc.setPosition(x, y)

    return true

}



function _shopRescueShopkeeperFromWalls(): void {

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return



    const b = _boundsWithOffset(shopkeeperNpc, _heroCollisionOffsetY(shopkeeperNpc))

    if (!_boxOverlapsWallBounds(b.left, b.right, b.top, b.bottom)) return



    const tileSize = WORLD_TILE_SIZE | 0

    const rows = _engineWorldTileMap.length | 0

    const cols = _engineWorldTileMap[0].length | 0

    if (tileSize <= 0 || rows <= 0 || cols <= 0) return



    const startR = Math.max(0, Math.min(rows - 1, Math.idiv((shopkeeperNpc.y | 0), tileSize))) | 0

    const startC = Math.max(0, Math.min(cols - 1, Math.idiv((shopkeeperNpc.x | 0), tileSize))) | 0



    const maxRadius = 4

    for (let r = 0; r <= maxRadius; r++) {

        for (let dr = -r; dr <= r; dr++) {

            for (let dc = -r; dc <= r; dc++) {

                if (Math.abs(dr) !== r && Math.abs(dc) !== r) continue

                const rr = startR + dr

                const cc = startC + dc

                if (rr < 0 || rr >= rows || cc < 0 || cc >= cols) continue

                if ((_engineWorldTileMap[rr][cc] | 0) === TILE_WALL) continue

                const px = _dunColToX(cc)

                const py = _dunRowToY(rr)

                if (_shopTryMoveShopkeeperTo(px, py)) return

            }

        }

    }

}



function _shopApplyForceMoveIfRequested(): void {

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return

    const req = sprites.readDataNumber(shopkeeperNpc, SHOPKEEPER_FORCE_MOVE_NOW_KEY) | 0

    if (!req) return

    const fx = sprites.readDataNumber(shopkeeperNpc, SHOPKEEPER_FORCE_MOVE_X_KEY) | 0

    const fy = sprites.readDataNumber(shopkeeperNpc, SHOPKEEPER_FORCE_MOVE_Y_KEY) | 0

    shopkeeperNpc.setPosition(fx, fy)

    sprites.setDataNumber(shopkeeperNpc, SHOPKEEPER_FORCE_MOVE_NOW_KEY, 0)

}



function _shopUpdateFocusHighlights(nowMs: number): void {

    const now = nowMs | 0

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    // Clear outlines by default

    _setFocusOutline(shopkeeperNpc, false)

    for (let i = 0; i < (shopStatues ? shopStatues.length : 0); i++) {

        const st = shopStatues[i]

        if (!st || (st.flags & sprites.Flag.Destroyed)) continue

        _setFocusOutline(st, false)

    }



    // Statues: highlight when focused

    for (let i = 0; i < (shopStatues ? shopStatues.length : 0); i++) {

        const st = shopStatues[i]

        if (!st || (st.flags & sprites.Flag.Destroyed)) continue

        if (_shopIsStatueFocused(st, now)) {

            _setFocusOutline(st, true)

        }

    }



    // Shopkeeper: highlight when a hero is close enough to interact

    let keeperFocused = false

    for (let hi = 0; hi < 4; hi++) {

        const hero = heroes[hi]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue

        const owner = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

        if ((owner | 0) !== ((hi + 1) | 0)) continue

        if (now <= (shopFocusUntilMsByHero[hi] | 0)) continue

        if (_isHeroInInteractRange(hero, shopkeeperNpc, NPC_INTERACT_EXTRA_X_PX, NPC_INTERACT_EXTRA_Y_PX)) {

            sprites.setDataNumber(hero, HERO_FOCUS_ACTIVE_KEY, 1)

            keeperFocused = true

        }

    }

    if (keeperFocused) _setFocusOutline(shopkeeperNpc, true)

}



function updateGenericFocus(nowMs: number): void {

    // Clear generic focus for all player heroes (will re-arm below as needed)

    for (let hi = 0; hi < 4; hi++) {

        const hero = heroes[hi]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue

        sprites.setDataNumber(hero, HERO_FOCUS_ACTIVE_KEY, 0)

    }



    _dunUpdateInteractableFocus(nowMs)

    _shopUpdateFocusHighlights(nowMs)

}



function _boxOverlapsWallBounds(

    left: number,

    right: number,

    top: number,

    bottom: number

): boolean {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return false



    const map = _engineWorldTileMap

    const rows = map.length

    const cols = map[0].length

    const tileSize = WORLD_TILE_SIZE



    const minCol = Math.idiv(left, tileSize)

    const maxCol = Math.idiv(right, tileSize)

    const minRow = Math.idiv(top, tileSize)

    const maxRow = Math.idiv(bottom, tileSize)



    for (let r = minRow; r <= maxRow; r++) {

        if (r < 0 || r >= rows) continue

        const rowArr = map[r]

        for (let c = minCol; c <= maxCol; c++) {

            if (c < 0 || c >= cols) continue

            if (rowArr[c] === TILE_WALL) {

                return true

            }

        }

    }

    return false

}







// Soft-slide resolver for a group (heroes or enemies)

function _resolveTilemapCollisionsForGroup(group: Sprite[], label: string): void {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return



    const tileSize = WORLD_TILE_SIZE

    const map = _engineWorldTileMap

    const rows = map.length

    const cols = map[0].length



    // Log occasionally so we can see what's happening

    const doFrameLog = (_tileCollFrame % 30) === 0

    if (doFrameLog) {

        console.log(

            "[tileColl] frame" + _tileCollFrame +

            "group" + label +

            "count" + group.length +

            "map" + rows + "x" + cols +

            "tileSize" + tileSize

        )

    }



    for (let i = 0; i < group.length; i++) {

        const s = group[i]

        if (!s) continue



        const prevX = sprites.readDataNumber(s, HERO_DATA.PREV_X)

        const prevY = sprites.readDataNumber(s, HERO_DATA.PREV_Y)

        const collOffY = _heroCollisionOffsetY(s)

        const cx = s.x

        const cy = s.y + collOffY



        const halfW = s.width >> 1

        const halfH = s.height >> 1



        // If we don't have a prev snapshot, skip for this frame

        if (!(prevX || prevX === 0) || !(prevY || prevY === 0)) continue



        // ------------------------------------------

        // Soft slide resolution:

        // 1) test X movement (cx, prevY)

        // 2) then test Y (finalX, cy)

        // ------------------------------------------



        let finalX = cx

        let finalY = cy

        let blockedX = false

        let blockedY = false



        // Test horizontal movement (X) first

        if (_boxOverlapsWallBounds(

            cx - halfW,

            cx + halfW - 1,

            (prevY + collOffY) - halfH,

            (prevY + collOffY) + halfH - 1

        )) {

            blockedX = true

            finalX = prevX  // can't move into the wall; keep previous X

        } else {

            finalX = cx     // X is ok, Y will be resolved next

        }



        // Test vertical movement (Y) with resolved X

        if (_boxOverlapsWallBounds(

            finalX - halfW,

            finalX + halfW - 1,

            cy - halfH,

            cy + halfH - 1

        )) {

            blockedY = true

            finalY = prevY + collOffY  // can't move into the wall; keep previous Y

        } else {

            finalY = cy

        }



        // Apply final position

        s.x = finalX

        s.y = finalY - collOffY



        // Zero out velocity on the blocked axes so they "slide"

        if (blockedX) s.vx = 0

        if (blockedY) s.vy = 0



        if (blockedX || blockedY) {

            console.log(

                "[tileColl]" + label + "#" + i +

                "blockedX" + blockedX + "blockedY" + blockedY +

                "prev=(" + prevX + "," + prevY + ")" +

                "curr=(" + cx + "," + cy + ")" +

                "final=(" + finalX + "," + (finalY - collOffY) + ")"

            )

        } else if (doFrameLog && i === 0) {

            // Occasional sample log even when no collision,

            // so we know the system is actually running.

            console.log(

                "[tileColl]" + label + "#" + i +

                "no collision" +

                "prev=(" + prevX + "," + prevY + ")" +

                "curr=(" + cx + "," + (cy - collOffY) + ")"

            )

        }

    }

}



function resolveHeroTilemapCollisions(): void {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return



    const map = _engineWorldTileMap

    const rows = map.length

    const cols = map[0].length

    const tileSize = WORLD_TILE_SIZE



    // Resolve collision for a single sprite (hero or enemy)

    function resolveForSprite(s: Sprite) {

        if (!s) return



        const halfW = s.width >> 1

        const halfH = s.height >> 1

        const collOffY = _heroCollisionOffsetY(s)



        // Run a couple of passes in case we overlap more than one tile

        for (let iter = 0; iter < 3; iter++) {

            const cx = s.x

            const cy = s.y + collOffY

            const b = _boundsWithOffset(s, collOffY)

            const left = b.left

            const right = b.right

            const top = b.top

            const bottom = b.bottom



            const minCol = Math.idiv(left, tileSize)

            const maxCol = Math.idiv(right, tileSize)

            const minRow = Math.idiv(top, tileSize)

            const maxRow = Math.idiv(bottom, tileSize)



            let moved = false



            for (let r = minRow; r <= maxRow; r++) {

                if (r < 0 || r >= rows) continue

                const rowArr = map[r]





                for (let c = minCol; c <= maxCol; c++) {

                    const type = rowArr[c] | 0; // force 0 if undefined

                    const def = TILE_COLLISION_DEFS[type] || TILE_COLLISION_DEFS[0];

                    if (!def.solid) continue;



                    // Build the tile's collision rect in WORLD space,

                    // using per-type offsets and size.

                    const shapeLeft   = c * tileSize + def.offsetX;

                    const shapeRight  = shapeLeft + def.width;

                    const shapeTop    = r * tileSize + def.offsetY;

                    const shapeBottom = shapeTop + def.height;



                    // Compute overlaps on each side (sprite vs collision shape)

                    const overlapLeft   = right  - shapeLeft;

                    const overlapRight  = shapeRight - left;

                    const overlapTop    = bottom - shapeTop;

                    const overlapBottom = shapeBottom - top;



                    // If any are <= 0, AABBs don't overlap on that axis

                    if (overlapLeft <= 0 || overlapRight <= 0 || overlapTop <= 0 || overlapBottom <= 0) {

                        continue;

                    }



                    // Minimal penetration on each axis

                    const penX = overlapLeft < overlapRight ? overlapLeft : overlapRight;

                    const penY = overlapTop < overlapBottom ? overlapTop : overlapBottom;



                    if (penX < penY) {

                        // Push in X

                        const shapeCenterX = shapeLeft + def.width / 2;

                        if (s.x < shapeCenterX) {

                            s.x -= penX;

                        } else {

                            s.x += penX;

                        }

                        // Soft slide: kill only X velocity

                        s.vx = 0;

                    } else {

                        // Push in Y

                        const shapeCenterY = shapeTop + def.height / 2;

                        if (cy < shapeCenterY) {

                            s.y -= penY;

                        } else {

                            s.y += penY;

                        }

                        // Soft slide: kill only Y velocity

                        s.vy = 0;

                    }



                    moved = true;



                }







            }



            // If we didn't adjust position this pass, we are out of walls

            if (!moved) break

        }

    }



    // Apply to all heroes

    for (let hi = 0; hi < heroes.length; hi++) {

        const h = heroes[hi]

        if (!h) continue

        if (h.flags & sprites.Flag.Ghost) continue

        resolveForSprite(h)

    }



    // Apply to all enemies

    for (let ei = 0; ei < enemies.length; ei++) {

        const e = enemies[ei]

        if (e) resolveForSprite(e)

    }

}



// Main entry to call from onUpdate

function resolveTilemapCollisions(): void {

    _tileCollFrame++

    resolveHeroTilemapCollisions()

    //_resolveTilemapCollisionsForGroup(heroes, "Hero")

    //_resolveTilemapCollisionsForGroup(enemies, "Enemy")

}







function decor_getDecalAtTile(r: number, c: number): number {

    if (!_engineDecalGrid || _engineDecalGrid.length === 0) return DECAL_NONE

    if (r < 0 || c < 0) return DECAL_NONE

    if (r >= _engineDecalGrid.length) return DECAL_NONE

    const row = _engineDecalGrid[r]

    if (!row || c >= row.length) return DECAL_NONE

    return row[c] | 0

}



// Publish hero underfoot tile coords + decal id for student logic.

// Must be called AFTER resolveTilemapCollisions() so it reflects final positions.

function updateHeroUnderfootTilesAndDecals(nowMs: number): void {

    const tileSize = WORLD_TILE_SIZE | 0



    // Prefer world grid dims if present; fallback to decal grid dims.

    const rows = (_engineWorldTileMap && _engineWorldTileMap.length > 0)

        ? (_engineWorldTileMap.length | 0)

        : (_engineDecalGrid ? (_engineDecalGrid.length | 0) : 0)



    const cols = (rows > 0)

        ? ((_engineWorldTileMap && _engineWorldTileMap[0] && _engineWorldTileMap[0].length > 0)

            ? (_engineWorldTileMap[0].length | 0)

            : (_engineDecalGrid && _engineDecalGrid[0] ? (_engineDecalGrid[0].length | 0) : 0))

        : 0



    for (let hi = 0; hi < heroes.length; hi++) {

        const h = heroes[hi]

        if (!h) continue



        if (rows <= 0 || cols <= 0 || tileSize <= 0) {

            sprites.setDataNumber(h, HERO_DATA.TILE_R, -1)

            sprites.setDataNumber(h, HERO_DATA.TILE_C, -1)

            sprites.setDataNumber(h, HERO_DATA.DECAL_ID_UNDERFOOT, DECAL_NONE)

            continue

        }



        // Define "underfoot tile" as the tile containing the hero's center.

        // (If you later want "feet point", we can change to y + halfH - 1.)

        let c = Math.idiv((h.x | 0), tileSize) | 0

        let r = Math.idiv((h.y | 0), tileSize) | 0



        // Clamp to world bounds (keeps values sane if near edges)

        if (c < 0) c = 0

        else if (c >= cols) c = (cols - 1) | 0



        if (r < 0) r = 0

        else if (r >= rows) r = (rows - 1) | 0



        const decalId = decor_getDecalAtTile(r, c) | 0



        sprites.setDataNumber(h, HERO_DATA.TILE_R, r)

        sprites.setDataNumber(h, HERO_DATA.TILE_C, c)

        sprites.setDataNumber(h, HERO_DATA.DECAL_ID_UNDERFOOT, decalId)

    }

}



// --------------------------------------------------------------

// DECOR SOLID BLOCKING HOOK (PLANNED LOCATION, DISABLED BY DEFAULT)

// This MUST remain a NOOP unless explicitly enabled.

// --------------------------------------------------------------

let DECOR_SOLID_BLOCKING_ENABLED = true



function decorSolids_blockingHook(nowMs: number): void {

    if (!DECOR_SOLID_BLOCKING_ENABLED) return

    if (!_engineDecorSolids || _engineDecorSolids.length === 0) return



    // Local helpers: AABB overlap using Arcade sprite bounds

    function overlaps(a: Sprite, b: Sprite): boolean {

        const ab = _boundsWithOffset(a, _heroCollisionOffsetY(a))

        const bb = _boundsWithOffset(b, _heroCollisionOffsetY(b))

        return (ab.left < bb.right) && (ab.right > bb.left) && (ab.top < bb.bottom) && (ab.bottom > bb.top)

    }



    function anySolidOverlap(h: Sprite): boolean {

        for (let i = 0; i < _engineDecorSolids.length; i++) {

            const s = _engineDecorSolids[i]

            if (!s || (s.flags & sprites.Flag.Destroyed)) continue

            if (overlaps(h, s)) return true

        }

        return false

    }



    // Fallback: resolve overlap by minimal penetration (tight AABB already applied in Phaser wrapper).

    // This is only used when rollback cannot resolve (bad/unstable PREV_*).

    function resolveByPenetrationOnce(h: Sprite): boolean {

        let bestAxis = 0 // 1 = x, 2 = y

        let bestPush = 0

        let bestMag = 1 << 30



        for (let i = 0; i < _engineDecorSolids.length; i++) {

            const s = _engineDecorSolids[i]

            if (!s || (s.flags & sprites.Flag.Destroyed)) continue

            const hb = _boundsWithOffset(h, _heroCollisionOffsetY(h))

            const sb = _boundsWithOffset(s, _heroCollisionOffsetY(s))

            if (!((hb.left < sb.right) && (hb.right > sb.left) && (hb.top < sb.bottom) && (hb.bottom > sb.top))) continue



            const hcx = ((hb.left + hb.right) >> 1) | 0

            const hcy = ((hb.top + hb.bottom) >> 1) | 0

            const scx = ((sb.left + sb.right) >> 1) | 0

            const scy = ((sb.top + sb.bottom) >> 1) | 0



            // Penetrations (positive when overlapping)

            const penLeft = (hb.right - sb.left) | 0   // push left by this (negative)

            const penRight = (sb.right - hb.left) | 0  // push right by this (positive)

            const penUp = (hb.bottom - sb.top) | 0     // push up by this (negative)

            const penDown = (sb.bottom - hb.top) | 0   // push down by this (positive)



            // Candidate pushes based on relative centers (stable direction choice)

            const pushX = (hcx < scx) ? (-(penLeft | 0)) : (penRight | 0)

            const pushY = (hcy < scy) ? (-(penUp | 0)) : (penDown | 0)



            const magX = Math.abs(pushX) | 0

            const magY = Math.abs(pushY) | 0



            // Choose minimal axis for THIS solid

            let axis = 1

            let push = pushX

            let mag = magX



            if (magY < magX) {

                axis = 2

                push = pushY

                mag = magY

            }



            if (mag > 0 && mag < bestMag) {

                bestMag = mag

                bestAxis = axis

                bestPush = push

            }

        }



        if (!bestAxis || bestMag >= (1 << 29)) return false



        if (bestAxis === 1) {

            h.x = ((h.x | 0) + (bestPush | 0)) | 0

            try { (h.vx as any) = 0 } catch { }

        } else {

            h.y = ((h.y | 0) + (bestPush | 0)) | 0

            try { (h.vy as any) = 0 } catch { }

        }



        return true

    }



    const MAX_FALLBACK_ITERS = 6



    // Resolve per hero

    for (let hi = 0; hi < heroes.length; hi++) {

        const h = heroes[hi]

        if (!h) continue

        if (h.flags & sprites.Flag.Ghost) continue



        if (!anySolidOverlap(h)) continue



        // Read "prev" position (set earlier each tick for tile rollback).

        let px = sprites.readDataNumber(h, HERO_DATA.PREV_X) | 0

        let py = sprites.readDataNumber(h, HERO_DATA.PREV_Y) | 0



        const cx = h.x | 0

        const cy = h.y | 0



        if ((px === 0 && py === 0) && (cx !== 0 || cy !== 0)) {

            px = cx

            py = cy

        }



        let dx = (cx - px) | 0

        let dy = (cy - py) | 0



        // If PREV_* is stale/overwritten, dx/dy can be 0 even while overlapping.

        // Use velocity direction only for axis preference in that case.

        if (dx === 0 && dy === 0) {

            try { dx = (h.vx as any) | 0 } catch { dx = 0 }

            try { dy = (h.vy as any) | 0 } catch { dy = 0 }

        }



        const preferX = (Math.abs(dx) >= Math.abs(dy))



        const ox = cx

        const oy = cy



        let resolved = false



        if (preferX) {

            if (dx !== 0) {

                h.x = px

                if (!anySolidOverlap(h)) {

                    try { (h.vx as any) = 0 } catch { }

                    resolved = true

                } else {

                    h.x = ox

                }

            }



            if (!resolved && dy !== 0) {

                h.y = py

                if (!anySolidOverlap(h)) {

                    try { (h.vy as any) = 0 } catch { }

                    resolved = true

                } else {

                    h.y = oy

                }

            }

        } else {

            if (dy !== 0) {

                h.y = py

                if (!anySolidOverlap(h)) {

                    try { (h.vy as any) = 0 } catch { }

                    resolved = true

                } else {

                    h.y = oy

                }

            }



            if (!resolved && dx !== 0) {

                h.x = px

                if (!anySolidOverlap(h)) {

                    try { (h.vx as any) = 0 } catch { }

                    resolved = true

                } else {

                    h.x = ox

                }

            }

        }



        // Fallback: if rollback didn't resolve (or dx/dy were useless), push out by penetration.

        if (!resolved) {

            for (let it = 0; it < MAX_FALLBACK_ITERS; it++) {

                if (!anySolidOverlap(h)) { resolved = true; break }

                if (!resolveByPenetrationOnce(h)) break

            }

        }



        // Last resort: revert fully

        if (!resolved) {

            h.x = px

            h.y = py

            try { (h.vx as any) = 0 } catch { }

            try { (h.vy as any) = 0 } catch { }

        }

    }

}





