const INT_SPELL_SPRITE_KEY = "__intSpellSprite"



const INT_TERM_HIT_KEY = "INT_THIT"



const INT_PULSE_PERIOD_MS_KEY = "__intPulsePeriodMs";

const INT_PULSE_NEXT_AT_MS_KEY = "__intPulseNextAtMs";

const INT_PULSE_WINDOW_END_MS_KEY = "__intPulseWindowEndMs";

const INT_PULSE_HIT_MASK_KEY = "__intPulseHitMask";

const INT_PULSE_TOTAL_KEY = "__intPulseTotal";

const INT_PULSE_LEFT_KEY = "__intPulseLeft";





function calculateIntellectStats(baseTimeMs: number, traits: number[]) {

    const stats = makeBaseStats(baseTimeMs)



    // Pull raw trait values and floor at 0 (no upper caps)

    const axis = BALANCE.MOVES.AXIS_WEIGHT_X1000

    let tEnergy = applyAxisWeight(traits[1], axis.DAMAGE)   // energy / inertia

    let tSize = applyAxisWeight(traits[2], axis.REACH)   // AOE size

    let tTarget = applyAxisWeight(traits[3], axis.TIME)   // max targeting duration

    let tWeak = applyAxisWeight(traits[4], axis.STATUS)   // weakness debuff



    if (tEnergy < 0) tEnergy = 0

    if (tSize < 0) tSize = 0

    if (tTarget < 0) tTarget = 0

    if (tWeak < 0) tWeak = 0



    // ----------------------------------------------------

    // TARGETING DURATION (traits[3])

    // ----------------------------------------------------

    // How long you can "aim" the spell before it fires.

    // Base 500ms + 50ms per point of tTarget (can get absurdly long).

    let targetingTime = BALANCE.MOVES.INTELLECT.TARGETING_BASE_MS + tTarget * BALANCE.MOVES.INTELLECT.TARGETING_PER_POINT_MS

    // Safety: never allow 0 or negative (shouldn't happen with floor, but just in case):

    if (targetingTime < BALANCE.MOVES.INTELLECT.TARGETING_MIN_MS) {

        targetingTime = BALANCE.MOVES.INTELLECT.TARGETING_MIN_MS

    }

    stats[STAT.TARGETING_TIME] = targetingTime



    // ----------------------------------------------------

    // AOE SIZE (traits[2]) ? ring radius

    // ----------------------------------------------------

    // Base radius 8px + 1px per point of tSize.

    // No cap here; huge values just mean huge circles.

    stats[STAT.RING_RADIUS] = BALANCE.MOVES.INTELLECT.RING_RADIUS_BASE_PX + tSize * BALANCE.MOVES.INTELLECT.RING_RADIUS_PER_POINT_PX



    // ----------------------------------------------------

    // ENERGY / INERTIA (traits[1]) ? damage, channel power, move duration

    // ----------------------------------------------------

    // Damage multiplier: base + asymptotic bonus for diminishing returns.

    const dmgBase = BALANCE.MOVES.INTELLECT.DAMAGE_BASE

    const dmgBonus = asymptoticBonusPct(

        tEnergy,

        BALANCE.MOVES.INTELLECT.ENERGY_BONUS_MAX_PCT,

        BALANCE.MOVES.INTELLECT.ENERGY_BONUS_HALF_POINTS

    )

    stats[STAT.DAMAGE_MULT] = dmgBase + dmgBonus



    // Channel power: 100 base + 5 per point of tEnergy

    stats[STAT.CHANNEL_POWER] = BALANCE.MOVES.INTELLECT.CHANNEL_POWER_BASE + tEnergy * BALANCE.MOVES.INTELLECT.CHANNEL_POWER_PER_POINT



    // Move duration: baseTimeMs + 5ms per point of tEnergy

    // (Big, heavy, high-energy spells take longer.)

    let moveDur = baseTimeMs + tEnergy * BALANCE.MOVES.INTELLECT.MOVE_DURATION_PER_POINT_MS

    if (moveDur < BALANCE.MOVES.INTELLECT.MOVE_DURATION_MIN_MS) {

        moveDur = BALANCE.MOVES.INTELLECT.MOVE_DURATION_MIN_MS

    }

    stats[STAT.MOVE_DURATION] = moveDur



    // ----------------------------------------------------

    // WEAKNESS (traits[4]) ? debuff strength and duration

    // ----------------------------------------------------

    // Weaken percent: 5% base + 1% per point of tWeak

    stats[STAT.WEAKEN_PCT] = BALANCE.MOVES.INTELLECT.WEAKEN_BASE_PCT + tWeak * BALANCE.MOVES.INTELLECT.WEAKEN_PER_POINT_PCT



    // Weaken duration: 500ms base + 20ms per point of tWeak

    stats[STAT.WEAKEN_DURATION] = BALANCE.MOVES.INTELLECT.WEAKEN_DURATION_BASE_MS + tWeak * BALANCE.MOVES.INTELLECT.WEAKEN_DURATION_PER_POINT_MS



    return stats

}



function maybeDetonateIntellectSpellsOnWall(nowMs: number): void {

    // Needs a world grid to test against

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return



    const now = nowMs | 0

    const tile = WORLD_TILE_SIZE | 0



    // Attempt wall-detonate for ONE sprite if it is an eligible INT spell

    function tryDetonateSpell(spell: Sprite, heroIndexHint: number): void {

        if (!spell || (spell.flags & sprites.Flag.Destroyed)) return



        // Only INT spells

        const fam = sprites.readDataNumber(spell, PROJ_DATA.FAMILY) | 0

        if (fam !== (FAMILY.INTELLECT | 0)) return



        // Already detonated? nothing to do

        const detonated = sprites.readDataNumber(spell, INT_DETONATED_KEY) | 0

        if (detonated) return



        // Idempotence gate: if a terminus was already chosen (enemy hit sets 2), don't re-request

        const termHit = sprites.readDataNumber(spell, PROJ_DATA.TERMINUS_HIT) | 0

        if (termHit !== 0) return



        // Activation gating (safe: only gates if ACTIVATE_AT_MS is explicitly set)

        const activateAt = sprites.readDataNumber(spell, PROJ_DATA.ACTIVATE_AT_MS) | 0

        if (activateAt > 0 && now < activateAt) return



        // Wall overlap test

        const halfW = Math.max(1, spell.width >> 1)

        const halfH = Math.max(1, spell.height >> 1)

        if (!_boxOverlapsWall(spell.x, spell.y, halfW, halfH)) return



        // Determine heroIndex (prefer sprite data, fallback to hint)

        const hiData = sprites.readDataNumber(spell, PROJ_DATA.HERO_INDEX) | 0

        let heroIndex = hiData

        if (!(heroIndex >= 0 && heroIndex < heroes.length)) heroIndex = heroIndexHint | 0

        if (!(heroIndex >= 0 && heroIndex < heroes.length)) return



        // Record terminus (wall)

        sprites.setDataNumber(spell, PROJ_DATA.TERMINUS_HIT, 1)

        sprites.setDataNumber(spell, PROJ_DATA.TERMINUS_X, spell.x | 0)

        sprites.setDataNumber(spell, PROJ_DATA.TERMINUS_Y, spell.y | 0)

        sprites.setDataNumber(spell, PROJ_DATA.TERMINUS_MS, now)



        // Debug line only when we actually request detonation

        const r = Math.idiv((spell.y | 0), tile) | 0

        const c = Math.idiv((spell.x | 0), tile) | 0

        console.log("[INT][WALL] detonate request hero=" + heroIndex + " at tile=(" + r + "," + c + ")")



        // Request detonation the same way the Enemy overlap does

        detonateIntellectSpellForHero(

            heroIndex,

            spell,

            now,

            "INTELLECT_DETONATE_REQUEST_HIT_WALL",

            "maybeDetonateIntellectSpellsOnWall"

        )

    }



    // (1) Primary: spells currently owned by hero control

    for (let heroIndex = 0; heroIndex < heroes.length; heroIndex++) {

        const spell = heroControlledSpells[heroIndex]

        if (spell) tryDetonateSpell(spell, heroIndex)

    }



    // (2) Also scan heroProjectiles (covers cases where INT spells are stored there)

    for (let i = 0; i < heroProjectiles.length; i++) {

        const proj = heroProjectiles[i]

        if (!proj || (proj.flags & sprites.Flag.Destroyed)) continue

        tryDetonateSpell(proj, -1)

    }

}





function executeIntellectMove(

    heroIndex: number,

    hero: Sprite,

    button: string,

    traits: number[],

    stats: number[],

    now: number

) {

    const nowMs = now | 0



    // Total time the spell exists pre-detonation (THIS is your "16 seconds")

    const targetingTime = (stats[STAT.TARGETING_TIME] | 0) || 16000



    const baseDmg = getBasePower(FAMILY.INTELLECT)

    const dmgMult = stats[STAT.DAMAGE_MULT] | 0

    let castDmg = Math.idiv(baseDmg * (dmgMult || 100), 100)

    if (castDmg < 1) castDmg = 1



    const radiusPx = Math.max(1, stats[STAT.RING_RADIUS] | 0)

    const weakenPct = stats[STAT.WEAKEN_PCT] | 0

    const weakenDur = stats[STAT.WEAKEN_DURATION] | 0



    const axis = BALANCE.MOVES.AXIS_WEIGHT_X1000

    let tEnergy = applyAxisWeight(traits[1], axis.DAMAGE)

    if (tEnergy < 0) tEnergy = 0



    let tTime = applyAxisWeight(traits[3], axis.TIME)

    if (tTime < 0) tTime = 0



    let pulseCount = BALANCE.MOVES.INTELLECT.PULSE_COUNT | 0

    if (pulseCount < 1) pulseCount = 1



    let perPulseDmg = Math.idiv(castDmg * BALANCE.MOVES.INTELLECT.PULSE_DAMAGE_PCT_X1000, 1000)

    if (perPulseDmg < 1) perPulseDmg = 1



    const pulsePeriodMs = intellectPulsePeriodMs(perPulseDmg | 0, tTime | 0)



    sprites.setDataNumber(hero, INT_CAST_PULSE_COUNT_KEY, pulseCount | 0)

    sprites.setDataNumber(hero, INT_CAST_PULSE_DMG_KEY, perPulseDmg | 0)

    sprites.setDataNumber(hero, INT_PULSE_PERIOD_MS_KEY, pulsePeriodMs | 0)



    let speed = BALANCE.MOVES.INTELLECT.SPEED_BASE + tEnergy * BALANCE.MOVES.INTELLECT.SPEED_PER_POINT

    if (speed < 1) speed = 1



    let maxSpeed = speed + BALANCE.MOVES.INTELLECT.SPEED_MAX_BONUS + tEnergy * BALANCE.MOVES.INTELLECT.SPEED_MAX_PER_POINT

    if (maxSpeed < speed) maxSpeed = speed



    let accel = BALANCE.MOVES.INTELLECT.STEER_ACCEL_BASE - tEnergy * BALANCE.MOVES.INTELLECT.STEER_ACCEL_PER_POINT

    if (accel < BALANCE.MOVES.INTELLECT.STEER_ACCEL_MIN) accel = BALANCE.MOVES.INTELLECT.STEER_ACCEL_MIN



    sprites.setDataNumber(hero, INT_CAST_DMG_KEY, castDmg | 0)

    sprites.setDataNumber(hero, INT_CAST_DMG_MULT_KEY, dmgMult | 0)

    sprites.setDataNumber(hero, INT_CAST_RADIUS_KEY, radiusPx | 0)

    sprites.setDataNumber(hero, INT_CAST_WEAK_PCT_KEY, weakenPct | 0)

    sprites.setDataNumber(hero, INT_CAST_WEAK_DUR_KEY, weakenDur | 0)

    sprites.setDataNumber(hero, INT_CAST_SPEED_KEY, speed | 0)

    sprites.setDataNumber(hero, INT_CAST_SPEED_MAX_KEY, maxSpeed | 0)

    sprites.setDataNumber(hero, INT_CAST_ACCEL_KEY, accel | 0)



    const produceMs = INT_PRODUCE_DUR_MS | 0

    const spawnAt = (nowMs + produceMs) | 0



    const expiresAt = (nowMs + (targetingTime | 0)) | 0



    // Hero control metadata

    sprites.setDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL, true)



    // Store delayed spawn + lifetime on hero (so updateIntellectSpellsControl drives the timeline)

    sprites.setDataNumber(hero, INT_CAST_SPAWN_AT_MS_KEY, spawnAt)

    sprites.setDataNumber(hero, INT_SPELL_EXPIRES_AT_MS_KEY, expiresAt)

    console.log("Set the intellect spell lifetime to ", expiresAt)

    sprites.setDataNumber(hero, INT_CAST_FAMILY_KEY, FAMILY.INTELLECT)

    sprites.setDataString(hero, INT_CAST_BUTTON_KEY, button)

    sprites.setDataNumber(hero, INT_CAST_LAND_END_MS_KEY, 0)



    // Phase = cast for the whole segmented window

    setHeroPhaseString(heroIndex, "cast")

    sprites.setDataString(hero, HERO_DATA.ActionKind, "intellect_cast")



    // Phase window includes: produce + drive + land

    const totalCastMs = ((targetingTime | 0) + (INT_LAND_DUR_MS | 0)) | 0



    _dbgContract_noteWhy(heroIndex, "INTELLECT_CAST_BEGIN", "executeIntellectMove")



    _animKeys_stampPhaseWindow(

        heroIndex,

        hero,

        "cast",

        nowMs | 0,

        totalCastMs | 0,

        "INTELLECT_CAST_BEGIN",

        "executeIntellectMove(stamp)"

    )



    // PhasePart: PRODUCE (frames 0..4 over produceMs)

    _animKeys_setPhasePart(

        heroIndex,

        hero,

        "produce",

        nowMs | 0,

        produceMs | 0,

        nowMs | 0,

        "INTELLECT_CAST_BEGIN",

        "executeIntellectMove(produce)"

    )



    // Lock hero immediately (produce + drive + land are non-movement)

    lockHeroControls(heroIndex)



    // BusyUntil is only for LAND; we’ll set it at detonation time.

    // (Do NOT set busyUntil to expiresAt — you want spell existence to control “drive”.)

}







const INT_PULSE_DEFAULT_PERIOD_MS = 250;  // tweak (or write from your "Time" axis)

const INT_PULSE_WINDOW_MS = 70;           // short window so multiple enemies can be hit in same pulse



// Safe even if INT_PULSE_DEFAULT_PERIOD_MS was never declared anywhere.

const pulsePeriodMs =

  (typeof INT_PULSE_DEFAULT_PERIOD_MS === "number"

    ? INT_PULSE_DEFAULT_PERIOD_MS

    : 250) | 0;







// Intellect spell image (Phaser-host runtime has no MakeCode `assets.*` macro)

// Intellect spell image (Phaser-host runtime: Image has no fillCircle/drawCircle)

let _INT_SPELL_IMG: Image | null = null



function _img_fillCircleCompat(img: Image, cx: number, cy: number, r: number, col: number): void {

    const rr = (r * r) | 0

    for (let dy = -r; dy <= r; dy++) {

        const y = (cy + dy) | 0

        const inside = (rr - dy * dy) | 0

        if (inside < 0) continue

        const dx = (Math.sqrt(inside) | 0) | 0

        img.drawLine((cx - dx) | 0, y, (cx + dx) | 0, y, col)

    }

}



function beginIntellectTargeting(heroIndex: number): void {

    const nowMs = game.runtime() | 0

    const hero = heroes[heroIndex]

    if (!hero) return



    const expiresAtMs = sprites.readDataNumber(hero, INT_SPELL_EXPIRES_AT_MS_KEY) | 0

    if (expiresAtMs <= nowMs) {

        finishIntellectSpellForHero(heroIndex)

        return

    }



    // Destroy any previous controlled spell

    const prev = heroControlledSpells[heroIndex]

    if (prev && !(prev.flags & sprites.Flag.Destroyed)) {

        prev.destroy()

    }

    heroControlledSpells[heroIndex] = null



    const castRadius = sprites.readDataNumber(hero, INT_CAST_RADIUS_KEY) | 0

    const radiusPx = (castRadius > 0 ? castRadius : 16) | 0



    // Spawn as HeroWeapon so overlap(HeroWeapon, Enemy) can apply

    const spell = sprites.create(_getIntSpellImg(false, radiusPx), SpriteKind.HeroWeapon)



    // ? CRITICAL: Ghost disables overlaps in arcadeCompat

    spell.setFlag(SpriteFlag.Ghost, false)



    // TRACE: prove kind + flags at runtime

    {

        const SK: any = SpriteKind as any

        const sid = (spell as any).id

        const sk = (spell as any).kind

        const flags = (spell as any).flags | 0

        console.log(

            "[INT][SPAWN-KIND]",

            "heroIndex", heroIndex,

            "| spell.id", sid,

            "| spell.kind", sk,

            "| SK.HeroWeapon", SK.HeroWeapon,

            "| flags", flags,

            "| ghost?", ((flags & (sprites.Flag.Ghost | 0)) ? 1 : 0)

        )

    }



    spell.x = hero.x

    spell.y = hero.y - 12



    const family = sprites.readDataNumber(hero, INT_CAST_FAMILY_KEY) | 0

    const button = sprites.readDataString(hero, INT_CAST_BUTTON_KEY)



    sprites.setDataNumber(spell, PROJ_DATA.HERO_INDEX, heroIndex)

    sprites.setDataNumber(spell, PROJ_DATA.FAMILY, family)

    sprites.setDataString(spell, PROJ_DATA.BUTTON, button)

    sprites.setDataNumber(spell, INT_SPELL_EXPIRES_AT_MS_KEY, expiresAtMs)

    sprites.setDataNumber(spell, INT_DETONATED_KEY, 0)



    sprites.setDataNumber(spell, INT_DETONATED_KEY, 0)



    // Pulse period is read by overlap() AFTER detonation. Set it on the spell now.

    const pulseMsFromHero = sprites.readDataNumber(hero, INT_PULSE_PERIOD_MS_KEY) | 0

    sprites.setDataNumber(

        spell,

        INT_PULSE_PERIOD_MS_KEY,

        (pulseMsFromHero > 0 ? pulseMsFromHero : INT_PULSE_DEFAULT_PERIOD_MS) | 0

    )



    // Phaser-side visual override (optional but recommended)

    sprites.setDataString(spell, PROJ_PHASER_VISUAL_MODEL_KEY, "crystal")





    // IMPORTANT: the control loop checks this one

    sprites.setDataNumber(spell, PROJ_DATA.TERMINUS_HIT, 0)



    sprites.setDataNumber(spell, INT_SPELL_CREATED_AT_MS_KEY, nowMs)

    sprites.setDataNumber(spell, INT_SPELL_SPAWNED_AT_MS_KEY, nowMs)



    // Publish cached combat stats onto the spell

    const castDmg = sprites.readDataNumber(hero, INT_CAST_DMG_KEY) | 0

    const castMult = sprites.readDataNumber(hero, INT_CAST_DMG_MULT_KEY) | 0

    const castWeakenPct = sprites.readDataNumber(hero, INT_CAST_WEAK_PCT_KEY) | 0

    const castWeakenDur = sprites.readDataNumber(hero, INT_CAST_WEAK_DUR_KEY) | 0

    const castSpeed = sprites.readDataNumber(hero, INT_CAST_SPEED_KEY) | 0

    const castSpeedMax = sprites.readDataNumber(hero, INT_CAST_SPEED_MAX_KEY) | 0

    const castAccel = sprites.readDataNumber(hero, INT_CAST_ACCEL_KEY) | 0

    const castPulseCount = sprites.readDataNumber(hero, INT_CAST_PULSE_COUNT_KEY) | 0

    const castPulseDmg = sprites.readDataNumber(hero, INT_CAST_PULSE_DMG_KEY) | 0



    const baseDmg = getBasePower((family | 0) || FAMILY.INTELLECT) | 0

    const dmg = (castDmg > 0 ? castDmg : Math.max(1, baseDmg) | 0) | 0



    let pulseCount = (castPulseCount > 0 ? castPulseCount : BALANCE.MOVES.INTELLECT.PULSE_COUNT) | 0

    if (pulseCount < 1) pulseCount = 1

    let pulseDmg = (castPulseDmg > 0 ? castPulseDmg : dmg) | 0

    if (pulseDmg < 1) pulseDmg = 1



    sprites.setDataNumber(spell, PROJ_DATA.DAMAGE, pulseDmg)

    sprites.setDataNumber(spell, INT_RADIUS_KEY, radiusPx)

    sprites.setDataNumber(spell, INT_PULSE_TOTAL_KEY, pulseCount | 0)

    sprites.setDataNumber(spell, INT_PULSE_LEFT_KEY, pulseCount | 0)

    sprites.setDataNumber(spell, INT_PULSE_NEXT_AT_MS_KEY, 0)

    sprites.setDataNumber(spell, INT_PULSE_WINDOW_END_MS_KEY, 0)

    sprites.setDataNumber(spell, INT_PULSE_HIT_MASK_KEY, 0)

    if (castMult > 0) sprites.setDataNumber(spell, INT_DAMAGE_MULT_KEY, castMult)

    sprites.setDataNumber(spell, PROJ_DATA.WEAKEN_PCT, castWeakenPct | 0)

    sprites.setDataNumber(spell, PROJ_DATA.WEAKEN_DURATION_MS, castWeakenDur | 0)



    if (castSpeed > 0) sprites.setDataNumber(spell, INT_SPELL_SPEED_KEY, castSpeed | 0)

    if (castSpeedMax > 0) sprites.setDataNumber(spell, INT_SPELL_SPEED_MAX_KEY, castSpeedMax | 0)

    if (castAccel > 0) sprites.setDataNumber(spell, INT_SPELL_ACCEL_KEY, castAccel | 0)

    sprites.setDataNumber(spell, INT_SPELL_LAST_MS_KEY, nowMs | 0)



    sprites.setDataSprite(hero, INT_SPELL_SPRITE_KEY, spell)

    heroControlledSpells[heroIndex] = spell



    // (Recommended) Track it so processIntellectLingers() can animate detonations

    heroProjectiles.push(spell)



    spell.vx = 0

    spell.vy = 0

}





function runIntellectDetonation(spell: Sprite, lingerMs: number) {

    if (!spell || (spell.flags & sprites.Flag.Destroyed)) return



    const now = game.runtime() | 0



    // How long the tendril animation should last (ms)

    const pulseTotal = sprites.readDataNumber(spell, INT_PULSE_TOTAL_KEY) | 0

    let pulsePeriod = sprites.readDataNumber(spell, INT_PULSE_PERIOD_MS_KEY) | 0

    if (pulsePeriod <= 0) pulsePeriod = INT_PULSE_DEFAULT_PERIOD_MS

    const pulseLinger = (pulseTotal > 0 ? (pulseTotal * pulsePeriod + INT_PULSE_WINDOW_MS) : 0) | 0

    const baseLinger = lingerMs | 0

    const totalLinger = Math.max(200, baseLinger, pulseLinger) | 0



    // Pull max radius from traits; fall back to something sane

    let maxRadius = sprites.readDataNumber(spell, INT_RADIUS_KEY) | 0

    if (maxRadius <= 0) maxRadius = 16



    // Make the sprite's image large enough to contain the full explosion

    const size = (maxRadius * 2 + 2) | 0

    const img = image.create(size, size)

    img.fill(0)



    // Optional: make detonation *unmistakably visible* even if tendrils never render in Phaser.

    if (DEBUG_INT_DET_FORCE_VISIBLE_IMAGE) {

        img.drawRect(0, 0, size, size, 2)

        img.drawLine(0, size >> 1, size - 1, size >> 1, 2)

        img.drawLine(size >> 1, 0, size >> 1, size - 1, 2)

    }



    spell.setImage(img)



    // Center it visually at the same world location

    spell.z += 1

//    spell.x -= img.width >> 1

//    spell.y -= img.height >> 1



    // Store timing for per-frame animation

    const endAt = (now + totalLinger) | 0

    sprites.setDataNumber(spell, INT_DETONATE_START_KEY, now)

    sprites.setDataNumber(spell, INT_DETONATE_END_KEY, endAt)



    // Schedule cleanup: contract + actual kill

    const destroyAt = (endAt + 100) | 0

    sprites.setDataNumber(spell, PROJ_DATA.DESTROY_AT, destroyAt)



    // **CRITICAL FIX**: guarantee actual destruction even if AutoDestroy/DestroyOnWall were disabled earlier.

    // lifespan is "ms from now" and does not rely on any other cleanup loop.

    spell.lifespan = (totalLinger + 150) | 0



    // After detonation, allow normal policies again (harmless even if not used)

    spell.setFlag(SpriteFlag.AutoDestroy, true)



    if (DEBUG_INT_DET) {

        const heroIndex = sprites.readDataNumber(spell, PROJ_DATA.HERO_INDEX) | 0

        console.log(

            `[INT][DET] hero=${heroIndex} now=${now} linger=${totalLinger} ` +

            `endAt=${endAt} destroyAt=${destroyAt} lifespan=${spell.lifespan | 0} img=${img.width}x${img.height}`

        )

    }

}





function finishIntellectSpellForHero(heroIndex: number): void {

    if (heroIndex < 0 || heroIndex >= heroes.length) return

    const hero = heroes[heroIndex]

    if (!hero) return



    const nowMs = game.runtime() | 0



    // ---- LOG (before) ----

    if (DEBUG_ANIM_KEYS_INT_FINISH) {

        const ctrl0 = sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL) ? 1 : 0

        const busy0 = sprites.readDataNumber(hero, HERO_DATA.BUSY_UNTIL) | 0

        const ph0 = sprites.readDataString(hero, HERO_DATA.PhaseName) || ""

        const part0 = sprites.readDataString(hero, HERO_DATA.PhasePartName) || ""

        const fco0 = sprites.readDataNumber(hero, HERO_DATA.FRAME_COL_OVERRIDE) | 0

        const hasSpell = heroControlledSpells[heroIndex] ? 1 : 0

        _dbgAnimKeys(heroIndex, hero, "INT_FINISH_BEGIN",

            `t=${nowMs} ctrl=${ctrl0} hasSpell=${hasSpell} busyUntil=${busy0} ph=${ph0} part=${part0} fco=${fco0}`

        )

    }



    // Clear cast metadata (prevents stale-land / stale-produce edge cases)

    sprites.setDataNumber(hero, INT_CAST_LAND_END_MS_KEY, 0)

    sprites.setDataNumber(hero, INT_CAST_SPAWN_AT_MS_KEY, 0)

    sprites.setDataNumber(hero, INT_SPELL_EXPIRES_AT_MS_KEY, 0)

    sprites.setDataNumber(hero, INT_CAST_FAMILY_KEY, 0)

    sprites.setDataString(hero, INT_CAST_BUTTON_KEY, "")



    // Release control state (engine-owned)

    sprites.setDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL, false)



    // IMPORTANT: do NOT destroy the spell here.

    if (heroControlledSpells[heroIndex]) heroControlledSpells[heroIndex] = null



    // Clear movement intent + busy lock

    sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

    sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

    hero.vx = 0

    hero.vy = 0

    clearHeroBusyUntil(heroIndex)



    _dbgContract_noteWhy(heroIndex, "INTELLECT_CAST_FINISH", "finishIntellectSpellForHero")



    // Clear any action leftovers that can strand the hero in "aura-only" mode

    _animEvent_clear(

        heroIndex,

        hero,

        "INTELLECT_CAST_FINISH",

        "finishIntellectSpellForHero(clearEvent)"

    )



    _animKeys_clearPhasePart(

        heroIndex,

        hero,

        nowMs | 0,

        "INTELLECT_CAST_FINISH",

        "finishIntellectSpellForHero(clearPart)"

    )



    sprites.setDataNumber(hero, HERO_DATA.RenderStyleMask, 0)

    sprites.setDataNumber(hero, HERO_DATA.RenderStyleP0, 0)

    sprites.setDataNumber(hero, HERO_DATA.RenderStyleP1, 0)



    unlockHeroControls(heroIndex)



    // Return to ambient phase ownership (movement resolver will keep it healthy)

    setHeroPhaseString(heroIndex, "idle")



    // Reset FAMILY back to movement/base so idle/run/walk resolve correctly

    sprites.setDataNumber(hero, HERO_DATA.FAMILY, 0)



    // ---- LOG (after) ----

    if (DEBUG_ANIM_KEYS_INT_FINISH) {

        const ctrl1 = sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL) ? 1 : 0

        const busy1 = sprites.readDataNumber(hero, HERO_DATA.BUSY_UNTIL) | 0

        const ph1 = sprites.readDataString(hero, HERO_DATA.PhaseName) || ""

        const part1 = sprites.readDataString(hero, HERO_DATA.PhasePartName) || ""

        const fco1 = sprites.readDataNumber(hero, HERO_DATA.FRAME_COL_OVERRIDE) | 0

        _dbgAnimKeys(heroIndex, hero, "INT_FINISH_END",

            `t=${nowMs} ctrl=${ctrl1} busyUntil=${busy1} ph=${ph1} part=${part1} fco=${fco1}`

        )

    }

}





// --- DEBUG KEYS (standalone constants; keep outside the function) ---

const INT_DRIVE_LAST_LOG_MS_KEY = "__intDriveLastLogMs"

const INT_DRIVE_LAST_AIM_X_KEY = "__intDriveLastAimX"

const INT_DRIVE_LAST_AIM_Y_KEY = "__intDriveLastAimY"

const INT_DRIVE_LAST_TERM_HIT_KEY = "__intDriveLastTermHit"



function updateIntellectSpellsControl(): void {

    const nowMs = game.runtime() | 0



    for (let i = 0; i < heroes.length; i++) {

        const hero = heroes[i]

        if (!hero) continue



        if (!sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)) continue



        // If we don't have a spell yet, we may simply be in PRODUCE waiting for spawnAt.

        let spell2 = sprites.readDataSprite(hero, INT_SPELL_SPRITE_KEY)



        if (!spell2 || (spell2.flags & sprites.Flag.Destroyed)) {

            const spawnAt = sprites.readDataNumber(hero, INT_CAST_SPAWN_AT_MS_KEY) | 0

            const expiresAt = sprites.readDataNumber(hero, INT_SPELL_EXPIRES_AT_MS_KEY) | 0



            // If the cast already expired, end cleanly.

            if (expiresAt > 0 && expiresAt <= nowMs) {

                finishIntellectSpellForHero(i, hero, nowMs, "INT_FINISH_EXPIRED_BEFORE_SPAWN")

                continue

            }



            // Still in PRODUCE: wait for spawn moment (DO NOT finish).

            if (spawnAt > 0 && nowMs < spawnAt) {

                continue

            }



            // Time to spawn (or spawnAt missing): try to create the controlled spell now.

            if (spawnAt > 0 && nowMs >= spawnAt) {

                console.log(`[INT][SPAWN] hi=${i} now=${nowMs} spawnAt=${spawnAt}`)

                beginIntellectTargeting(i)



                // Consume spawnAt so we don't repeatedly attempt spawn if something goes wrong.

                sprites.setDataNumber(hero, INT_CAST_SPAWN_AT_MS_KEY, 0)



                spell2 = sprites.readDataSprite(hero, INT_SPELL_SPRITE_KEY)

            }



            // If we still don't have a spell, then it's a real failure.

            if (!spell2 || (spell2.flags & sprites.Flag.Destroyed)) {

                finishIntellectSpellForHero(i, hero, nowMs, "INT_FINISH_MISSING_SPELL")

                continue

            }

        }



        // Ensure DRIVE phase-part persists as long as spell exists (and not detonated)

        if (!sprites.readDataNumber(spell2, INT_DETONATED_KEY)) {

            const exp = sprites.readDataNumber(spell2, INT_SPELL_EXPIRES_AT_MS_KEY) | 0

            if (exp > 0) {

                const remaining = Math.max(1, (exp - nowMs) | 0) | 0

                _animKeys_setPhasePart(

                    i,

                    hero,

                    "drive",

                    nowMs,

                    remaining,

                    nowMs,

                    "INTELLECT_CAST_DRIVE",

                    "updateIntellectSpellsControl(drive)"

                )



                // Auto-detonate when spell lifetime ends

                if (nowMs >= exp) {

                    console.log("Killing spell with detonate because nowMs is greater than exp")

                    detonateIntellectSpellForHero(

                        i,

                        spell2,

                        nowMs,

                        "INTELLECT_DETONATE_REQUEST_EXPIRE",

                        "updateIntellectSpellsControl(expire)"

                    )

                    continue

                }

            }

        }



        // If the spell has a terminus hit, detonate (enemy/wall semantics come from TERMINUS_HIT)

        const termHit = sprites.readDataNumber(spell2, PROJ_DATA.TERMINUS_HIT) | 0

        if (termHit) {

            console.log(`We found a terminus hit on the spell, so we are detonating. termHit=${termHit}`)



            let why = "INTELLECT_DETONATE_REQUEST_UNKNOWN"

            if (termHit == 1) why = "INTELLECT_DETONATE_REQUEST_HIT_WALL"

            else if (termHit == 2) why = "INTELLECT_DETONATE_REQUEST_HIT_ENEMY"



            detonateIntellectSpellForHero(

                i,

                spell2,

                nowMs,

                why,

                `updateIntellectSpellsControl(terminusHit=${termHit})`

            )

            continue

        }



        // Steering: apply limited acceleration so turning has inertia.

        const ownerId = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

        const ctrl = getControllerForOwnerId(ownerId)



        let rawX = 0

        let rawY = 0

        if (ctrl) {

            if (ctrl.left.isPressed()) rawX -= 1

            if (ctrl.right.isPressed()) rawX += 1

            if (ctrl.up.isPressed()) rawY -= 1

            if (ctrl.down.isPressed()) rawY += 1

        }



        const hasInput = (rawX !== 0 || rawY !== 0)



        let aimX = 0

        let aimY = 0

        if (hasInput) {

            let mag = Math.sqrt(rawX * rawX + rawY * rawY)

            if (mag === 0) mag = 1

            aimX = rawX / mag

            aimY = rawY / mag

        } else {

            const curVx = spell2.vx || 0

            const curVy = spell2.vy || 0

            const curMag = Math.sqrt(curVx * curVx + curVy * curVy)

            if (curMag > 0.001) {

                aimX = curVx / curMag

                aimY = curVy / curMag

            } else {

                continue

            }

        }



        // DEBUG (throttled + change-aware, per-hero keys)

        const lastLogMs = sprites.readDataNumber(hero, INT_DRIVE_LAST_LOG_MS_KEY) | 0

        const lastAx = sprites.readDataNumber(hero, INT_DRIVE_LAST_AIM_X_KEY) | 0

        const lastAy = sprites.readDataNumber(hero, INT_DRIVE_LAST_AIM_Y_KEY) | 0

        const lastTerm = sprites.readDataNumber(hero, INT_DRIVE_LAST_TERM_HIT_KEY) | 0



        const aimChanged = (rawX !== lastAx) || (rawY !== lastAy)

        const termChanged = (termHit !== lastTerm)

        const timeOk = (nowMs - lastLogMs) >= 250



        if (aimChanged || termChanged || timeOk) {

            sprites.setDataNumber(hero, INT_DRIVE_LAST_LOG_MS_KEY, nowMs)

            sprites.setDataNumber(hero, INT_DRIVE_LAST_AIM_X_KEY, rawX)

            sprites.setDataNumber(hero, INT_DRIVE_LAST_AIM_Y_KEY, rawY)

            sprites.setDataNumber(hero, INT_DRIVE_LAST_TERM_HIT_KEY, termHit)



            console.log("[INT][DRIVE]",

                "| hero", i,

                "| input", rawX, rawY,

                "| aim", r2(aimX), r2(aimY),

                "| spellXY", (spell2.x | 0), (spell2.y | 0),

                "| spellV", (spell2.vx | 0), (spell2.vy | 0),

                "| termHit", termHit,

                "| life", (spell2.lifespan | 0),

                "| now", nowMs

            )

        }



        let lastMs = sprites.readDataNumber(spell2, INT_SPELL_LAST_MS_KEY) | 0

        if (lastMs <= 0) lastMs = nowMs | 0

        let dt = (nowMs - lastMs) / 1000

        if (dt < 0.001) dt = 0.001

        if (dt > 0.05) dt = 0.05

        sprites.setDataNumber(spell2, INT_SPELL_LAST_MS_KEY, nowMs | 0)



        let baseSpeed = sprites.readDataNumber(spell2, INT_SPELL_SPEED_KEY) | 0

        if (baseSpeed <= 0) baseSpeed = BALANCE.MOVES.INTELLECT.SPEED_BASE

        if (baseSpeed < 1) baseSpeed = 1



        let maxSpeed = sprites.readDataNumber(spell2, INT_SPELL_SPEED_MAX_KEY) | 0

        if (maxSpeed <= 0) maxSpeed = baseSpeed + BALANCE.MOVES.INTELLECT.SPEED_MAX_BONUS

        if (maxSpeed < baseSpeed) maxSpeed = baseSpeed



        let accel = sprites.readDataNumber(spell2, INT_SPELL_ACCEL_KEY) | 0

        if (accel <= 0) accel = BALANCE.MOVES.INTELLECT.STEER_ACCEL_BASE



        const curVx2 = spell2.vx || 0

        const curVy2 = spell2.vy || 0

        const curSpeed = Math.sqrt(curVx2 * curVx2 + curVy2 * curVy2)

        const accelBoost = Math.idiv(Math.round(curSpeed * BALANCE.MOVES.INTELLECT.STEER_ACCEL_PER_SPEED_X1000), 1000)

        accel = accel + accelBoost

        if (accel < BALANCE.MOVES.INTELLECT.STEER_ACCEL_MIN) accel = BALANCE.MOVES.INTELLECT.STEER_ACCEL_MIN



        let targetSpeed = baseSpeed

        if (hasInput) {

            if (curSpeed <= 0.1) {

                targetSpeed = maxSpeed

            } else {

                const dot = (aimX * curVx2 + aimY * curVy2) / curSpeed

                const minDot = BALANCE.MOVES.INTELLECT.SPEED_ALIGN_DOT_MIN_X1000 / 1000

                if (dot >= minDot) targetSpeed = maxSpeed

            }

        }



        const targetVx = aimX * targetSpeed

        const targetVy = aimY * targetSpeed



        let dvx = targetVx - curVx2

        let dvy = targetVy - curVy2

        const dvMag = Math.sqrt(dvx * dvx + dvy * dvy)

        const maxDv = accel * dt

        if (dvMag > maxDv && dvMag > 0) {

            const s = maxDv / dvMag

            dvx *= s

            dvy *= s

        }



        spell2.vx = curVx2 + dvx

        spell2.vy = curVy2 + dvy

    }

}





function detonateIntellectSpellForHero(

    heroIndex: number,

    spell: Sprite,

    nowMs: number,

    whyIdArg?: string,

    whoFromArg?: string

): void {

    console.log("We are detonating the spell and doing the contract writes and land signaling in detonateIntellectSpellForHero")



    // Be defensive: heroIndex can be read off sprites in overlap callbacks.

    if (heroIndex < 0 || heroIndex >= heroes.length) return



    const hero = heroes[heroIndex]

    if (!hero) return



    const spell2 = spell

    if (!spell2 || (spell2.flags & sprites.Flag.Destroyed)) {

        finishIntellectSpellForHero(heroIndex, hero, nowMs, "INT_FINISH_MISSING_SPELL")

        return

    }



    const now = nowMs | 0



    // ---- normalize optional args (also tolerate accidental swap) ----

    let whyOverride = (whyIdArg || "") as string

    let whoFrom = (whoFromArg || "") as string



    // If caller swapped them, fix it (whyIds are the ones that exist in CONTRACT_WHY_TABLE).

    const whyOverrideKnown = !!(whyOverride && (CONTRACT_WHY_TABLE as any)[whyOverride])

    const whoLooksLikeWhy = !!(whoFrom && (CONTRACT_WHY_TABLE as any)[whoFrom])

    if (whyOverride && whoFrom && !whyOverrideKnown && whoLooksLikeWhy) {

        const tmp = whyOverride

        whyOverride = whoFrom

        whoFrom = tmp

    }



    const termHit = sprites.readDataNumber(spell2, PROJ_DATA.TERMINUS_HIT) | 0

    const exp = sprites.readDataNumber(spell2, INT_SPELL_EXPIRES_AT_MS_KEY) | 0



    // Default why derived from state unless caller provided a valid override.

    let whyId = ""

    if (whyOverride && (CONTRACT_WHY_TABLE as any)[whyOverride]) {

        whyId = whyOverride

    } else {

        if (termHit == 1) whyId = "INTELLECT_DETONATE_REQUEST_HIT_WALL"

        else if (termHit == 2) whyId = "INTELLECT_DETONATE_REQUEST_HIT_ENEMY"

        else if (exp > 0 && now >= exp) whyId = "INTELLECT_DETONATE_REQUEST_EXPIRE"

        else whyId = "INTELLECT_DETONATE_REQUEST_UNKNOWN"

    }



    // Encode the triggering site into WHO (while keeping the writer identifiable).

    const who =

        whoFrom && whoFrom.length

            ? `detonateIntellectSpellForHero<${whoFrom}>`

            : "detonateIntellectSpellForHero"



    // WHY always (even if the spell was already in LAND etc)

    _dbgContract_noteWhy(heroIndex, whyId, who)



    // If we are still controlling the spell, drop control immediately (and unfreeze movement).

    if (sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)) {

        _dbgContract_trackTouch(heroIndex, whyId, who, HERO_DATA.IS_CONTROLLING_SPELL)

        sprites.setDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL, false)



        _dbgContract_trackTouch(heroIndex, whyId, who, HERO_DATA.FROZEN_FRAMES)

        sprites.setDataNumber(hero, HERO_DATA.FROZEN_FRAMES, 0)



        // If we were storing velocity, clear it (so the hero resumes cleanly).

        _dbgContract_trackTouch(heroIndex, whyId, who, HERO_DATA.STORED_VX)

        _dbgContract_trackTouch(heroIndex, whyId, who, HERO_DATA.STORED_VY)

        sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

        sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

    }



    // Pick the correct busy key (you've had both names in play)

    const busyKey: any =

        (HERO_DATA as any).BUSY_UNTIL_MS != null ? (HERO_DATA as any).BUSY_UNTIL_MS

        : (HERO_DATA as any).BUSY_UNTIL



    // Always ensure we enter LAND window (unless we are already in LAND).

    // ? FIX: ANIMKEYS was undefined; use the real stored key instead.

    const partNameNow = sprites.readDataString(hero, HERO_DATA.PhasePartName) || ""

    if (partNameNow != "land") {

        const landDur = INT_LAND_DUR_MS | 0

        _animKeys_setPhasePart(heroIndex, hero, "land", now, landDur, now, whyId, who)

        sprites.setDataNumber(hero, INT_CAST_LAND_END_MS_KEY, (now + landDur) | 0)



        // Also treat LAND as busy (keeps movement-phase writers from fighting it).

        if (busyKey != null) {

            _dbgContract_trackTouch(heroIndex, whyId, who, busyKey)

            sprites.setDataNumber(hero, busyKey, (now + landDur) | 0)

        }

    }



    // Idempotent: if detonation already happened, stop here (LAND window above is still valid).

    if ((sprites.readDataNumber(spell2, INT_DETONATED_KEY) | 0) != 0) return



    const family = sprites.readDataNumber(spell2, PROJ_DATA.FAMILY) | 0

    const detonateX = spell2.x | 0

    const detonateY = spell2.y | 0

    const dmgNow = sprites.readDataNumber(spell2, PROJ_DATA.DAMAGE) | 0



    console.log(`[INT DEBUG] DETONATE intellect hero=${heroIndex} family=${family} at=(${detonateX},${detonateY}) dmg=${dmgNow} why=${whyId} who=${who}`)



    console.log("We are running detonateIntellectSpellAt within detonateIntellectSpellForHero")

    detonateIntellectSpellAt(spell2, detonateX, detonateY)

    console.log("We cleaned up the detonation here in detonateIntellectSpellForHero")

}





function detonateIntellectSpellAt(spell: Sprite, termX: number, termY: number) {



    console.log("We are detonating the spell AT and doing the contract writes and land signaling in detonateIntellectSpellAt")



    if (!spell) return

    if (sprites.readDataNumber(spell, INT_DETONATED_KEY)) return



    const heroIndex = sprites.readDataNumber(spell, PROJ_DATA.HERO_INDEX) | 0



    // (Optional debug – keep or delete as you like)

    const family = sprites.readDataNumber(spell, PROJ_DATA.FAMILY) | 0

    const dmg = sprites.readDataNumber(spell, PROJ_DATA.DAMAGE) | 0

    console.log(

        `[INT DEBUG] DETONATE intellect hero=${heroIndex} family=${family} ` +

        `at=(${termX},${termY}) dmg=${dmg}`

    )



    // Mark detonated & pin position

    sprites.setDataNumber(spell, INT_DETONATED_KEY, 1)

    sprites.setDataNumber(spell, INT_TERM_X_KEY, termX)

    sprites.setDataNumber(spell, INT_TERM_Y_KEY, termY)

    spell.vx = 0

    spell.vy = 0

    spell.x = termX

    spell.y = termY



    const weakenMs = sprites.readDataNumber(spell, PROJ_DATA.WEAKEN_DURATION_MS) | 0

    const pulseTotal = sprites.readDataNumber(spell, INT_PULSE_TOTAL_KEY) | 0

    if (pulseTotal > 0) {

        sprites.setDataNumber(spell, INT_PULSE_LEFT_KEY, pulseTotal | 0)

    }

    sprites.setDataNumber(spell, INT_PULSE_NEXT_AT_MS_KEY, 0)

    sprites.setDataNumber(spell, INT_PULSE_WINDOW_END_MS_KEY, 0)

    sprites.setDataNumber(spell, INT_PULSE_HIT_MASK_KEY, 0)



    // Visual + cleanup (spell will be destroyed later)

    runIntellectDetonation(spell, Math.max(400, weakenMs))

    console.log("We cleaned up the detonation here in detonateIntellectSpellAt")

}







function processIntellectLingers() {

    const now = game.runtime() | 0



    const totalTendrils = 18        // 9 long + 9 short

    const longCount = 9

    const shortCount = totalTendrils - longCount



    const rotationSpeed = 0.008     // radians per ms (spin speed)

    const growthFrac = 0.4          // portion of time spent "growing" before spin



    const jagSegments = 5           // number of steps along each tendril

    const jagAmplitude = 0.5        // BIGGER wiggle (˜ "15" feel instead of "5")



    function _killSprite(s: Sprite, reason: string): void {

        if (!s || (s.flags & sprites.Flag.Destroyed)) return



        // Prevent repeated attempts even if destroy fails for some reason.

        sprites.setDataNumber(s, PROJ_DATA.DESTROY_AT, 0)



        if (DEBUG_INT_DET) {

            const hi = sprites.readDataNumber(s, PROJ_DATA.HERO_INDEX) | 0

            console.log(`[INT][CLEANUP] hero=${hi} now=${now} reason=${reason} -> destroy()`)

        }



        // In your runtime, sprites.destroy(...) is not available.

        // Sprite instance destroy() *should* be.

        const anyS = s as any

        if (anyS && typeof anyS.destroy === "function") {

            anyS.destroy()

        }

    }



    for (let i = 0; i < heroProjectiles.length; i++) {

        const proj = heroProjectiles[i]

        if (!proj || (proj.flags & sprites.Flag.Destroyed)) continue



        if (!sprites.readDataNumber(proj, INT_DETONATED_KEY)) continue



        let pulseLeft = sprites.readDataNumber(proj, INT_PULSE_LEFT_KEY) | 0

        const pulseTotal = sprites.readDataNumber(proj, INT_PULSE_TOTAL_KEY) | 0

        if (pulseLeft <= 0 && pulseTotal > 0) {

            pulseLeft = pulseTotal | 0

            sprites.setDataNumber(proj, INT_PULSE_LEFT_KEY, pulseLeft | 0)

        }

        let pulsePeriod = sprites.readDataNumber(proj, INT_PULSE_PERIOD_MS_KEY) | 0

        if (pulsePeriod <= 0) pulsePeriod = INT_PULSE_DEFAULT_PERIOD_MS

        let nextAt = sprites.readDataNumber(proj, INT_PULSE_NEXT_AT_MS_KEY) | 0

        if (pulseLeft > 0) {

            if (nextAt <= 0) nextAt = now

            if (now >= nextAt) {

                nextAt = (now + pulsePeriod) | 0

                sprites.setDataNumber(proj, INT_PULSE_NEXT_AT_MS_KEY, nextAt)

                sprites.setDataNumber(proj, INT_PULSE_WINDOW_END_MS_KEY, (now + INT_PULSE_WINDOW_MS) | 0)

                sprites.setDataNumber(proj, INT_PULSE_HIT_MASK_KEY, 0)

                pulseLeft = (pulseLeft - 1) | 0

                sprites.setDataNumber(proj, INT_PULSE_LEFT_KEY, pulseLeft | 0)

            }

        }



        // --- destroyAt safety: if something else didn’t kill it, we do. ---

        const destroyAt = sprites.readDataNumber(proj, PROJ_DATA.DESTROY_AT) | 0

        if (destroyAt > 0 && now >= destroyAt) {

            _killSprite(proj, `destroyAt=${destroyAt}`)

            // Optional: stop tracking immediately in our local list

            heroProjectiles[i] = null

            continue

        }



        const startMs = sprites.readDataNumber(proj, INT_DETONATE_START_KEY) | 0

        const endMs = sprites.readDataNumber(proj, INT_DETONATE_END_KEY) | 0

        if (startMs <= 0 || endMs <= startMs) continue



        const total = Math.max(1, pulsePeriod | 0)

        let pulseStart = startMs

        if (nextAt > 0) pulseStart = (nextAt - total) | 0

        let elapsed = (now - pulseStart) | 0

        if (elapsed < 0) elapsed = 0

        if (elapsed > total) elapsed = total



        // Clamp animation progress [0, 1] within the current pulse

        let t = total > 0 ? (elapsed / total) : 1



        let maxRadius = sprites.readDataNumber(proj, INT_RADIUS_KEY) | 0

        if (maxRadius <= 0) maxRadius = 16



        // Long tendrils go to full radius; short ones to half radius

        const longMax = maxRadius

        const shortMax = Math.max(1, maxRadius >> 1)



        // Out -> spin -> contraction across a single pulse

        let radiusT = 1

        if (growthFrac > 0) {

            if (t < growthFrac) {

                radiusT = 0.2 + 0.8 * (t / growthFrac)

            } else if (t > (1 - growthFrac)) {

                radiusT = 0.2 + 0.8 * ((1 - t) / growthFrac)

            }

        }



        const currentLongRadius = Math.max(

            1,

            Math.floor(longMax * radiusT)

        )

        const currentShortRadius = Math.max(

            1,

            Math.floor(shortMax * radiusT)

        )



        const img = proj.image

        if (!img) continue



        const w = img.width

        const h = img.height

        const cx = w >> 1

        const cy = h >> 1



        // Clear previous frame

        img.fill(0)



        // Cheap outline to read on dark backgrounds.

        const glowOuter = Math.max(1, (currentLongRadius + 1) | 0)

        const glowInner = Math.max(1, (currentLongRadius - 2) | 0)

        _img_fillCircleCompat(img, cx, cy, glowOuter, 1)

        if (glowInner < glowOuter) _img_fillCircleCompat(img, cx, cy, glowInner, 0)



        const colorIndex = 8

        const twoPi = 2 * Math.PI



        // "Grow, then spin": no rotation during the first growthFrac of the pulse

        const growthMs = total * growthFrac

        let spinElapsed = elapsed - growthMs

        if (spinElapsed < 0) spinElapsed = 0



        const baseAngleLong = spinElapsed * rotationSpeed          // clockwise

        const baseAngleShort = -spinElapsed * rotationSpeed        // counterclockwise



        const heroIndex = sprites.readDataNumber(proj, PROJ_DATA.HERO_INDEX) | 0



        for (let k = 0; k < totalTendrils; k++) {

            const isLong = k < longCount

            const setIndex = isLong ? k : (k - longCount)

            const perSetCount = isLong ? longCount : shortCount



            // Angle fraction within its own ring (9 long distributed, 9 short distributed)

            const fraction = perSetCount > 0 ? setIndex / perSetCount : 0



            const maxR = isLong ? currentLongRadius : currentShortRadius

            const baseAngle = isLong ? baseAngleLong : baseAngleShort



            // Alternate jag pattern: +1 vs -1 (up/down vs down/up)

            const patternSign = (k % 2 == 0) ? 1 : -1



            // Slight per-tendril variation

            const perTendrilPhase = (heroIndex * 0.3 + k * 0.5)



            let prevX = cx

            let prevY = cy



            for (let s = 1; s <= jagSegments; s++) {

                const segFrac = s / jagSegments

                const rBase = maxR * segFrac



                // Flip offset direction each segment for up/down/up/down look

                const segDir = (s % 2 == 0) ? 1 : -1



                // Wiggle angle – larger near center, smaller toward tip

                const wiggle = patternSign * segDir * jagAmplitude * (1 - segFrac)



                const angle = baseAngle

                    + fraction * twoPi

                    + wiggle

                    + perTendrilPhase * 0.02



                const ex = cx + Math.round(rBase * Math.cos(angle))

                const ey = cy + Math.round(rBase * Math.sin(angle))



                // Draw thicker tendril: main line + a slight perpendicular offset

                img.drawLine(prevX, prevY, ex, ey, colorIndex)



                const dx = ex - prevX

                const dy = ey - prevY

                const segLenSq = dx * dx + dy * dy

                if (segLenSq > 0) {

                    // Perpendicular unit step (approx) for width

                    let px = -dy

                    let py = dx

                    // Normalize to length 1-ish

                    if (px != 0 || py != 0) {

                        const mag = Math.sqrt(px * px + py * py)

                        px = Math.idiv(px, mag)

                        py = Math.idiv(py, mag)

                        img.drawLine(prevX + px, prevY + py, ex + px, ey + py, colorIndex)

                    }

                }



                prevX = ex

                prevY = ey

            }

        }



        // Tiny core so center isn't empty

        img.setPixel(cx, cy, colorIndex)



        // If you were using the "force upload" trick earlier, keep it:

        // (safe even if Phaser ignores it; it shouldn’t crash)

        if ((proj as any).setImage && typeof (proj as any).setImage === "function") {

            ;(proj as any).setImage(img)

        }

    }

}



// Return control when the projectile ends

sprites.onDestroyed(SpriteKind.HeroWeapon, function (proj) {



    const family = sprites.readDataNumber(proj, PROJ_DATA.FAMILY)

    if (family != FAMILY.INTELLECT && family != FAMILY.HEAL) return



    const heroIndex = sprites.readDataNumber(proj, PROJ_DATA.HERO_INDEX)

    console.log(`[INT DEBUG] onDestroyed heroWeapon hero=${heroIndex} t=${game.runtime()|0} detonated=${sprites.readDataNumber(proj, INT_DETONATED_KEY)|0} destroyAt=${sprites.readDataNumber(proj, PROJ_DATA.DESTROY_AT)|0} lifespan=${proj.lifespan|0}`);



    if (heroIndex < 0 || heroIndex >= heroes.length) return



    if (heroControlledSpells[heroIndex] == proj) {

        heroControlledSpells[heroIndex] = null



        const hero = heroes[heroIndex]

        if (!hero) return



        // If we are in the LAND window, finish will happen when land ends.

        const landEnd = sprites.readDataNumber(hero, INT_CAST_LAND_END_MS_KEY) | 0

        if (landEnd > 0 && (game.runtime() | 0) < landEnd) return



        // Otherwise, recover immediately (safety)

        finishIntellectSpellForHero(heroIndex)

    }

})









