const DEFAULT_MONSTER_FRAME_W = BALANCE.MONSTERS.DEFAULT_FRAME_W

const DEFAULT_MONSTER_FRAME_H = BALANCE.MONSTERS.DEFAULT_FRAME_H



// Default collider rule: for most frames < 96px, treat as 1-tile footprint (32×32).

// For big frames (>=96px), default to 2-tile footprint (64×64).

const MONSTER_COLLIDER_BIG_THRESHOLD_PX = BALANCE.MONSTERS.COLLIDER_BIG_THRESHOLD_PX



interface MonsterSizing {

    frameW: number

    frameH: number

    colliderW: number

    colliderH: number

    renderOffsY: number

}



function _monsterFrameSizeForId(monsterId: string): { w: number, h: number } {

    const md = _monsterDefById(monsterId)

    if (md && (md.frameW || md.frameH)) {

        const w = (md.frameW || DEFAULT_MONSTER_FRAME_W) | 0

        const h = (md.frameH || DEFAULT_MONSTER_FRAME_H) | 0

        return { w, h }

    }



    const atlasSize = getLpcFrameSizeForMonster(monsterId)

    if (atlasSize) return { w: atlasSize.w | 0, h: atlasSize.h | 0 }



    return { w: DEFAULT_MONSTER_FRAME_W, h: DEFAULT_MONSTER_FRAME_H }

}



function _defaultColliderFromFrame(frameW: number, frameH: number): { cw: number, ch: number } {

    const tile = WORLD_TILE_SIZE | 0



    let cw = tile

    let ch = tile



    if ((frameW | 0) <= tile) cw = frameW | 0

    else if ((frameW | 0) >= (MONSTER_COLLIDER_BIG_THRESHOLD_PX | 0)) cw = (tile * 2) | 0



    if ((frameH | 0) <= tile) ch = frameH | 0

    else if ((frameH | 0) >= (MONSTER_COLLIDER_BIG_THRESHOLD_PX | 0)) ch = (tile * 2) | 0



    if (cw < 1) cw = 1

    if (ch < 1) ch = 1

    return { cw, ch }

}



function _monsterSizingForId(monsterId: string): MonsterSizing {

    const md = _monsterDefById(monsterId)

    const fs = _monsterFrameSizeForId(monsterId)

    const frameW = fs.w | 0

    const frameH = fs.h | 0



    const defCol = _defaultColliderFromFrame(frameW, frameH)

    const colliderW = ((md && md.colliderW) ? (md.colliderW | 0) : (defCol.cw | 0)) | 0

    const colliderH = ((md && md.colliderH) ? (md.colliderH | 0) : (defCol.ch | 0)) | 0



    // Phaser sprite should be shifted UP so the "feet" sit on the collider

    // (centered collider vs centered art)

    let renderOffsY = 0

    if ((frameH | 0) > (colliderH | 0)) {

        renderOffsY = Math.idiv((frameH - colliderH) | 0, 2) | 0

    }



    return { frameW, frameH, colliderW, colliderH, renderOffsY }

}





function _monsterDefById(id: string): MonsterDef {

    for (let i = 0; i < MONSTER_CATALOG.length; i++) {

        const d = MONSTER_CATALOG[i]

        if (d.id === id) return d

    }



    // fallback: unknown monsters still spawn but have "danger" = 999 so generator won't pick them

    return {

        id,

        danger: 999,

        hp: 1,

        damage: 1,

        speed: 1,

        xp: 1,

        advanceRangePx: 0

    }

}



function _clamp(n: number, lo: number, hi: number): number {

    if (n < lo) return lo

    if (n > hi) return hi

    return n

}



function _floorDangerBase(floor1: number): number {

    // floor1 = 1..100

    // This is THE pacing knob. Keep it linear-ish for now.

    return BALANCE.WAVES.DANGER_BASE + (floor1 * BALANCE.WAVES.DANGER_PER_FLOOR)

}



function _pickArchetype(floor1: number, waveIndex: number, waveCount: number): WaveArchetype {

    // Early floors: more swarms. Later: more elites/mixed.

    const t = _clamp(floor1 / 100, 0, 1)



    const r = Math.random()

    const swarmW = (BALANCE.WAVES.ARCHETYPE_SWARM_WEIGHT_BASE + BALANCE.WAVES.ARCHETYPE_SWARM_WEIGHT_DELTA * t)

    const elitesW = (BALANCE.WAVES.ARCHETYPE_ELITES_WEIGHT_BASE + BALANCE.WAVES.ARCHETYPE_ELITES_WEIGHT_DELTA * t)

    // remainder = mixed



    if (r < swarmW) return "swarm"

    if (r < (swarmW + elitesW)) return "elites"

    return "mixed"

}



function _buildPoolForTarget(targetAvgDanger: number, maxDangerAllowed: number): { id: string, w: number }[] {

    const out: { id: string, w: number }[] = []

    for (let i = 0; i < MONSTER_CATALOG.length; i++) {

        const m = MONSTER_CATALOG[i]

        if ((m.danger | 0) <= 0) continue

        if (m.danger > maxDangerAllowed) continue



        // Weight by closeness to targetAvgDanger (closer = heavier weight)

        const d = Math.abs(m.danger - targetAvgDanger)

        const w = 1 / (1 + d) // simple, stable

        out.push({ id: m.id, w })

    }

    return out

}



function _sumWeights(pool: { id: string, w: number }[]): number {

    let s = 0

    for (let i = 0; i < pool.length; i++) s += pool[i].w

    return s

}



function _pickFromPool(pool: { id: string, w: number }[]): string {

    if (!pool || pool.length == 0) return MONSTER_CATALOG[0]?.id || "eyeball"

    const total = _sumWeights(pool)

    let r = Math.random() * total

    for (let i = 0; i < pool.length; i++) {

        r -= pool[i].w

        if (r <= 0) return pool[i].id

    }

    return pool[pool.length - 1].id

}



function _buildWavePlanForFloor(floorIndex0: number, spawnIntervalMs: number): GenWaveDef[] {

    const floor1 = Math.max(1, floorIndex0 | 0) | 0

    const slimeOnly = (floor1 | 0) == 1



    const baseDanger = _floorDangerBase(floor1)



    // 3..7 waves up to floor 100

    const waveCount = _clamp(

        BALANCE.WAVES.WAVE_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.WAVE_COUNT_FLOOR_DIV),

        BALANCE.WAVES.WAVE_COUNT_MIN,

        BALANCE.WAVES.WAVE_COUNT_MAX

    )



    // Split danger across waves so later waves are heavier

    const weights: number[] = []

    let wsum = 0

    for (let i = 0; i < waveCount; i++) {

        const w = Math.pow(i + 1, BALANCE.WAVES.WAVE_WEIGHT_EXP)

        weights.push(w)

        wsum += w

    }



    const plan: GenWaveDef[] = []

    for (let i = 0; i < waveCount; i++) {

        const archetype = _pickArchetype(floor1, i, waveCount)

        const waveBudget = (baseDanger * (weights[i] / wsum)) | 0



        // Choose “how many spawns we want” based on archetype

        let desiredCount = BALANCE.WAVES.DESIRED_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.DESIRED_COUNT_FLOOR_DIV)

        if (archetype === "swarm") {

            desiredCount = BALANCE.WAVES.SWARM_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.SWARM_COUNT_FLOOR_DIV)

        } else if (archetype === "elites") {

            desiredCount = BALANCE.WAVES.ELITES_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.ELITES_COUNT_FLOOR_DIV)

        }



        desiredCount = _clamp(desiredCount, BALANCE.WAVES.DESIRED_COUNT_MIN, BALANCE.WAVES.DESIRED_COUNT_MAX)



        // Target average danger determines which monsters are preferred

        const targetAvgDanger = _clamp(

            waveBudget / Math.max(1, desiredCount),

            BALANCE.WAVES.TARGET_AVG_DANGER_MIN,

            BALANCE.WAVES.TARGET_AVG_DANGER_MAX

        )



        // Eligible monsters must have danger <= waveBudget (your exact rule)

        const pool = slimeOnly ? [{ id: "slime", w: 1 }] : _buildPoolForTarget(targetAvgDanger, waveBudget)



        // Spawn chance & duration from desired count

        let spawnChance = BALANCE.WAVES.SPAWN_CHANCE_DEFAULT

        if (archetype === "swarm") spawnChance = BALANCE.WAVES.SPAWN_CHANCE_SWARM

        else if (archetype === "elites") spawnChance = BALANCE.WAVES.SPAWN_CHANCE_ELITES



        const expectedTicks = Math.ceil(desiredCount / Math.max(0.05, spawnChance))

        const durationMs = (expectedTicks * spawnIntervalMs) | 0



        // Breaks: short; you can tune later

        const breakMs = (BALANCE.WAVES.BREAK_BASE_MS + Math.idiv(floor1, BALANCE.WAVES.BREAK_PER_FLOOR_DIV)) | 0



        // Cap alive count so testing doesn’t explode

        const maxAlive = _clamp(

            BALANCE.WAVES.MAX_ALIVE_BASE + Math.idiv(floor1, BALANCE.WAVES.MAX_ALIVE_FLOOR_DIV),

            BALANCE.WAVES.MAX_ALIVE_MIN,

            BALANCE.WAVES.MAX_ALIVE_MAX

        )



        plan.push({

            archetype,

            dangerBudget: waveBudget,

            spawnChance,

            durationMs,

            breakMs,

            maxAlive,

            pool

        })

    }



    return plan

}



function pickEnemyKindForWave(waveIndex: number): string {

    const wi = waveIndex | 0

    if (!_dunWavePlan || _dunWavePlan.length == 0) {

        return MONSTER_CATALOG[0]?.id || "eyeball"

    }

    const w = _dunWavePlan[_clamp(wi, 0, _dunWavePlan.length - 1)]

    return _pickFromPool(w.pool)

}







game.onUpdateInterval(ENEMY_SPAWN_INTERVAL_MS, function () {

    if (!HeroEngine._isStarted()) return

    if (_engineIsPaused()) return

    if (SHOP_MODE_ACTIVE) return

    if (!enemySpawners || enemySpawners.length == 0) return



    // Finite waves run only when a combat floor has started them.

    if (!_dunCombatWavesActive || _dunCombatWavesComplete) return



    const now = game.runtime() | 0



    // No procedural plan? then stop the wave driver (combat clears once enemies are dead)

    if (!_dunWavePlan || _dunWavePlan.length == 0) {

        _dunCombatWavesActive = false

        _dunCombatWavesComplete = true

        return

    }



    // Phase transitions (break <-> wave)

    if ((now | 0) >= (wavePhaseUntilMs | 0)) {

        if (currentWaveIsBreak) {

            // Start / resume a wave

            currentWaveIsBreak = false



            const wi = _clamp(currentWaveIndex | 0, 0, _dunWavePlan.length - 1) | 0

            const w = _dunWavePlan[wi]



            wavePhaseUntilMs = (now + (w.durationMs | 0)) | 0

            showWaveBanner(wi)

        } else {

            // Wave just ended

            if ((currentWaveIndex | 0) >= (_dunWavePlan.length - 1)) {

                currentWaveIsBreak = true

                _dunCombatWavesActive = false

                _dunCombatWavesComplete = true

                wavePhaseUntilMs = (now + 999999999) | 0

                console.log(`[waves] complete; finalWave=${currentWaveIndex} t=${now}`)

                return

            }



            // Schedule next break, then next wave

            currentWaveIsBreak = true

            currentWaveIndex = ((currentWaveIndex | 0) + 1) | 0



            const wi = _clamp(currentWaveIndex | 0, 0, _dunWavePlan.length - 1) | 0

            const w = _dunWavePlan[wi]



            wavePhaseUntilMs = (now + (w.breakMs | 0)) | 0

        }

        return

    }



    if (currentWaveIsBreak) {

        // Rest window: no spawns

        return

    }



    // Active wave

    const wi = _clamp(currentWaveIndex | 0, 0, _dunWavePlan.length - 1) | 0

    const wave = _dunWavePlan[wi]



    // NEW: Cap alive enemies per-wave (prevents runaway spawns while testing)

    const live = _dunCountLiveEnemies() | 0

    const cap = (wave.maxAlive | 0) || 9999

    if ((cap | 0) > 0 && (live | 0) >= (cap | 0)) return



    // Wave-specific spawn chance

    const chance = (wave.spawnChance | 0) === 0 ? 0 : (wave.spawnChance as any as number)

    if (chance < 1 && Math.random() > chance) return



    // Pick a spawner + pick a monster from THIS wave's pool

    const idx = randint(0, enemySpawners.length - 1)

    const s = enemySpawners[idx]



    const kind = _pickFromPool(wave.pool)

    spawnEnemyOfKind(kind, s.x, s.y, /*elite=*/ (wave.archetype === "elites"))

})

















