// ----------------------------------------------------------
const EFFECT_DEBUG_ID_KEY = "effectDebugId"

function _installEffectDebugOnce(): void {
    try {
        const g: any = globalThis as any
        if (!g || g.__heEffectDebug) return

        const sessions: any = {}

        g.__heEffectDebug = {
            enabled: false,
            mark: (id: number, stage: string, payload?: any, finalize?: boolean) => {
                if (!g.__heEffectDebug || !g.__heEffectDebug.enabled) return
                const key = String(id | 0)
                let s = sessions[key]
                if (!s) {
                    s = { id: key, t0: game.runtime() | 0, events: [], stages: {}, spriteIds: {}, logged: false }
                    sessions[key] = s
                }
                const now = game.runtime() | 0
                const stageKey = String(stage || "unknown")
                s.stages[stageKey] = (s.stages[stageKey] | 0) + 1
                if (payload && payload.spriteId != null) {
                    s.spriteIds[String(payload.spriteId | 0)] = true
                }
                if (!s.stages[stageKey] || s.stages[stageKey] === 1) {
                    s.events.push({ t: now, stage: stageKey, payload: payload || {} })
                }
                if (finalize && !s.logged) {
                    s.logged = true
                    const out = {
                        id: s.id,
                        t0: s.t0,
                        tLast: now,
                        stages: s.stages,
                        spriteIds: Object.keys(s.spriteIds),
                        events: s.events
                    }
                    console.log("[EFFECTDBG]", JSON.stringify(out))
                }
            },
            dump: (id?: number) => {
                if (!g.__heEffectDebug || !g.__heEffectDebug.enabled) return
                if (id == null) {
                    for (const k of Object.keys(sessions)) {
                        const s = sessions[k]
                        console.log("[EFFECTDBG]", JSON.stringify(s))
                    }
                    return
                }
                const s = sessions[String(id | 0)]
                if (s) console.log("[EFFECTDBG]", JSON.stringify(s))
            }
        }

        const enableFn = function (v: boolean): void {
            if (!g.__heEffectDebug) return
            g.__heEffectDebug.enabled = !!v
        }
        g.__heEffectDebugEnable = enableFn
        g._heEffectDebugEnable = enableFn
    } catch { }
}

function _effectDebugMark(id: number, stage: string, payload?: any, finalize?: boolean): void {
    try {
        const g: any = globalThis as any
        if (g && g.__heEffectDebug && typeof g.__heEffectDebug.mark === "function") {
            g.__heEffectDebug.mark(id | 0, String(stage || ""), payload || {}, !!finalize)
        }
    } catch { }
}

try { _installEffectDebugOnce() } catch { }



