// -----------------------------------------------------------------

// RELIC RUNTIME STATE (v3.1 PoC)

// These are engine-only, per-player mutable fields that drive both

// gameplay hooks and the UI state sent in snapshots.

// -----------------------------------------------------------------



const RELIC_SHROUD_COOLDOWN_MS = 10_000

const RELIC_ENERGY_SHIELD_MAX = 10
const RELIC_ENERGY_SHIELD_REGEN_MS = 1_000
const RELIC_RING_OF_FIRE_DAMAGE = 10
const RELIC_RING_OF_FIRE_RADIUS = 44
const RELIC_RING_OF_FIRE_FLAME_COUNT = 12
const RELIC_RING_OF_FIRE_LIFESPAN_MS = 1_000
const RELIC_RING_OF_FIRE_SKIN_ID = "firelion"
const RELIC_LOAF_OF_BREAD_HP_BONUS = 10
const RELIC_LOAF_OF_BREAD_SHOP_PRICE = 10
const RELIC_RAINBOW_GLYPH_TEXT = "SAIW"
const RELIC_RAINBOW_FULL_MASK = 0b1111



type RelicRuntimeState = {

    shroudReadyAtMs: number

    lanternCharges: number

    energyShieldValue: number

    energyShieldLastMs: number

    ringOfFireReady: boolean

    rainbowStep: number

    rainbowArmed: boolean

}



const _relicRuntimeByPid: { [pid: string]: RelicRuntimeState } = {

    // Dev default: player 1 has the starter relics

    "1": {

        shroudReadyAtMs: 0,

        lanternCharges: 1,

        energyShieldValue: RELIC_ENERGY_SHIELD_MAX,

        energyShieldLastMs: 0,

        ringOfFireReady: true,

        rainbowStep: 0,

        rainbowArmed: false,

    },

}



function _relicEnsureRuntimeForPid(pid: number): RelicRuntimeState {

    const k = String(pid | 0)

    let st = _relicRuntimeByPid[k]

    if (!st) {

        st = {

            shroudReadyAtMs: 0,

            lanternCharges: 1,

            energyShieldValue: RELIC_ENERGY_SHIELD_MAX,

            energyShieldLastMs: 0,

            ringOfFireReady: true,

            rainbowStep: 0,

            rainbowArmed: false,

        }

        _relicRuntimeByPid[k] = st

    }

    // sanitize

    st.shroudReadyAtMs = st.shroudReadyAtMs | 0

    st.lanternCharges = st.lanternCharges | 0

    st.energyShieldValue = st.energyShieldValue | 0

    st.energyShieldLastMs = st.energyShieldLastMs | 0

    st.ringOfFireReady = !!st.ringOfFireReady

    st.rainbowStep = st.rainbowStep | 0

    st.rainbowArmed = !!st.rainbowArmed

    return st

}



function _relicUpdateEnergyShield(pid: number, nowMs: number): number {

    const st = _relicEnsureRuntimeForPid(pid)

    const now = nowMs | 0



    let value = st.energyShieldValue | 0

    let last = st.energyShieldLastMs | 0



    if (last <= 0) {

        if (value > RELIC_ENERGY_SHIELD_MAX) value = RELIC_ENERGY_SHIELD_MAX

        if (value < 0) value = 0

        st.energyShieldValue = value

        st.energyShieldLastMs = now

        return st.energyShieldValue | 0

    }



    if (value >= RELIC_ENERGY_SHIELD_MAX) {

        st.energyShieldValue = RELIC_ENERGY_SHIELD_MAX

        st.energyShieldLastMs = now

        return RELIC_ENERGY_SHIELD_MAX

    }



    const elapsed = (now - last) | 0

    if (elapsed < RELIC_ENERGY_SHIELD_REGEN_MS) return value



    const gain = Math.idiv(elapsed, RELIC_ENERGY_SHIELD_REGEN_MS) | 0

    if (gain <= 0) return value



    const nextValue = Math.min(RELIC_ENERGY_SHIELD_MAX, (value + gain) | 0) | 0

    st.energyShieldValue = nextValue

    st.energyShieldLastMs = (last + gain * RELIC_ENERGY_SHIELD_REGEN_MS) | 0

    return nextValue

}



const RELIC_EFFECT_RING_RING_ID_KEY = "relicRingFireId"

const RELIC_EFFECT_RING_SRC_HI_KEY = "relicRingFireSrcHi"

const RELIC_EFFECT_RING_DMG_KEY = "relicRingFireDmg"

const RELIC_EFFECT_RING_ENEMY_HIT_KEY = "relicRingFireHit"

let _relicRingFireNextId = 1

let _relicRingFireFlameImg: Image | null = null



function _relicRingOfFireFlameImage(): Image {

    if (_relicRingFireFlameImg) return _relicRingFireFlameImg

    const img = image.create(8, 8)

    img.fill(0)

    img.fillRect(3, 0, 2, 2, 7)

    img.fillRect(2, 2, 4, 2, 4)

    img.fillRect(1, 4, 6, 3, 2)

    _relicRingFireFlameImg = img

    return img

}



function _relicRingOfFireDamageEnemy(ringId: number, eIndex: number, enemy: Sprite, srcHi: number, dmg: number): void {

    if (eIndex < 0 || !enemy || (enemy.flags & sprites.Flag.Destroyed)) return

    const lastRing = sprites.readDataNumber(enemy, RELIC_EFFECT_RING_ENEMY_HIT_KEY) | 0

    if ((lastRing | 0) === (ringId | 0)) return

    sprites.setDataNumber(enemy, RELIC_EFFECT_RING_ENEMY_HIT_KEY, ringId | 0)



    const hit: EnemyHitPacket = {

        family: FAMILY.INTELLECT,

        sourceTag: "RELIC_RING_FIRE",

    }

    applyDamageToEnemyIndex(eIndex, dmg | 0, srcHi | 0, hit)

}



function _relicSpawnRingOfFire(hi: number, hero: Sprite): void {

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return

    const ringId = (_relicRingFireNextId++ | 0) || 1

    const cx = hero.x

    const cy = hero.y

    const radius = RELIC_RING_OF_FIRE_RADIUS | 0

    const rSq = radius * radius

    const dmg = RELIC_RING_OF_FIRE_DAMAGE | 0



    // Immediate burst for enemies already in the ring.

    for (let i = 0; i < enemies.length; i++) {

        const e = enemies[i]

        if (!e || (e.flags & sprites.Flag.Destroyed)) continue

        if (distSqPointToSprite(cx, cy, e) <= rSq) {

            _relicRingOfFireDamageEnemy(ringId, i, e, hi, dmg)

        }

    }



    const count = RELIC_RING_OF_FIRE_FLAME_COUNT | 0

    _installEffectDebugOnce()
    _effectDebugMark(ringId | 0, "request", {
        effect: "ring_of_fire",
        hi: hi | 0,
        skin: RELIC_RING_OF_FIRE_SKIN_ID,
        dir: sprites.readDataString(hero, HERO_DATA.DIR) || sprites.readDataString(hero, "dir") || "down"
    })

    const dir = sprites.readDataString(hero, HERO_DATA.DIR) || sprites.readDataString(hero, "dir") || "down"
    const img = _relicRingOfFireFlameImage()

    for (let i = 0; i < count; i++) {

        const angle = (Math.PI * 2 * i) / count

        const fx = cx + Math.cos(angle) * radius

        const fy = cy + Math.sin(angle) * radius

        const flame = sprites.create(img, SpriteKind.RelicEffect)
        sprites.setDataNumber(flame, EFFECT_DEBUG_ID_KEY, ringId | 0)

        flame.x = fx

        flame.y = fy

        flame.z = 200

        flame.lifespan = RELIC_RING_OF_FIRE_LIFESPAN_MS | 0

        sprites.setDataString(flame, "effectSkin", RELIC_RING_OF_FIRE_SKIN_ID)
        sprites.setDataString(flame, "effectDir", dir)
        sprites.setDataNumber(flame, RELIC_EFFECT_RING_RING_ID_KEY, ringId | 0)

        sprites.setDataNumber(flame, RELIC_EFFECT_RING_SRC_HI_KEY, hi | 0)

        sprites.setDataNumber(flame, RELIC_EFFECT_RING_DMG_KEY, dmg)

    }

}



function _relicRainbowMaskFromStep(step: number): number {

    const s = step | 0

    if (s <= 0) return 0

    if (s >= 4) return RELIC_RAINBOW_FULL_MASK

    return ((1 << s) - 1) | 0

}



function _relicRainbowExpectedFamilyForStep(step: number): number {

    const s = step | 0

    if (s === 0) return FAMILY.STRENGTH | 0

    if (s === 1) return FAMILY.AGILITY | 0

    if (s === 2) return FAMILY.INTELLECT | 0

    if (s === 3) return FAMILY.HEAL | 0 // "W" = Wisdom/Heal in this engine

    return -1

}



function _relicRainbowAdvanceStep(currentStep: number, committedFamily: number): number {

    const fam = committedFamily | 0

    const step = currentStep | 0



    // If correct next step, advance

    const expected = _relicRainbowExpectedFamilyForStep(step) | 0

    if (expected >= 0 && fam === expected) return (step + 1) | 0



    // Otherwise, restart only if the new move is Strength (start of sequence)

    if (fam === (FAMILY.STRENGTH | 0)) return 1

    return 0

}



function _relicUiCeilSeconds(remainMs: number): number {

    const r = remainMs | 0

    if (r <= 0) return 0

    return Math.idiv((r + 999), 1000) | 0

}







const _relicOwnedByPid: { [pid: string]: string[] } = {

    // Dev default: player 1 has all starter relics so the DOM can render/test

    "1": [

        RELIC_IDS.ENERGY_SHIELD,

        RELIC_IDS.RING_OF_FIRE,

        RELIC_IDS.ETHEREAL_SHROUD,

        RELIC_IDS.RAINBOW_SCEPTER,

        RELIC_IDS.LANTERN_OF_LIFE,

    ],

}



const _relicUiStateByPid: { [pid: string]: { [relicId: string]: RelicUiState } } = {

    // Runtime-derived UI state is computed on snapshot build; leave this empty by default.

    "1": {},

}



function _relicDbgEnsurePid(pid: number): void {

    const k = String(pid | 0)

    if (!_relicOwnedByPid[k]) _relicOwnedByPid[k] = []

    if (!_relicUiStateByPid[k]) _relicUiStateByPid[k] = {}

    _relicEnsureRuntimeForPid(pid | 0)

}



function _relicHasPid(pid: number, relicId: string): boolean {

    const rid = String(relicId || "")

    if (!rid) return false

    _relicDbgEnsurePid(pid)

    const list = _relicOwnedByPid[String(pid | 0)]

    if (!list || list.length <= 0) return false

    return list.indexOf(rid) >= 0

}

function _relicApplyLoafOfBread(pid: number): void {

    const hi = _relicResolveHeroIndexForPid(pid | 0)

    if (hi < 0 || hi >= heroes.length) return

    const hero = heroes[hi]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return

    const add = RELIC_LOAF_OF_BREAD_HP_BONUS | 0

    if (add <= 0) return

    let maxHp = sprites.readDataNumber(hero, HERO_DATA.MAX_HP) | 0

    if (maxHp <= 0) maxHp = sprites.readDataNumber(hero, HERO_DATA.HP) | 0

    if (maxHp <= 0) maxHp = 1

    const nextMax = (maxHp + add) | 0

    sprites.setDataNumber(hero, HERO_DATA.MAX_HP, nextMax)

    const hp = sprites.readDataNumber(hero, HERO_DATA.HP) | 0

    const nextHp = Math.min(nextMax, (hp + add) | 0) | 0

    sprites.setDataNumber(hero, HERO_DATA.HP, nextHp)

    updateHeroHPBar(hi)

}

function _relicGrantToPid(pid: number, relicId: string, source: string): boolean {

    const rid = String(relicId || "")

    if (!rid) return false

    _relicDbgEnsurePid(pid)

    const list = _relicOwnedByPid[String(pid | 0)]

    if (!list) return false

    if (list.indexOf(rid) >= 0) return false

    list.push(rid)

    if (rid === RELIC_IDS.LOAF_OF_BREAD) {

        _relicApplyLoafOfBread(pid | 0)

    }

    console.log("[RELIC][GRANT]", { pid: pid | 0, relicId: rid, source: String(source || "") })

    return true

}

function getOwnedRelicIdsForPid(pid: number): string[] {

    _relicDbgEnsurePid(pid)

    const ids = _relicOwnedByPid[String(pid | 0)]

    return ids ? ids.slice() : []

}



function getRelicUiStateByIdForPid(pid: number): { [relicId: string]: RelicUiState } {

    _relicDbgEnsurePid(pid)



    const k = String(pid | 0)

    const owned = getOwnedRelicIdsForPid(pid)

    const now = game.runtime() | 0



    const base = _relicUiStateByPid[k] || {}

    const out: { [relicId: string]: RelicUiState } = {}



    // Start with defaults for every owned relic

    for (let i = 0; i < owned.length; i++) {

        const rid = owned[i]

        if (!rid) continue

        const st = base[rid]

        out[rid] = st ? st : { disabled: false }

    }



    // Overlay dynamic UI state derived from runtime for the starter relics.

    const rt = _relicEnsureRuntimeForPid(pid | 0)



    // A) Energy Shield: regen-driven cornerCount

    if (out[RELIC_IDS.ENERGY_SHIELD]) {

        const shieldNow = _relicUpdateEnergyShield(pid, now) | 0

        out[RELIC_IDS.ENERGY_SHIELD] = {

            disabled: (shieldNow | 0) <= 0,

            cornerCount: shieldNow | 0,

        }

    }



    // B) Ring of Fire: ready once per floor

    if (out[RELIC_IDS.RING_OF_FIRE]) {

        const ready = !!rt.ringOfFireReady

        out[RELIC_IDS.RING_OF_FIRE] = {

            disabled: !ready,

            cornerCount: ready ? 1 : undefined,

        }

    }



    // C) Ethereal Shroud: cooldown-driven disabled + cornerCount (seconds remaining)

    if (out[RELIC_IDS.ETHEREAL_SHROUD]) {

        const readyAt = rt.shroudReadyAtMs | 0

        const disabled = (readyAt > 0 && now < readyAt)

        const remain = disabled ? _relicUiCeilSeconds((readyAt - now) | 0) : 0

        out[RELIC_IDS.ETHEREAL_SHROUD] = {

            disabled: disabled,

            cornerCount: disabled ? (remain | 0) : undefined,

        }

    }



    // D) Rainbow Scepter: glyph tracking + throb when armed

    if (out[RELIC_IDS.RAINBOW_SCEPTER]) {

        const mask = _relicRainbowMaskFromStep(rt.rainbowStep | 0) | 0

        out[RELIC_IDS.RAINBOW_SCEPTER] = {

            disabled: false,

            glyphText: RELIC_RAINBOW_GLYPH_TEXT,

            glyphLitMask: mask,

            throb: !!rt.rainbowArmed,

        }

    }



    // E) Lantern of Life: one-time charge + alt icon + disabled

    if (out[RELIC_IDS.LANTERN_OF_LIFE]) {

        const charges = rt.lanternCharges | 0

        const usedUp = charges <= 0

        out[RELIC_IDS.LANTERN_OF_LIFE] = {

            disabled: usedUp,

            cornerCount: charges,

            useAltIcon: usedUp,

        }

    }



    return out

}



function appendRelicsToSnapshot(snap: any, pid: number): void {

    if (!snap || !snap.ready) return



    const ownedRelicIds = getOwnedRelicIdsForPid(pid)

    const stateById = getRelicUiStateByIdForPid(pid)



    // Only include state for owned relics (keeps snapshot small + matches contract)

    const filteredState: any = {}

    for (let i = 0; i < ownedRelicIds.length; i++) {

        const rid = ownedRelicIds[i]

        if (!rid) continue

        filteredState[rid] = stateById[rid] ? stateById[rid] : { disabled: false }

    }



    snap.relics = {

        ownedRelicIds,

        relicUiStateById: filteredState,

    }



    // Offer session will be added later; keep field stable for DOM.

    if (snap.offer == null) snap.offer = null



    // Next-floor choice session (Wing Boots analog)

    if (_relicNextFloorChoice.active) {

        snap.floorChoice = {

            activePlayerId: _relicNextFloorChoice.activePid | 0,

            nextFloorIndex: _relicNextFloorChoice.nextFloorIndex | 0,

            title: String(_relicNextFloorChoice.title || "Choose Next Floor"),

            options: (_relicNextFloorChoice.options || []).slice(0, 2),

            selectedIndex: _relicNextFloorChoice.selectedIndex | 0,

            canControl: ((pid | 0) === (_relicNextFloorChoice.activePid | 0)),

        }

    } else {

        if (snap.floorChoice == null) snap.floorChoice = null

    }

}



function appendShopToSnapshot(snap: any, pid: number, hi: number): void {

    if (!snap || !snap.ready) return

    const items = _shopUiBuildItemsForPid(pid | 0, hi | 0)

    const list = items || []

    snap.shop = {
        title: "Shop",
        items: list,
        selectedIndex: (snap.uiSel | 0) || 0,
        open: ((snap.uiMode | 0) === HERO_UI_MODE.SHOP),
        soldOut: (list.length <= 0),
    }

}

